//! AOT Runtime Library Template
//!
//! 这是AOT编译器使用的完整运行时库模板。
//! 实现了PHP值类型系统和所有必需的运算符函数。
//!
//! ## 设计原则
//! 1. **零依赖**：除了Zig标准库，不依赖任何其他模块
//! 2. **内存安全**：使用引用计数管理内存，防止泄漏
//! 3. **性能优化**：使用NaN boxing技术，48位整数快速路径
//! 4. **PHP语义**：严格遵循PHP 8.5的类型转换和运算规则
//!
//! @ownership TRANSFER (Value类型通过引用计数管理)
//! @thread-safety ISOLATED (每个编译的程序独立运行)
//! @memory-model Reference Counting with Cycle Detection

const std = @import("std");
const builtin = @import("builtin");
const Allocator = std.mem.Allocator;
const concurrency = @import("concurrency_runtime.zig");
const array_ops_shared = @import("array_ops_shared.zig");
const nanbox_abi = @import("nanbox_abi.zig");
pub const profiler = @import("profiler.zig");
pub const flamegraph = @import("flamegraph.zig");
pub const pprof = @import("pprof.zig");

// ============================================================================
// PHP 自述（★F-101/R-265：版本与 OS 常量的**单一来源**，禁再散落字面量）
// ============================================================================
const PHP_VER_MAJOR: i64 = 8;
const PHP_VER_MINOR: i64 = 5;
const PHP_VER_RELEASE: i64 = 8;
const PHP_VER_EXTRA: []const u8 = "";
const PHP_VER_STRING: []const u8 = "8.5.8";
const PHP_VER_ID: i64 = PHP_VER_MAJOR * 10000 + PHP_VER_MINOR * 100 + PHP_VER_RELEASE;

/// `PHP_OS`：按目标平台计算（PHP 实测：macOS ⇒ "Darwin"、Linux ⇒ "Linux"、Windows ⇒ "WINNT"）。
const PHP_OS_NAME: []const u8 = switch (builtin.os.tag) {
    .macos => "Darwin",
    .ios => "Darwin",
    .linux => "Linux",
    .windows => "WINNT",
    .freebsd => "FreeBSD",
    .openbsd => "OpenBSD",
    .netbsd => "NetBSD",
    .dragonfly => "DragonFly",
    .illumos => "SunOS",
    else => @tagName(builtin.os.tag),
};

/// `PHP_OS_FAMILY`：PHP 实测分类（Darwin 单列；BSD 各族统一 "BSD"；Solaris 家族 "Solaris"）。
const PHP_OS_FAMILY_NAME: []const u8 = switch (builtin.os.tag) {
    .macos, .ios => "Darwin",
    .linux => "Linux",
    .windows => "Windows",
    .freebsd, .openbsd, .netbsd, .dragonfly => "BSD",
    .illumos => "Solaris",
    else => "Unknown",
};

// ============================================================================
// 随机数辅助函数（替代 std.crypto.random，兼容 Zig 0.16）
// ============================================================================

/// 填充缓冲区以密码学安全的随机字节
fn getRandomBytes(buf: []u8) void {
    if (builtin.os.tag == .linux) {
        // Linux: 使用 getrandom 系统调用
        std.c.getrandom(buf.ptr, buf.len, 0);
    } else {
        // macOS/BSD: 使用 arc4random_buf
        std.c.arc4random_buf(buf.ptr, buf.len);
    }
}

/// 生成指定范围内的随机整数（含两端）
fn getRandomIntRange(comptime T: type, at_least: T, at_most: T) T {
    if (at_most == at_least) return at_least;
    var buf: [@sizeOf(T)]u8 = undefined;
    getRandomBytes(&buf);
    const rand_val = std.mem.readInt(T, &buf, .little);
    const range = @as(u64, @intCast(at_most)) - @as(u64, @intCast(at_least)) + 1;
    return at_least + @as(T, @intCast(@as(u64, @intCast(rand_val)) % range));
}

