fn lookupBuiltinFunction(name: []const u8) ?BuiltinFn {
    return builtin_function_map.get(name);
}

pub fn php_create_closure(name: Value, captures: Value, is_static_val: Value, allocator: Allocator) !Value {
    if (!name.isString()) return error.InvalidClosureName;
    if (!captures.isArray()) return error.InvalidCaptureList;

    const func_name = name.asString().data;
    const caps_arr = captures.asArray();
    const is_static = is_static_val.toBool();

    // Convert PHPArray to []Value slice
    // We need to iterate the array.
    var cap_list = std.ArrayListUnmanaged(Value){ .items = &.{}, .capacity = 0 };
    defer cap_list.deinit(allocator);

    // Assuming captures is a list (indexed 0..N)
    var i: usize = 0;
    while (i < caps_arr.elements.count()) : (i += 1) {
        const key = ArrayKey{ .integer = @intCast(i) };
        if (caps_arr.elements.get(key)) |val| {
            try cap_list.append(allocator, val);
        } else {
            break;
        }
    }

    // Lookup function
    var func_ptr: ?BuiltinFn = null;

    // §8 #6：用户函数名 CI（Closure::fromCallable("dyn") 须命中声明为 Dyn 的函数）
    if (lookupUserFunctionCI(func_name)) |func| {
        func_ptr = func;
    }

    if (func_ptr == null) {
        func_ptr = lookupBuiltinFunction(func_name);
    }

    if (func_ptr == null) return error.UnknownFunction;

    const closure = try PHPClosure.init(allocator, func_ptr.?, cap_list.items);
    // 从元数据注册表设置参数计数
    if (function_meta_registry) |meta_reg| {
        if (meta_reg.get(func_name)) |meta| {
            closure.param_count = meta.param_count;
            closure.required_params = meta.required_params;
            // AOT-CODEGEN-012 F-12b：一并带入形参名（注册表切片的别名）
            closure.param_names = meta.param_names;
            // ★F-155：形参默认值/变参（同一份 registry 切片）
            closure.param_default_values = meta.param_default_values;
            closure.param_default_known = meta.param_default_known;
            closure.param_default_factories = meta.param_default_factories;
            closure.variadic_index = meta.variadic_index;
        }
    }
    closure.is_static = is_static;
    // 捕获当前作用域类：闭包在类方法内定义时自动绑定作用域
    closure.bound_scope = getCurrentScopeClass();
    return Value.initFunction(closure);
}

pub fn php_object_isset(obj_val: Value, property_name_val: Value) !Value {
    // ★F-153（R-243）：非对象接收者一律 false（PHP 8.5.8 实测 int/float/bool/string/array/null 全 false）；
    //   先解引用，避免 `$r = &$obj; isset($r->p)` 被误判成非对象。
    if (!property_name_val.isString()) return Value.initBool(false);
    return Value.initBool(try objectIssetByName(obj_val, property_name_val.asString().data));
}

/// 按属性名判定 isset（供 `php_object_isset` 与 F-151-b 的链中继共用，避免构造临时 Value）。
fn objectIssetByName(obj_val: Value, prop_name: []const u8) !bool {
    var resolved = obj_val;
    while (resolved.isRef()) resolved = resolved.asRef().*;
    if (!Value_isObject(resolved)) return false;

    const obj = Value_asObject(resolved);

    // 属性可见性检查 + __isset 魔术方法回退
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, prop_name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                // 属性声明但不可访问：尝试 __isset 魔术方法
                if (meta.findMethodLookup("__isset")) |lookup| {
                    const name_str = try PHPString.init(runtime_allocator, prop_name);
                    const name_val = Value.initString(name_str);
                    defer name_val.release(runtime_allocator);
                    const args = [_]Value{name_val};
                    const guard = ClassContext.init(meta, lookup.owner);
                    defer guard.deinit();
                    const result = try lookup.method.func(resolved, &args, runtime_allocator);
                    defer result.release(runtime_allocator);
                    return result.toBool();
                }
                return false;
            }
            // ★F-143：已声明属性必须判值——值为 null / 未初始化时 isset=false（原先见声明就 true）
            if (obj.getPropertyDirect(prop_name)) |pv| {
                var actual = pv;
                while (actual.isRef()) actual = actual.asRef().*;
                return !actual.isNull();
            }
            return false;
        } else {
            // 属性未声明：先检查动态属性（直接查 HashMap，不触发 __isset），无则尝试 __isset
            if (obj.properties.get(prop_name)) |pv| {
                var actual = pv;
                while (actual.isRef()) actual = actual.asRef().*;
                return !actual.isNull();
            }
            if (meta.findMethodLookup("__isset")) |lookup| {
                const name_str = try PHPString.init(runtime_allocator, prop_name);
                const name_val = Value.initString(name_str);
                defer name_val.release(runtime_allocator);
                const args = [_]Value{name_val};
                const guard = ClassContext.init(meta, lookup.owner);
                defer guard.deinit();
                const result = try lookup.method.func(resolved, &args, runtime_allocator);
                defer result.release(runtime_allocator);
                return result.toBool();
            }
            return false;
        }
    }

    return obj.hasProperty(prop_name);
}

/// empty($obj->prop): 先检查 __isset，若属性不存在则视为空
/// 若 __isset 返回 true（属性存在），再取值判断是否为空
pub fn php_object_empty(obj_val: Value, property_name_val: Value) !Value {
    // ★F-153（R-243）：非对象接收者 empty 恒 true（PHP 8.5.8 实测 int/float/bool/string/array/null 全 true）。
    var resolved = obj_val;
    while (resolved.isRef()) resolved = resolved.asRef().*;
    if (!Value_isObject(resolved)) return Value.initBool(true);

    const obj = Value_asObject(resolved);
    const prop_name = if (property_name_val.isString())
        property_name_val.asString().data
    else
        return Value.initBool(true);

    // 属性存在于 HashMap 中：直接取值判断
    if (obj.properties.get(prop_name)) |val| {
        return Value.initBool(php_empty_val(val));
    }

    // 属性不在 HashMap 中：检查是否声明
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, prop_name) != null) {
            // 已声明但未初始化：视为 null（empty 返回 true）
            return Value.initBool(true);
        }
        // 未声明属性：先调用 __isset
        if (meta.findMethodLookup("__isset")) |lookup| {
            const name_str = try PHPString.init(runtime_allocator, prop_name);
            const name_val = Value.initString(name_str);
            defer name_val.release(runtime_allocator);
            const args = [_]Value{name_val};
            const guard = ClassContext.init(meta, lookup.owner);
            defer guard.deinit();
            const isset_result = try lookup.method.func(resolved, &args, runtime_allocator);
            if (!isset_result.toBool()) {
                // __isset 返回 false：属性不存在，empty 返回 true
                return Value.initBool(true);
            }
            // __isset 返回 true：通过 __get 获取值
            if (meta.findMethodLookup("__get")) |get_lookup| {
                const get_guard = ClassContext.init(meta, get_lookup.owner);
                defer get_guard.deinit();
                const get_result = try get_lookup.method.func(resolved, &args, runtime_allocator);
                return Value.initBool(php_empty_val(get_result));
            }
        }
    }

    return Value.initBool(true);
}

pub fn php_object_unset(obj_val: Value, property_name_val: Value, allocator: Allocator) !Value {
    if (!Value_isObject(obj_val)) return Value.initNull();

    const obj = Value_asObject(obj_val);
    const name = if (property_name_val.isString())
        property_name_val.asString().data
    else {
        const property_name = try property_name_val.toString(allocator);
        defer property_name.release(allocator);
        return try php_object_unset_impl(obj_val, obj, property_name.data);
    };

    return try php_object_unset_impl(obj_val, obj, name);
}

fn php_object_unset_impl(obj_val: Value, obj: *PHPObject, name: []const u8) !Value {
    // 属性可见性检查 + __unset 魔术方法回退
    if (obj.class_meta) |meta| {
        if (findPropertyDeclaringClass(meta, name)) |decl| {
            if (!checkPropertyAccess(decl.class, decl.prop)) {
                // 属性声明但不可访问：尝试 __unset 魔术方法
                if (meta.findMethodLookup("__unset")) |lookup| {
                    const name_str = try PHPString.init(runtime_allocator, name);
                    const name_val = Value.initString(name_str);
                    defer name_val.release(runtime_allocator);
                    const args = [_]Value{name_val};
                    const guard = ClassContext.init(meta, lookup.owner);
                    defer guard.deinit();
                    _ = try lookup.method.func(obj_val, &args, runtime_allocator);
                    return Value.initNull();
                }
                var buf: [256]u8 = undefined;
                const vis = if (decl.prop.is_private) "private" else "protected";
                const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, name }) catch "Cannot access property";
                return throwThrowable("Error", msg, runtime_allocator);
            }
        } else {
            // 属性未声明：尝试 __unset 魔术方法
            if (meta.findMethodLookup("__unset")) |lookup| {
                const name_str = try PHPString.init(runtime_allocator, name);
                const name_val = Value.initString(name_str);
                defer name_val.release(runtime_allocator);
                const args = [_]Value{name_val};
                const guard = ClassContext.init(meta, lookup.owner);
                defer guard.deinit();
                _ = try lookup.method.func(obj_val, &args, runtime_allocator);
                return Value.initNull();
            }
        }
    }

    _ = try obj.unsetProperty(name);
    return Value.initNull();
}

