/// 检查是否是某个类的子类
/// AOT-CODEGEN-012 R-131：is_a —— 对象实例/子类判定；allow_string 时类名字符串亦可。
/// 类名 CI（经 findClass 规范化）。
pub fn php_is_a(value: Value, class_name: Value, allow_string: Value) !Value {
    if (!class_name.isString()) return Value.initBool(false);
    const target_meta = findClass(class_name.asString().data) orelse return Value.initBool(false);
    const target = target_meta.name;

    if (Value_isObject(value)) {
        const obj = Value_asObject(value);
        if (std.mem.eql(u8, obj.class_name, target)) return Value.initBool(true);
        if (obj.class_meta) |meta| {
            if (meta.isSubclassOf(target)) return Value.initBool(true);
            if (meta.implementsInterface(target)) return Value.initBool(true);
        }
        return Value.initBool(false);
    }
    if (allow_string.toBool() and value.isString()) {
        const src_meta = findClass(value.asString().data) orelse return Value.initBool(false);
        if (std.mem.eql(u8, src_meta.name, target)) return Value.initBool(true);
        if (src_meta.isSubclassOf(target)) return Value.initBool(true);
        if (src_meta.implementsInterface(target)) return Value.initBool(true);
        return Value.initBool(false);
    }
    return Value.initBool(false);
}

/// AOT-CODEGEN-012 R-131：class_alias —— 为已注册类建立别名（同一 ClassMeta 双键）。
/// 源类未注册 ⇒ false（PHP 8 行为为 Warning/ValueError 族，此处从简）。
pub fn php_class_alias(from: Value, to: Value) !Value {
    if (!from.isString() or !to.isString()) return Value.initBool(false);
    const from_meta = findClass(from.asString().data) orelse {
        // PHP 8：源类缺失 ⇒ PHP Warning + false（emitWarning 自带位置后缀，norm 对齐）
        emitWarning(std.fmt.allocPrint(runtime_allocator, "Class \"{s}\" not found", .{from.asString().data}) catch "Class not found");
        return Value.initBool(false);
    };
    if (class_registry) |*registry| {
        try registry.put(to.asString().data, from_meta);
    }
    return Value.initBool(true);
}

/// AOT-CODEGEN-012 R-136：class_uses —— 返回类使用的 trait 名数组。
/// AOT 将 trait 在 parse 层展开进类（方法/属性平铺），未保留使用记录 ⇒
/// 无 trait 记录的类返回空 array（与 PHP 对无 trait 类的行为一致）；
/// 有 trait 类的枚举需 ClassMeta 增加 trait 使用记录，登记未实现。
pub fn php_class_uses(value: Value, allocator: Allocator) !Value {
    _ = allocator;
    // 解析目标类：对象取其类名，字符串直接用（CI 规范化经 findClass）
    var class_name: []const u8 = "";
    if (Value_isObject(value)) {
        class_name = Value_asObject(value).class_name;
    } else if (value.isString()) {
        class_name = value.asString().data;
    } else {
        return Value.initBool(false);
    }
    const meta = findClass(class_name) orelse return Value.initBool(false);

    const result = try PHPArray.init(runtime_allocator);
    if (class_trait_uses) |*map| {
        if (map.get(meta.name)) |uses| {
            for (uses.items) |trait_name| {
                const key_str = try PHPString.init(runtime_allocator, trait_name);
                try result.elements.put(.{ .string = key_str }, Value.initString(key_str));
            }
        }
    }
    return Value.initArray(result);
}

pub fn php_is_subclass_of(child: Value, parent: Value, allow_string: Value) !Value {
    _ = allow_string; // ★F-75：见 `php_class_exists` 上方说明（AOT 侧本就拿对象或类名字符串两形）
    // 第一个参数可以是对象或类名字符串
    var child_class_name: []const u8 = undefined;
    var child_meta: ?*const ClassMeta = null;

    if (Value_isObject(child)) {
        const obj = Value_asObject(child);
        child_class_name = obj.class_name;
        child_meta = obj.class_meta;
    } else if (child.isString()) {
        child_class_name = child.asString().data;
        child_meta = findClass(child_class_name);
    } else {
        return Value.initBool(false);
    }

    // 第二个参数必须是类名字符串
    if (!parent.isString()) return Value.initBool(false);
    // AOT-CODEGEN-012 R-131：父类名 CI —— 规范化到注册拼写后再比较
    const parent_raw = parent.asString().data;
    const parent_class_name = if (findClass(parent_raw)) |pm| pm.name else parent_raw;

    // 如果子类元数据不存在，返回 false
    if (child_meta == null) return Value.initBool(false);

    // 检查是否相同（PHP 的 is_subclass_of 不包括自身）
    if (std.mem.eql(u8, child_class_name, parent_class_name)) {
        return Value.initBool(false);
    }

    // 检查继承链
    if (child_meta.?.parent) |parent_meta| {
        if (parent_meta.isSubclassOf(parent_class_name)) {
            return Value.initBool(true);
        }
    }

    // 检查接口实现
    if (child_meta.?.implementsInterface(parent_class_name)) {
        return Value.initBool(true);
    }

    return Value.initBool(false);
}

pub fn is_subclass_of(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    _ = allocator;
    if (args.len < 2) return error.MissingArgument;
    return php_is_subclass_of(args[0], args[1], if (args.len > 2) args[2] else Value.initBool(true));
}

/// instanceof 检查
pub fn php_instanceof(obj_val: Value, class_name: Value) !Value {
    if (!Value_isObject(obj_val)) {
        // 闭包在 PHP 侧就是 Closure 实例 ⇒ object/Closure/mixed 三格必须放行，
        // 与属性位（coercePropertyType）、形参位（checkSingleType）共用同一枚谓词，禁另造口径。
        if (obj_val.isFunction() and class_name.isString() and closureSatisfiesType(class_name.asString().data, obj_val)) {
            return Value.initBool(true);
        }
        return Value.initBool(false);
    }
    if (!class_name.isString()) return Value.initBool(false);

    const obj = Value_asObject(obj_val);
    const name = class_name.asString().data;

    // AOT-CODEGEN-012：类名 CI —— 先把被测名解析到规范注册名（未注册名原样比较，
    // Throwable/Stringable 伪接口特判不受影响），随后所有比较使用规范拼写。
    const canonical = blk: {
        if (findClass(name)) |meta| break :blk meta.name;
        break :blk name;
    };

    // 检查类名直接匹配
    if (std.mem.eql(u8, obj.class_name, canonical)) return Value.initBool(true);

    // 检查继承链和接口
    if (obj.class_meta) |meta| {
        if (meta.isSubclassOf(canonical)) return Value.initBool(true);
        if (meta.implementsInterface(canonical)) return Value.initBool(true);
    }

    // PHP: Throwable 是所有 Exception 和 Error 的基接口
    //（伪接口未注册 ⇒ canonicalization 不覆盖 ⇒ 此处必须 CI 比较，`throwable` 拼写同样命中）
    if (std.ascii.eqlIgnoreCase(canonical, "Throwable")) {
        if (obj.class_meta) |meta| {
            // 检查是否是Exception或Error的子类
            if (meta.isSubclassOf("Exception") or std.mem.eql(u8, obj.class_name, "Exception")) return Value.initBool(true);
            if (meta.isSubclassOf("Error") or std.mem.eql(u8, obj.class_name, "Error")) return Value.initBool(true);
        }
    }

    // PHP 8.0+: 实现了 __toString() 的类自动实现 Stringable 接口（同上：CI 比较）
    if (std.ascii.eqlIgnoreCase(canonical, "Stringable")) {
        if (obj.class_meta) |meta| {
            if (meta.magic_toString != null) return Value.initBool(true);
            if (meta.methods.get("__toString") != null) return Value.initBool(true);
        }
    }

    return Value.initBool(false);
}

/// 获取父类名
/// get_parent_class — 接受对象**或类名字符串**（PHP 两者皆可；★R-281 前只认对象，
///   `get_parent_class("ErrorException")` 恒 false）。
/// ★F-187（R-281 收口，门 C327 t5）：字符串未注册为类／非对象非字符串 ⇒ PHP 抛
///   `TypeError: get_parent_class(): Argument #1 ($object_or_class) must be an object
///    or a valid class name, {type} given`（实测 int 同样抛）；旧版静默 false。
pub fn php_get_parent_class(obj_val: Value, allocator: Allocator) !Value {
    // 对象恒不抛（PHP 对任意对象都有答案）；字符串须注册为类，其余类型直接抛
    if (Value_isObject(obj_val)) {
        const obj = Value_asObject(obj_val);
        const m = obj.class_meta orelse findClass(obj.class_name);
        if (m) |meta| {
            if (meta.parent) |parent| {
                const parent_name = try PHPString.init(allocator, parent.name);
                return Value.initString(parent_name);
            }
        }
        return Value.initBool(false);
    }
    if (obj_val.isString()) {
        if (findClass(obj_val.asString().data)) |meta| {
            if (meta.parent) |parent| {
                const parent_name = try PHPString.init(allocator, parent.name);
                return Value.initString(parent_name);
            }
            return Value.initBool(false);
        }
    }
    {
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "get_parent_class(): Argument #1 ($object_or_class) must be an object or" ++
                " a valid class name, {s} given",
            .{phpArgTypeWord(obj_val)},
        ) catch "get_parent_class(): Argument #1 must be an object or a valid class name";
        // ★F-188：自报抛出帧（未捕获时 PHP 打 `#0 file(line): get_parent_class('arg')`）。
        //   顺序铁律：setException 会清帧 ⇒ 必须在 throwThrowable 之后再自报。
        const thrown = throwThrowable("TypeError", msg, allocator);
        setLastThrowFrame("get_parent_class", &.{obj_val});
        return thrown;
    }
}

/// class_implements — 返回类实现的所有接口
pub fn php_class_implements(class_val: Value, allocator: Allocator) !Value {
    // 解析类名：接受对象或类名字符串
    var class_name: []const u8 = undefined;
    if (Value_isObject(class_val)) {
        const obj = Value_asObject(class_val);
        class_name = obj.class_name;
    } else if (class_val.isString()) {
        class_name = class_val.asString().data;
    } else {
        return Value.initBool(false);
    }

    const meta = findClass(class_name) orelse return Value.initBool(false);

    // 收集所有接口（包括继承链和接口的父接口）
    const arr = try PHPArray.init(allocator);
    errdefer destroyPHPArray(arr, allocator);

    var visited = std.StringHashMap(void).init(allocator);
    defer visited.deinit();

    try collectInterfaces(meta, arr, &visited, allocator);
    return Value.initArray(arr);
}

fn collectInterfaces(meta: *const ClassMeta, arr: *PHPArray, visited: *std.StringHashMap(void), allocator: Allocator) !void {
    // 直接实现的接口
    for (meta.interfaces) |iface| {
        if (visited.contains(iface)) continue;
        try visited.put(iface, {});
        const val_str = try PHPString.init(allocator, iface);
        try arr.push(allocator, Value.initString(val_str));
    }
    // 递归检查接口的父接口
    for (meta.interfaces) |iface| {
        if (class_registry) |reg| {
            if (reg.get(iface)) |iface_meta| {
                try collectInterfaces(iface_meta, arr, visited, allocator);
            }
        }
    }
    // 检查父类
    if (meta.parent) |parent| {
        try collectInterfaces(parent, arr, visited, allocator);
    }
}

pub fn class_implements(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    if (args.len < 1) return error.MissingArgument;
    return php_class_implements(args[0], allocator);
}

/// 检查方法是否存在
pub fn php_method_exists(obj_val: Value, method_name: Value) !Value {
    if (!method_name.isString()) return Value.initBool(false);
    const name = method_name.asString().data;

    if (Value_isObject(obj_val)) {
        const obj = Value_asObject(obj_val);
        if (obj.class_meta) |meta| {
            return Value.initBool(meta.findMethod(name) != null);
        }
    }
    // AOT-CODEGEN-012 R-131：PHP 的 method_exists 亦接受**类名字符串**形态
    //（两级 CI 链：findClass 类名 CI + findMethod 方法名 CI）
    if (obj_val.isString()) {
        if (findClass(obj_val.asString().data)) |meta| {
            return Value.initBool(meta.findMethod(name) != null);
        }
    }
    return Value.initBool(false);
}

pub fn method_exists(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    _ = allocator;
    if (args.len < 2) return error.MissingArgument;
    return php_method_exists(args[0], args[1]);
}

/// 检查属性是否存在
pub fn php_property_exists(obj_val: Value, property_name: Value) !Value {
    if (!property_name.isString()) return Value.initBool(false);
    const name = property_name.asString().data;

    if (Value_isObject(obj_val)) {
        const obj = Value_asObject(obj_val);
        // 首先检查类元数据中是否有该属性声明（包括类型化属性无默认值的情况）
        if (obj.class_meta) |meta| {
            if (findPropertyDeclaringClass(meta, name) != null) return Value.initBool(true);
        }
        // 然后检查对象实例中的动态属性
        return Value.initBool(obj.hasProperty(name));
    }

    // 支持字符串类名: property_exists('ClassName', 'prop')
    if (obj_val.isString()) {
        const class_name = obj_val.asString().data;
        if (findClass(class_name)) |meta| {
            // 检查类元数据中是否有该属性
            if (meta.properties.get(name) != null) return Value.initBool(true);
        }
    }

    return Value.initBool(false);
}

pub fn property_exists(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    _ = allocator;
    if (args.len < 2) return error.MissingArgument;
    return php_property_exists(args[0], args[1]);
}

/// Enum::cases() - 返回所有 case 的数组（保持声明顺序）
fn enumCases(meta: *const ClassMeta, allocator: Allocator) !Value {
    const arr = try PHPArray.init(allocator);
    // 使用 __enum_cases 有序列表
    if (meta.static_properties.get("__enum_cases")) |cases_val| {
        if (cases_val.isArray()) {
            const cases_arr = cases_val.asArray();
            var it = cases_arr.elements.iterator();
            while (it.next()) |entry| {
                const name_val = entry.value_ptr.*;
                if (name_val.isString()) {
                    const name = name_val.asString().data;
                    if (meta.static_properties.get(name)) |case_val| {
                        _ = case_val.retain();
                        try arr.push(allocator, case_val);
                    }
                }
            }
        }
    }
    return Value.initArray(arr);
}

/// Enum::from(value) - 根据 backing value 查找 case，找不到抛 ValueError
fn enumFrom(meta: *const ClassMeta, needle: Value, allocator: Allocator) !Value {
    var it = meta.static_properties.iterator();
    while (it.next()) |entry| {
        const val = entry.value_ptr.*;
        if (Value_isObject(val)) {
            const obj = Value_asObject(val);
            if (obj.getPropertyDirect("value")) |backing| {
                const eq = try php_eq(backing, needle);
                if (eq.asBool()) {
                    _ = val.retain();
                    return val;
                }
            }
        }
    }
    // 抛出 ValueError
    const needle_str = try needle.toString(allocator);
    defer needle_str.release(allocator);
    const msg = try std.fmt.allocPrint(allocator, "{s} is not a valid backing value for enum {s}", .{ needle_str.data, meta.name });
    defer allocator.free(msg);
    try throwThrowableDiscard("ValueError", msg, allocator);
    return Value.initNull();
}

/// Enum::tryFrom(value) - 根据 backing value 查找 case，找不到返回 null
fn enumTryFrom(meta: *const ClassMeta, needle: Value) !Value {
    var it = meta.static_properties.iterator();
    while (it.next()) |entry| {
        const val = entry.value_ptr.*;
        if (Value_isObject(val)) {
            const obj = Value_asObject(val);
            if (obj.getPropertyDirect("value")) |backing| {
                const eq = try php_eq(backing, needle);
                if (eq.asBool()) {
                    _ = val.retain();
                    return val;
                }
            }
        }
    }
    return Value.initNull();
}

/// 调用静态方法
pub fn php_call_static(class_name: []const u8, method_name: []const u8, args: []const Value, allocator: Allocator) !Value {
    return php_call_static_with_ctx(Value.initNull(), class_name, method_name, args, allocator);
}

/// 动态类名静态方法调用：$var::method() — 运行时从 Value 提取类名和方法名
/// args[0] = 类名变量值, args[1] = 方法名 Value, args[2..] = 方法参数
pub fn php_call_static_dynamic(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return error.InvalidArgumentCount;
    const class_name = if (args[0].isString()) args[0].asString().data else "";
    const method_name = if (args[1].isString()) args[1].asString().data else "";
    return php_call_static_with_ctx(Value.initNull(), class_name, method_name, args[2..], allocator);
}

/// 动态静态属性访问：($expr)::$prop
/// args[0] = 类名 Value（字符串）, args[1] = 属性名 Value（字符串）
pub fn php_get_static_property_dynamic(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return error.InvalidArgumentCount;
    const class_name = if (args[0].isString()) args[0].asString().data else "";
    const prop_name = if (args[1].isString()) args[1].asString().data else "";
    _ = allocator;
    return php_get_static_property(class_name, prop_name);
}

/// 动态类常量访问：($expr)::CONSTANT
/// args[0] = 类名 Value（字符串）, args[1] = 常量名 Value（字符串）
pub fn php_get_class_constant_dynamic(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return error.InvalidArgumentCount;
    const class_name = if (args[0].isString()) args[0].asString().data else "";
    const const_name = if (args[1].isString()) args[1].asString().data else "";

    // 特殊处理 ::class
    if (std.mem.eql(u8, const_name, "class")) {
        const str = try PHPString.init(allocator, class_name);
        return Value.initString(str);
    }

    // 类常量存储在 static_properties 中，需遍历继承链查找
    var current_meta: ?*const ClassMeta = findClass(class_name);
    while (current_meta) |meta| {
        if (meta.static_properties.get(const_name)) |val| {
            _ = val.retain();
            return val;
        }
        current_meta = meta.parent;
    }

    return Value.initNull();
}

/// `a` 与 `b` 是否同族（同一类，或其一为另一的祖先）。
/// 实测口径来源：实例方法内写 `Base::bm()`（bm 声明于父类 Base）合法，写异类 `Other::om()` Fatal。
fn classMetaSameFamily(a: *const ClassMeta, b: *const ClassMeta) bool {
    var cur: ?*const ClassMeta = a;
    while (cur) |m| {
        if (m == b) return true;
        cur = m.parent;
    }
    var up: ?*const ClassMeta = b;
    while (up) |m| {
        if (m == a) return true;
        up = m.parent;
    }
    return false;
}

/// 当前类作用域是否与该方法所属类同族（类内用显式类名调用本族非静态方法合法）。
/// 实测：`Sub` 内 `Base::bm()`、`Sub::bm()`（bm 继承自 Base）均合法；`Other` 内 `Base::bm()` ⇒ Fatal。
fn scopeClassMatches(owner: *const ClassMeta) bool {
    const scope = getCurrentScopeClass() orelse return false;
    return classMetaSameFamily(scope, owner);
}

pub fn php_call_static_with_ctx(ctx: Value, class_name: []const u8, method_name: []const u8, args: []const Value, allocator: Allocator) !Value {
    const lookup_meta = blk: {
        if (std.mem.eql(u8, class_name, "self")) {
            break :blk getCurrentScopeClass() orelse {
                // F-134：必须抛 Throwable 对象；throwException 设的是字符串，catch 派发恒不命中 ⇒ 假致命。
                return throwThrowable("Error", "Cannot access \"self\" when no class scope is active", allocator);
            };
        }
        if (std.mem.eql(u8, class_name, "parent")) {
            const scope = getCurrentScopeClass() orelse {
                return throwThrowable("Error", "Cannot access \"parent\" when no class scope is active", allocator);
            };
            break :blk scope.parent orelse {
                // PHP 8.5.8 该形是编译期 Fatal（不可捕获）；AOT 侧保留运行期兜底，措辞对齐 PHP。
                return throwThrowable("Error", "Cannot use \"parent\" when current class scope has no parent", allocator);
            };
        }
        if (std.mem.eql(u8, class_name, "static")) {
            // static:: 回退：先查 called class，再查 scope class
            break :blk getCurrentCalledClass() orelse getCurrentScopeClass() orelse {
                return throwThrowable("Error", "Cannot access \"static\" when no class scope is active", allocator);
            };
        }
        break :blk findClass(class_name) orelse {
            const msg = std.fmt.allocPrint(allocator, "Class \"{s}\" not found", .{class_name}) catch return Value.initNull();
            defer allocator.free(msg);
            return throwThrowable("Error", msg, allocator);
        };
    };

    const called_meta = blk: {
        if (std.mem.eql(u8, class_name, "self") or
            std.mem.eql(u8, class_name, "parent") or
            std.mem.eql(u8, class_name, "static"))
        {
            // 与 lookup_meta 同步回退逻辑
            break :blk getCurrentCalledClass() orelse getCurrentScopeClass() orelse lookup_meta;
        }
        break :blk lookup_meta;
    };

    // 查找方法（静态或实例方法）
    if (lookup_meta.findMethodLookup(method_name)) |lookup| {
        // PHP 8 实测：静态调用非静态方法 ⇒ Error「Non-static method C::m() cannot be called statically」
        //   判据 = **调用处有没有 $this，且其对象类与所属类同族**（十形矩阵 f1…f10，门 P 常驻）：
        //   实例方法内 `K::m()`/`self::m()`/`static::m()`/`parent::bm()`/`Base::bm()` 均合法；
        //   静态方法内 `self::m()`、异类方法内 `Base::bm()`、顶层 `K::m()` 均 Fatal 且必须可捕获。
        //   ctx 由发射侧透传（R-145 起 `.static_method_call` 两支都走 with_ctx）。
        if (!lookup.method.is_static) {
            // 运行期只能用两条近似证据：① 限定符是作用域常量（self/parent/static）；
            // ② 当前类作用域与所属类同族。**不能用 ctx 判 $this**——`php_call_static`
            // 包装层恒传 initNull，改成只看 ctx 会把实例方法内的动态类名调用误判为致命
            //（f11 实测：PHP = 4，改后 AOT 抛 Error ⇒ 假阳性，已回退）。
            // 「静态方法上下文」这一向由发射侧 staticEmitCallIsIllegal 的 has-this 闸门覆盖。
            const scope_qualified = std.mem.eql(u8, class_name, "self") or
                std.mem.eql(u8, class_name, "parent") or
                std.mem.eql(u8, class_name, "static");
            const legal = scope_qualified or scopeClassMatches(lookup.owner);
            if (!legal) {
                const msg = std.fmt.allocPrint(allocator, "Non-static method {s}::{s}() cannot be called statically", .{ lookup.owner.name, method_name }) catch return Value.initNull();
                defer allocator.free(msg);
                return throwThrowable("Error", msg, allocator);
            }
        }
        const guard = ClassContext.init(called_meta, lookup.owner);
        defer guard.deinit();
        return lookup.method.func(ctx, args, allocator);
    }

    // Enum 内置静态方法: cases(), from(), tryFrom()
    if (std.mem.eql(u8, method_name, "cases")) {
        return enumCases(lookup_meta, allocator);
    }
    if (std.mem.eql(u8, method_name, "from")) {
        if (args.len == 0) return error.InvalidArgumentCount;
        return enumFrom(lookup_meta, args[0], allocator);
    }
    if (std.mem.eql(u8, method_name, "tryFrom")) {
        if (args.len == 0) return error.InvalidArgumentCount;
        return enumTryFrom(lookup_meta, args[0]);
    }

    // 调用 __callStatic 魔法函数
    if (lookup_meta.findMethodLookup("__callStatic")) |lookup| {
        const name_str = try PHPString.init(allocator, method_name);
        const name_val = Value.initString(name_str);
        defer name_val.release(allocator);
        const args_arr = try PHPArray.init(allocator);
        for (args) |arg| {
            try args_arr.push(allocator, arg);
        }
        const call_args = [_]Value{ name_val, Value.initArray(args_arr) };
        const guard = ClassContext.init(called_meta, lookup.owner);
        defer guard.deinit();
        return lookup.method.func(Value.initNull(), &call_args, allocator);
    }

    return error.MethodNotFound;
}

/// ★F-74-b：直接以 trait 名访问静态属性（`T::$s`）时，PHP 每次访问发一条 E_DEPRECATED。
///   仅在“属性存在且可见”的路径调用（PHP 对未声明/不可见属性只报 Error，不发弃用）。
///   读改写（`T::$s++` / `T::$s += n`）在 AOT 落成 get+set 两次调用：get 发一条，紧随同位置的 set 去重。
threadlocal var last_trait_static_note_file: []const u8 = "";
threadlocal var last_trait_static_note_line: u32 = 0;
threadlocal var last_trait_static_note_was_get: bool = false;

fn noteTraitStaticPropertyAccess(meta: *const ClassMeta, property_name: []const u8, from_get: bool) void {
    if (!meta.is_trait) return;
    // PHP 只允许通过 trait 名访问 **public** 静态属性；private/protected 直接报 Error、不发弃用。
    const decl = findPropertyDeclaringClass(meta, property_name) orelse return;
    if (!decl.prop.is_public) return;
    if (!from_get and last_trait_static_note_was_get and
        last_trait_static_note_line == src_line and
        std.mem.eql(u8, last_trait_static_note_file, src_file))
    {
        last_trait_static_note_was_get = false;
        return;
    }
    var buf: [512]u8 = undefined;
    const msg = std.fmt.bufPrint(
        &buf,
        "Accessing static trait property {s}::${s} is deprecated, it should only be accessed on a class using the trait",
        .{ meta.name, property_name },
    ) catch return;
    emitDeprecated(msg);
    last_trait_static_note_file = src_file;
    last_trait_static_note_line = src_line;
    last_trait_static_note_was_get = from_get;
}

/// ★F-142：静态属性名的统一解析（self/static/parent 语义与 php_get/set_static_property 一致）。
fn resolveStaticPropertyMeta(class_name: []const u8) ?*ClassMeta {
    if (std.mem.eql(u8, class_name, "self")) {
        if (getCurrentScopeClass()) |scope| {
            if (scope.is_trait) {
                if (getCurrentCalledClass()) |called| return @constCast(called);
            }
            return @constCast(scope);
        }
        return @constCast(getCurrentCalledClass() orelse return null);
    }
    if (std.mem.eql(u8, class_name, "parent")) {
        const scope = getCurrentScopeClass() orelse return null;
        return @constCast(scope.parent orelse return null);
    }
    if (std.mem.eql(u8, class_name, "static")) {
        return @constCast(getCurrentCalledClass() orelse return null);
    }
    return findClass(class_name);
}

/// ★F-142：`isset(G::$p)` —— 缺失/不可见/null 都返回 false；不发 fatal、不发 trait 弃用（非 public）。
pub fn php_isset_static_property(class_val: Value, prop_val: Value) Value {
    if (!class_val.isString() or !prop_val.isString()) return Value.initBool(false);
    const class_name = class_val.asString().data;
    const property_name = prop_val.asString().data;
    const meta = resolveStaticPropertyMeta(class_name) orelse return Value.initBool(false);
    const decl = findPropertyDeclaringClass(meta, property_name) orelse return Value.initBool(false);
    if (!checkPropertyAccess(decl.class, decl.prop)) return Value.initBool(false);
    const val = meta.getStaticProperty(property_name) orelse return Value.initBool(false);
    if (decl.prop.is_public) noteTraitStaticPropertyAccess(meta, property_name, true);
    return Value.initBool(!val.isNull());
}

/// ★F-142：`empty(G::$p)` —— 缺失/不可见按 empty 语义返回 true；存在时复用 php_empty_val。
pub fn php_empty_static_property(class_val: Value, prop_val: Value) Value {
    if (!class_val.isString() or !prop_val.isString()) return Value.initBool(true);
    const class_name = class_val.asString().data;
    const property_name = prop_val.asString().data;
    const meta = resolveStaticPropertyMeta(class_name) orelse return Value.initBool(true);
    const decl = findPropertyDeclaringClass(meta, property_name) orelse return Value.initBool(true);
    if (!checkPropertyAccess(decl.class, decl.prop)) return Value.initBool(true);
    const val = meta.getStaticProperty(property_name) orelse return Value.initBool(true);
    if (decl.prop.is_public) noteTraitStaticPropertyAccess(meta, property_name, true);
    return Value.initBool(php_empty_val(val));
}

/// 获取静态属性
pub fn php_get_static_property(class_name: []const u8, property_name: []const u8) !Value {
    const meta = blk: {
        if (std.mem.eql(u8, class_name, "self")) {
            // trait 中 self:: 静态属性应解析为使用类（called class），而非 trait 自身
            if (getCurrentScopeClass()) |scope| {
                if (scope.is_trait) {
                    if (getCurrentCalledClass()) |called| break :blk called;
                }
                break :blk scope;
            }
            // 如果没有作用域，尝试从调用类获取
            if (getCurrentCalledClass()) |called| {
                break :blk called;
            }
            std.debug.print("ERROR: getCurrentScopeClass() returned null for 'self'\n", .{});
            return error.ClassNotFound;
        }
        if (std.mem.eql(u8, class_name, "parent")) {
            const scope = getCurrentScopeClass() orelse return error.ClassNotFound;
            break :blk scope.parent orelse return error.ClassNotFound;
        }
        if (std.mem.eql(u8, class_name, "static")) {
            break :blk getCurrentCalledClass() orelse return error.ClassNotFound;
        }
        break :blk findClass(class_name) orelse return error.ClassNotFound;
    };

    // 静态属性可见性检查
    if (findPropertyDeclaringClass(meta, property_name)) |decl| {
        if (decl.prop.is_static and !checkPropertyAccess(decl.class, decl.prop)) {
            var buf: [256]u8 = undefined;
            const vis = if (decl.prop.is_private) "private" else "protected";
            const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, property_name }) catch "Cannot access property";
            return throwThrowable("Error", msg, runtime_allocator);
        }
    }

    const val = meta.getStaticProperty(property_name);
    if (val == null) {
        // AOT-CODEGEN-012 R-133：未声明静态属性对齐 PHP —— 可捕获 Error（原先硬错误
        // `ERROR: Property ... not found` 不可捕获且消息形状与 PHP 不同）
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "Access to undeclared static property {s}::${s}",
            .{ meta.name, property_name },
        ) catch "Access to undeclared static property";
        return throwThrowable("Error", msg, runtime_allocator);
    }
    // retain：调用方（代码生成器）会在寄存器释放时 release，
    // 如果不 retain，release 会减少静态属性本身的引用计数，可能导致数据丢失
    if (val) |v| {
        noteTraitStaticPropertyAccess(meta, property_name, true); // ★F-74-b：存在且可见才发
        _ = v.retain();
        return v;
    }
    return Value.initNull();
}

/// 设置静态属性
pub fn php_set_static_property(class_name: []const u8, property_name: []const u8, value: Value) !Value {
    var meta = blk: {
        if (std.mem.eql(u8, class_name, "self")) {
            // trait 中 self:: 静态属性应解析为使用类（called class），而非 trait 自身
            if (getCurrentScopeClass()) |scope| {
                if (scope.is_trait) {
                    if (getCurrentCalledClass()) |called| break :blk @constCast(called);
                }
                break :blk @constCast(scope);
            }
            break :blk @constCast(getCurrentCalledClass() orelse return error.ClassNotFound);
        }
        if (std.mem.eql(u8, class_name, "parent")) {
            const scope = getCurrentScopeClass() orelse return error.ClassNotFound;
            break :blk @constCast(scope.parent orelse return error.ClassNotFound);
        }
        if (std.mem.eql(u8, class_name, "static")) {
            break :blk @constCast(getCurrentCalledClass() orelse return error.ClassNotFound);
        }
        break :blk findClass(class_name) orelse return error.ClassNotFound;
    };

    // 静态属性可见性检查
    if (findPropertyDeclaringClass(meta, property_name)) |decl| {
        if (decl.prop.is_static and !checkPropertyAccess(decl.class, decl.prop)) {
            var buf: [256]u8 = undefined;
            const vis = if (decl.prop.is_private) "private" else "protected";
            const msg = std.fmt.bufPrint(&buf, "Cannot access {s} property {s}::${s}", .{ vis, meta.name, property_name }) catch "Cannot access property";
            return throwThrowable("Error", msg, runtime_allocator);
        }
    }

    // ★F-74-b：属性存在且可访问才发弃用（未声明属性 PHP 只报 Error）
    if (meta.getStaticProperty(property_name) != null) {
        noteTraitStaticPropertyAccess(meta, property_name, false);
    }
    try meta.setStaticProperty(property_name, value);
    return Value.initNull();
}

fn serializeValue(buffer: *std.ArrayListUnmanaged(u8), value: Value, allocator: Allocator) !void {
    if (value.isNull()) {
        try buffer.appendSlice(allocator, "N;");
        return;
    }
    if (value.isBool()) {
        try buffer.print(allocator, "b:{d};", .{if (value.toBool()) @as(i64, 1) else @as(i64, 0)});
        return;
    }
    if (value.isInt()) {
        try buffer.print(allocator, "i:{d};", .{value.toInt()});
        return;
    }
    if (value.isFloat()) {
        try buffer.print(allocator, "d:{d};", .{value.toFloat()});
        return;
    }
    if (value.isString()) {
        const str = value.asString().data;
        try buffer.print(allocator, "s:{d}:\"", .{str.len});
        try buffer.appendSlice(allocator, str);
        try buffer.appendSlice(allocator, "\";");
        return;
    }
    if (value.isArray()) {
        const arr = value.asArray();
        const count = arr.elements.count();
        try buffer.print(allocator, "a:{d}:{{", .{count});
        var it = arr.elements.iterator();
        while (it.next()) |entry| {
            const key = entry.key_ptr.*;
            switch (key) {
                .integer => |i| try buffer.print(allocator, "i:{d};", .{i}),
                .string => |s| {
                    const k = s.data;
                    try buffer.print(allocator, "s:{d}:\"", .{k.len});
                    try buffer.appendSlice(allocator, k);
                    try buffer.appendSlice(allocator, "\";");
                },
            }
            try serializeValue(buffer, entry.value_ptr.*, allocator);
        }
        try buffer.appendSlice(allocator, "}");
        return;
    }
    if (Value_isObject(value)) {
        const obj = Value_asObject(value);
        const class_name = obj.class_name;

        // PHP 8.1+ Enum 序列化: E:<len>:"<ClassName>:<CaseName>";
        if (obj.class_meta) |meta| {
            if (meta.is_enum) {
                const case_name_val = obj.properties.get("name") orelse Value.initNull();
                const case_name = if (case_name_val.isString()) case_name_val.asString().data else "";
                const combined = std.fmt.allocPrint(allocator, "{s}:{s}", .{ class_name, case_name }) catch return error.OutOfMemory;
                defer allocator.free(combined);
                try buffer.print(allocator, "E:{d}:\"{s}\";", .{ combined.len, combined });
                return;
            }
        }

        if (obj.class_meta) |meta| {
            if (meta.magic_serialize) |serializer| {
                const arr_val = try serializer(value, &.{}, allocator);
                defer arr_val.release(allocator);

                if (arr_val.isArray()) {
                    const arr = arr_val.asArray();
                    const count = arr.elements.count();
                    try buffer.print(allocator, "O:{d}:\"", .{class_name.len});
                    try buffer.appendSlice(allocator, class_name);
                    try buffer.print(allocator, "\":{d}:{{", .{count});

                    var it = arr.elements.iterator();
                    while (it.next()) |entry| {
                        const key = entry.key_ptr.*;
                        switch (key) {
                            .integer => |i| try buffer.print(allocator, "i:{d};", .{i}),
                            .string => |s| {
                                const k = s.data;
                                try buffer.print(allocator, "s:{d}:\"", .{k.len});
                                try buffer.appendSlice(allocator, k);
                                try buffer.appendSlice(allocator, "\";");
                            },
                        }
                        try serializeValue(buffer, entry.value_ptr.*, allocator);
                    }
                    try buffer.appendSlice(allocator, "}");
                    return;
                }
            }
        }

        var allow_list: ?*PHPArray = null;
        var allow_val: Value = Value.initNull();
        defer if (!allow_val.isNull()) allow_val.release(allocator);

        if (obj.class_meta) |meta| {
            if (meta.magic_sleep) |sleeper| {
                allow_val = sleeper(value, &.{}, allocator) catch Value.initNull();
                if (allow_val.isArray()) {
                    allow_list = allow_val.asArray();
                }
            }
        }

        const count: usize = if (allow_list) |list| list.elements.count() else obj.properties.count();

        try buffer.print(allocator, "O:{d}:\"", .{class_name.len});
        try buffer.appendSlice(allocator, class_name);
        try buffer.print(allocator, "\":{d}:{{", .{count});

        if (allow_list) |list| {
            var it_allow = list.elements.iterator();
            while (it_allow.next()) |entry| {
                const v = entry.value_ptr.*;
                if (!v.isString()) continue;
                const prop_name = v.asString().data;
                const prop_val = obj.properties.get(prop_name) orelse Value.initNull();

                const full_len: usize = class_name.len + prop_name.len + 2;
                try buffer.print(allocator, "s:{d}:\"", .{full_len});
                try buffer.appendSlice(allocator, &[_]u8{0});
                try buffer.appendSlice(allocator, class_name);
                try buffer.appendSlice(allocator, &[_]u8{0});
                try buffer.appendSlice(allocator, prop_name);
                try buffer.appendSlice(allocator, "\";");

                try serializeValue(buffer, prop_val, allocator);
            }
        } else {
            var it_props = obj.properties.iterator();
            while (it_props.next()) |entry| {
                const prop_name = entry.key_ptr.*;
                const prop_val = entry.value_ptr.*;

                const full_len: usize = class_name.len + prop_name.len + 2;
                try buffer.print(allocator, "s:{d}:\"", .{full_len});
                try buffer.appendSlice(allocator, &[_]u8{0});
                try buffer.appendSlice(allocator, class_name);
                try buffer.appendSlice(allocator, &[_]u8{0});
                try buffer.appendSlice(allocator, prop_name);
                try buffer.appendSlice(allocator, "\";");

                try serializeValue(buffer, prop_val, allocator);
            }
        }

        try buffer.appendSlice(allocator, "}");
        return;
    }

    try buffer.appendSlice(allocator, "N;");
}

pub fn php_serialize(value: Value, allocator: Allocator) !Value {
    var buffer = std.ArrayListUnmanaged(u8){ .items = &.{}, .capacity = 0 };
    defer buffer.deinit(allocator);
    try serializeValue(&buffer, value, allocator);
    const s = try PHPString.init(allocator, buffer.items);
    return Value.initString(s);
}

fn unserializeValue(data: []const u8, pos: *usize, allocator: Allocator) !Value {
    if (pos.* >= data.len) return Value.initNull();
    const type_char = data[pos.*];
    pos.* += 1;

    switch (type_char) {
        'E' => {
            // E:<len>:"<ClassName>:<CaseName>";
            pos.* += 1; // skip ':'
            const colon1 = std.mem.indexOfScalarPos(u8, data, pos.*, ':') orelse data.len;
            const len_str = data[pos.*..colon1];
            pos.* = colon1 + 1; // skip ':'
            const name_len = std.fmt.parseInt(usize, len_str, 10) catch 0;
            pos.* += 1; // skip '"'
            const combined = data[pos.* .. pos.* + name_len];
            pos.* += name_len + 1; // skip combined and '"'
            pos.* += 1; // skip ';'

            // 分割 ClassName:CaseName
            const sep = std.mem.indexOfScalar(u8, combined, ':') orelse return Value.initNull();
            const class_name = combined[0..sep];
            const case_name = combined[sep + 1 ..];

            // 从类静态属性中查找 enum case
            if (findClass(class_name)) |meta| {
                if (meta.static_properties.get(case_name)) |case_val| {
                    return case_val;
                }
            }
            return Value.initNull();
        },
        'N' => {
            pos.* += 1;
            return Value.initNull();
        },
        'b' => {
            pos.* += 1;
            const end = std.mem.indexOfScalarPos(u8, data, pos.*, ';') orelse data.len;
            const bool_str = data[pos.*..end];
            pos.* = end + 1;
            return Value.initBool(std.mem.eql(u8, bool_str, "1"));
        },
        'i' => {
            pos.* += 1;
            const end = std.mem.indexOfScalarPos(u8, data, pos.*, ';') orelse data.len;
            const int_str = data[pos.*..end];
            pos.* = end + 1;
            const v = std.fmt.parseInt(i64, int_str, 10) catch 0;
            return Value.initInt(v);
        },
        'd' => {
            pos.* += 1;
            const end = std.mem.indexOfScalarPos(u8, data, pos.*, ';') orelse data.len;
            const float_str = data[pos.*..end];
            pos.* = end + 1;
            const v = std.fmt.parseFloat(f64, float_str) catch 0;
            return Value.initFloat(v);
        },
        's' => {
            pos.* += 1;
            const colon = std.mem.indexOfScalarPos(u8, data, pos.*, ':') orelse data.len;
            const len_str = data[pos.*..colon];
            pos.* = colon + 1;
            const len = std.fmt.parseInt(usize, len_str, 10) catch 0;
            pos.* += 1;
            const str_val = data[pos.* .. pos.* + len];
            pos.* += len + 2;
            const ps = try PHPString.init(allocator, str_val);
            return Value.initString(ps);
        },
        'a' => {
            pos.* += 1;
            const count_end = std.mem.indexOfScalarPos(u8, data, pos.*, ':') orelse data.len;
            const count_str = data[pos.*..count_end];
            pos.* = count_end + 1;
            const count = std.fmt.parseInt(usize, count_str, 10) catch 0;
            pos.* += 1;

            const arr = try PHPArray.init(allocator);
            const arr_val = Value.initArray(arr);

            var i: usize = 0;
            while (i < count) : (i += 1) {
                const key_val = try unserializeValue(data, pos, allocator);
                const val = try unserializeValue(data, pos, allocator);
                defer key_val.release(allocator);
                defer val.release(allocator);

                const key: ArrayKey = if (key_val.isString())
                    ArrayKey{ .string = key_val.asString() }
                else
                    ArrayKey{ .integer = key_val.toInt() };

                try arr.set(allocator, key, val);
            }

            pos.* += 1;
            return arr_val;
        },
        'O' => {
            pos.* += 1; // skip ':'
            const colon1 = std.mem.indexOfScalarPos(u8, data, pos.*, ':') orelse data.len;
            const len_str = data[pos.*..colon1];
            pos.* = colon1 + 1; // skip ':'
            const name_len = std.fmt.parseInt(usize, len_str, 10) catch 0;
            pos.* += 1; // skip '"'
            const class_name = data[pos.* .. pos.* + name_len];
            pos.* += name_len + 1; // skip class_name and '"'
            pos.* += 1; // skip ':'
            const colon2 = std.mem.indexOfScalarPos(u8, data, pos.*, ':') orelse data.len;
            const count_str = data[pos.*..colon2];
            pos.* = colon2 + 1; // skip ':'
            const count = std.fmt.parseInt(usize, count_str, 10) catch 0;
            pos.* += 1; // skip '{'

            const class_name_copy = try allocator.dupe(u8, class_name);
            defer allocator.free(class_name_copy);
            const obj_val = try php_object_new(class_name_copy, allocator);
            const obj = Value_asObject(obj_val);

            const data_arr = try PHPArray.init(allocator);
            const data_arr_val = Value.initArray(data_arr);
            defer data_arr_val.release(allocator);

            var i: usize = 0;
            while (i < count) : (i += 1) {
                const key_val = try unserializeValue(data, pos, allocator);
                const val = try unserializeValue(data, pos, allocator);

                if (!key_val.isString()) {
                    key_val.release(allocator);
                    val.release(allocator);
                    continue;
                }
                const raw_key = key_val.asString().data;
                var prop_name: []const u8 = raw_key;
                if (raw_key.len > 0 and raw_key[0] == 0) {
                    if (std.mem.indexOfScalarPos(u8, raw_key, 1, 0)) |nul2| {
                        if (nul2 + 1 <= raw_key.len) {
                            prop_name = raw_key[nul2 + 1 ..];
                        }
                    }
                }

                const prop_str = try PHPString.init(allocator, prop_name);
                const prop_key = ArrayKey{ .string = prop_str };
                try data_arr.set(allocator, prop_key, val);

                // 释放key_val，val已经被data_arr持有
                key_val.release(allocator);
            }

            pos.* += 1; // skip '}'

            if (obj.class_meta) |meta| {
                if (meta.magic_unserialize) |unser_fn| {
                    const args = [_]Value{data_arr_val};
                    _ = try unser_fn(obj_val, &args, allocator);
                    return obj_val;
                }
            }

            var it = data_arr.elements.iterator();
            while (it.next()) |entry| {
                if (entry.key_ptr.* == .string) {
                    const k = entry.key_ptr.string.data;
                    try obj.setProperty(k, entry.value_ptr.*);
                }
            }

            if (obj.class_meta) |meta| {
                if (meta.magic_wakeup) |wake| {
                    _ = wake(obj_val, &.{}, allocator) catch {};
                }
            }

            return obj_val;
        },
        else => return Value.initNull(),
    }
}

pub fn php_unserialize(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgumentType;
    const data = str.asString().data;
    var pos: usize = 0;
    return unserializeValue(data, &pos, allocator);
}

/// 检查是否是对象
pub fn php_is_object(val: Value) !Value {
    // AOT 的闭包是独立 .function tag，但 PHP 侧闭包就是 Closure 实例
    return Value.initBool(Value_isObject(val) or val.isFunction());
}

/// 获取对象的类名
pub fn php_get_class(obj_val: Value, allocator: Allocator) !Value {
    if (obj_val.isFunction()) {
        return Value.initString(try PHPString.init(allocator, "Closure"));
    }
    if (!Value_isObject(obj_val)) {
        return Value.initBool(false);
    }

    const obj = Value_asObject(obj_val);
    const class_name_str = try PHPString.init(allocator, obj.class_name);
    return Value.initString(class_name_str);
}

pub fn get_class(ctx: Value, args: []const Value, allocator: Allocator) anyerror!Value {
    _ = ctx;
    if (args.len < 1) return error.MissingArgument;
    return php_get_class(args[0], allocator);
}

// ============================================================================
// 异常处理
// ============================================================================

/// 当前异常（全局状态）
/// 注意：这是一个简化的异常处理机制
/// 在真实的PHP实现中，异常应该是线程局部的
// var current_exception: ?Value = null; // 已在文件顶部定义为 threadlocal

/// 设置当前异常
///
/// @param exception 异常Value
// pub fn setException(exception: Value) void { // 已在文件顶部定义
//     current_exception = exception;
// }

/// 获取当前异常
///
/// @return 当前异常，如果没有异常返回null
pub fn getCurrentException() ?Value {
    if (has_exception) return current_exception;
    return null;
}

/// 清除当前异常
pub fn clearException() void {
    if (has_exception) {
        current_exception.release(runtime_allocator);
        current_exception = Value.initNull();
        has_exception = false;
    }
}

/// finally 体执行完后放回「进入 finally 时已 pending」的异常（AOT-CODEGEN-012 F-22）。
/// 进入 finally 前 IR 发 `peek_exception`（自带 retain ⇒ saved 自持一份引用）+ `clear_exception`，
/// 这样体内每条语句都能正常跑完（PHP 语义：finally 必须整块执行完才传播），块尾再交还。
/// 三个分支的所有权要与发射器的「调用后 hasException() ⇒ 清理并 release 该寄存器」路径配平：
///   · saved 为 null ⇒ 进入时无 pending 异常，且调用后检查为假 ⇒ 寄存器不会被清理，故不持任何引用
///   · 已有 pending ⇒ 体内新抛优先（PHP 语义）⇒ **不碰引用**，寄存器那份交给发射器的清理路径 release
///   · 否则 ⇒ 先 retain 一份交全局（setException 收走所有权），此后调用后检查为真，
///     发射器清掉寄存器自己那份 ⇒ 各持一份，既不泄漏也不双释放
/// 返回 `!void` 是 `may_raise = true` 的要求（发射出的语句形如 `_ = try runtime.php_restoreException(…)`）。
pub fn php_restoreException(saved: Value) !void {
    if (saved.isNull()) return;
    if (has_exception) return;
    _ = saved.retain();
    setException(saved);
}

/// 抛出异常
///
/// @param message 异常消息
/// @param allocator 内存分配器
/// @return 异常Value
pub fn throwException(message: []const u8, allocator: Allocator) !Value {
    const msg_str = try PHPString.init(allocator, message);
    const exception = Value.initString(msg_str);
    setException(exception);
    return exception;
}

/// 抛出并丢弃返回的字符串异常引用（setException 已另持一份）
pub fn throwExceptionDiscard(message: []const u8, allocator: Allocator) !void {
    const ex = try throwException(message, allocator);
    ex.release(allocator);
}

/// 同上，用于没有错误返回通道的站点
pub fn throwExceptionDiscardCatch(message: []const u8, allocator: Allocator) void {
    const ex = throwException(message, allocator) catch return;
    ex.release(allocator);
}

/// 抛出并丢弃返回的异常对象引用（setException 已另持一份）。
/// 不接收返回值的站点必须走这里；PHPObject.init 的那份引用若没人 release 就永久泄漏。
pub fn throwThrowableDiscard(class_name: []const u8, message: []const u8, allocator: Allocator) !void {
    const ex = try throwThrowable(class_name, message, allocator);
    ex.release(allocator);
}

/// 同上，用于没有错误返回通道的站点（分配失败保持原有的静默吞掉口径）
pub fn throwThrowableDiscardCatch(class_name: []const u8, message: []const u8, allocator: Allocator) void {
    const ex = throwThrowable(class_name, message, allocator) catch return;
    ex.release(allocator);
}

pub fn throwThrowable(class_name: []const u8, message: []const u8, allocator: Allocator) !Value {
    const obj = if (findClass(class_name)) |meta|
        try PHPObject.initWithMeta(allocator, meta)
    else
        try PHPObject.init(allocator, class_name);
    const exception = Value_initObject(obj);
    const msg_str = try PHPString.init(allocator, message);
    const msg_val = Value.initString(msg_str);
    defer msg_val.release(allocator);
    try obj.setProperty("message", msg_val);
    setException(exception);
    return exception;
}

/// ★F-134：`...$x` 解包操作数不可遍历时的 TypeError。
/// PHP 8.5.8 实测措辞：bool 打 `true`/`false`，对象打类名（`stdClass`/`Closure`），其余用通用名表。
fn throwUnpackTypeError(src: Value, allocator: Allocator) !Value {
    var buf: [256]u8 = undefined;
    const given = if (src.isBool())
        (if (src.toBool()) "true" else "false")
    else
        phpGetValueTypeName(src);
    const msg = std.fmt.bufPrint(&buf, "Only arrays and Traversables can be unpacked, {s} given", .{given}) catch
        "Only arrays and Traversables can be unpacked";
    return throwThrowable("TypeError", msg, allocator);
}

/// never 返回类型检查：never 函数不应正常返回，调用此函数即抛出 TypeError
pub fn php_never_return(func_name_val: Value) !Value {
    const func_name = if (func_name_val.isString()) func_name_val.asString().data else "unknown";
    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "{s}(): never-returning function must not implicitly return", .{func_name}) catch "never-returning function must not implicitly return";
    return throwThrowable("TypeError", msg, runtime_allocator);
}

/// 检查是否有异常
///
/// @return 如果有异常返回true
pub fn hasException() bool {
    return has_exception;
}

// ============================================================================
// 时间函数（从VM实现复用）
// ============================================================================

/// time - 返回当前Unix时间戳
pub fn php_time() Value {
    const timestamp = unixTimestamp();
    return Value.initInt(timestamp);
}

/// getdate - 获取日期/时间信息
pub fn php_getdate(ts_val: Value, allocator: Allocator) !Value {
    // ★F-62f 余量（R-254）：#1 ?int；null ⇒ 当前时间（原语义）。
    const ts_ok = requireOptionalNumParam("getdate", 1, "timestamp", .nullable_int_param, ts_val) orelse return Value.initNull();
    const timestamp = if (ts_ok.isNull()) unixTimestamp() else ts_ok.toInt();
    const epoch = std.time.epoch.EpochSeconds{ .secs = @intCast(@as(u64, @bitCast(timestamp))) };
    const day_seconds = epoch.getDaySeconds();
    const epoch_day = epoch.getEpochDay();
    const year_day = epoch_day.calculateYearDay();
    const month_day = year_day.calculateMonthDay();

    const year = year_day.year;
    const month: i64 = @intCast(@intFromEnum(month_day.month));
    const day: i64 = @intCast(month_day.day_index + 1);
    const hours: i64 = @intCast(day_seconds.getHoursIntoDay());
    const minutes: i64 = @intCast(day_seconds.getMinutesIntoHour());
    const seconds_val: i64 = @intCast(day_seconds.getSecondsIntoMinute());
    // 计算星期几：1970-01-01是周四(4)，PHP wday: 0=周日,1=周一,...,6=周六
    const days_since_epoch: i64 = @intCast(epoch_day.day);
    const wday: i64 = @mod(days_since_epoch + 4, 7);
    // 一年中的第几天：year_day.day 是0-based，PHP yday也是0-based
    const yday: i64 = @intCast(year_day.day);

    const arr = try PHPArray.init(allocator);
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "seconds")), Value.initInt(seconds_val));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "minutes")), Value.initInt(minutes));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "hours")), Value.initInt(hours));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "mday")), Value.initInt(day));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "wday")), Value.initInt(wday));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "mon")), Value.initInt(month));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "year")), Value.initInt(@intCast(@as(i32, year))));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "yday")), Value.initInt(yday));
    const weekday_names = [_][]const u8{ "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" };
    const month_names = [_][]const u8{ "", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" };
    const wday_idx = @as(usize, @intCast(@mod(wday, 7)));
    const mon_idx = @as(usize, @intCast(@min(@max(month, 1), 12)));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "weekday")), Value.initString(try PHPString.init(allocator, weekday_names[wday_idx])));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "month")), Value.initString(try PHPString.init(allocator, month_names[mon_idx])));
    try arr.setByValue(allocator, Value.initInt(0), Value.initInt(timestamp));
    return Value.initArray(arr);
}

pub fn php_idate(format_val: Value, ts_val: Value, allocator: Allocator) !Value {
    _ = allocator;
    if (!format_val.isString()) return Value.initInt(0);
    const fmt = format_val.asString().data;
    if (fmt.len == 0) return Value.initInt(0);
    // ★F-62f 余量（R-254）：#2 ?int；null ⇒ 当前时间（原语义）。
    const ts_ok = requireOptionalNumParam("idate", 2, "timestamp", .nullable_int_param, ts_val) orelse return Value.initInt(0);
    const timestamp = if (ts_ok.isNull()) unixTimestamp() else ts_ok.toInt();
    const epoch = std.time.epoch.EpochSeconds{ .secs = @intCast(@as(u64, @bitCast(timestamp))) };
    const day_seconds = epoch.getDaySeconds();
    const epoch_day = epoch.getEpochDay();
    const year_day = epoch_day.calculateYearDay();
    const month_day = year_day.calculateMonthDay();
    const hours: i64 = @intCast(day_seconds.getHoursIntoDay());
    const minutes: i64 = @intCast(day_seconds.getMinutesIntoHour());
    const secs: i64 = @intCast(day_seconds.getSecondsIntoMinute());
    const day: i64 = @intCast(month_day.day_index + 1);
    const month: i64 = @intCast(@intFromEnum(month_day.month));
    const year: i64 = @intCast(@as(i32, year_day.year));
    const days_since_epoch: i64 = @intCast(epoch_day.day);
    const wday: i64 = @mod(days_since_epoch + 4, 7);
    const yday: i64 = @intCast(year_day.day);
    const result: i64 = switch (fmt[0]) {
        'Y' => year,
        'y' => @mod(year, 100),
        'n', 'm' => month,
        'j', 'd' => day,
        'H' => hours,
        'h' => blk: {
            const h = @mod(hours, 12);
            break :blk if (h == 0) 12 else h;
        },
        'i' => minutes,
        's' => secs,
        'w', 'l' => wday,
        'z' => yday,
        'U' => timestamp,
        else => 0,
    };
    return Value.initInt(result);
}

/// mktime(hour, minute, second, month, day, year) -> Unix timestamp
pub fn php_mktime(hour: Value, minute: Value, second: Value, month: Value, day: Value, year: Value) !Value {
    // ★F-62f 余量（R-254）：#1 int（不可空）＋#2–#6 ?int 的类型校验；null 语义保持不变。
    const hour_ok = requireOptionalNumParam("mktime", 1, "hour", .int_param, hour) orelse return Value.initNull();
    const minute_ok = requireOptionalNumParam("mktime", 2, "minute", .nullable_int_param, minute) orelse return Value.initNull();
    const second_ok = requireOptionalNumParam("mktime", 3, "second", .nullable_int_param, second) orelse return Value.initNull();
    const month_ok = requireOptionalNumParam("mktime", 4, "month", .nullable_int_param, month) orelse return Value.initNull();
    const day_ok = requireOptionalNumParam("mktime", 5, "day", .nullable_int_param, day) orelse return Value.initNull();
    const year_ok = requireOptionalNumParam("mktime", 6, "year", .nullable_int_param, year) orelse return Value.initNull();
    // ★F-131：PHP 的 6 个形参全部可省略（min=1），省略与显式 null 一律取**当前本地时间**的对应分量。
    //   本模板的时间族统一按 UTC 解释（DateTimeFormatter 同口径），故这里取 UTC 分量。
    const any_null = hour_ok.isNull() or minute_ok.isNull() or second_ok.isNull() or
        month_ok.isNull() or day_ok.isNull() or year_ok.isNull();
    var now_mi: i64 = 0;
    var now_s: i64 = 0;
    var now_mon: i64 = 1;
    var now_d: i64 = 1;
    var now_y: i64 = 1970;
    if (any_null) {
        const now = @max(unixTimestamp(), 0);
        const epoch = std.time.epoch.EpochSeconds{ .secs = @intCast(now) };
        const ds = epoch.getDaySeconds();
        const yd = epoch.getEpochDay().calculateYearDay();
        const md = yd.calculateMonthDay();
        now_mi = @intCast(ds.getMinutesIntoHour());
        now_s = @intCast(ds.getSecondsIntoMinute());
        now_mon = @intCast(md.month.numeric());
        now_d = @intCast(md.day_index + 1);
        now_y = @intCast(yd.year);
    }
    // ★F-131 真值实测：mktime 的 #1 `$hour` 是**不可空 int**（null ⇒ 0，并带一条 Deprecated），
    //   与 #2–#6 的 `?int`（null ⇒ 当前分量）不同口径。
    const h = if (hour_ok.isNull()) @as(i64, 0) else hour_ok.toInt();
    const mi = if (minute_ok.isNull()) now_mi else minute_ok.toInt();
    const sec = if (second_ok.isNull()) now_s else second_ok.toInt();
    const mon_in = if (month_ok.isNull()) now_mon else month_ok.toInt();
    const day_in = if (day_ok.isNull()) now_d else day_ok.toInt();
    var y = if (year_ok.isNull()) now_y else year_ok.toInt();
    // PHP: 0-69 => 2000-2069, 70-100 => 1970-2000
    if (y >= 0 and y <= 69) y += 2000;
    if (y >= 70 and y <= 100) y += 1900;

    // ★F-131：libc mktime 会把任意月/日归一化（mon=0→上一年 12 月、mon=13→下一年 1 月、day=0/32 同理）。
    //   先把 (year, mon) 折成正规年月，再按 Howard Hinnant 的 days_from_civil 求纪元日数。
    const total_months = y * 12 + (mon_in - 1);
    const cy = @divFloor(total_months, 12);
    const cm = @mod(total_months, 12) + 1; // 1..12
    const yy = if (cm <= 2) cy - 1 else cy;
    const era = @divFloor(yy, 400);
    const yoe = yy - era * 400; // 0..399
    const mp = if (cm > 2) cm - 3 else cm + 9; // Mar=0 .. Feb=11
    const doy = @divFloor(153 * mp + 2, 5) + (day_in - 1);
    const doe = yoe * 365 + @divFloor(yoe, 4) - @divFloor(yoe, 100) + doy;
    const days = era * 146097 + doe - 719468;
    const ts = days * 86400 + h * 3600 + mi * 60 + sec;
    return Value.initInt(ts);
}

/// checkdate(month, day, year) -> bool: 验证日期合法性
pub fn php_checkdate(month: Value, day: Value, year: Value) !Value {
    // ★F-128（R-253）：三枚 `int` 形参统一走 F-62f 的 `requireNumParam` 契约；配合注册表
    //   `.may_raise = true`，helper 置的 TypeError 才会在调用点被路由（PHP 实测：
    //   `checkdate(): Argument #N ($month|$day|$year) must be of type int, Foo given`）。
    const m_ok = requireNumParam("checkdate", 1, "month", .int_param, month) orelse return Value.initNull();
    const d_ok = requireNumParam("checkdate", 2, "day", .int_param, day) orelse return Value.initNull();
    const y_ok = requireNumParam("checkdate", 3, "year", .int_param, year) orelse return Value.initNull();
    const m = m_ok.toInt();
    const d = d_ok.toInt();
    const y = y_ok.toInt();
    if (y < 1 or y > 32767) return Value.initBool(false);
    if (m < 1 or m > 12) return Value.initBool(false);
    if (d < 1) return Value.initBool(false);
    const days_in_month = [_]i64{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    const is_leap = (@rem(y, 4) == 0 and @rem(y, 100) != 0) or (@rem(y, 400) == 0);
    var max_day = days_in_month[@as(usize, @intCast(m - 1))];
    if (m == 2 and is_leap) max_day = 29;
    return Value.initBool(d <= max_day);
}

/// gmdate(format, timestamp=null) -> string: UTC格式化（与date相同，时间戳已是UTC）
pub fn php_gmdate(format: Value, timestamp: Value, allocator: Allocator) !Value {
    if (!format.isString()) return Value.initString(try PHPString.init(allocator, ""));
    const ts = if (timestamp.isNull())
        unixTimestamp()
    else if (timestamp.isInt())
        timestamp.asInt()
    else if (timestamp.isFloat())
        @as(i64, @intFromFloat(timestamp.asFloat()))
    else
        unixTimestamp();
    return formatPhpDateValue(ts, format.asString().data, allocator);
}

/// microtime - 返回当前时间（带微秒）
///
/// @param get_as_float 是否返回浮点数格式
/// @param allocator 内存分配器
/// @return 字符串格式 "0.microseconds seconds" 或浮点数时间戳
pub fn php_microtime(get_as_float: Value, allocator: Allocator) !Value {
    const now_ns = nanoTimestamp();
    const sec = @divTrunc(now_ns, std.time.ns_per_s);
    const usec = @divTrunc(@mod(now_ns, std.time.ns_per_s), std.time.ns_per_us);

    // 检查是否返回浮点数
    const as_float = if (get_as_float.isBool())
        get_as_float.asBool()
    else if (get_as_float.isInt())
        get_as_float.asInt() != 0
    else
        false;

    if (as_float) {
        // 返回浮点数时间戳
        const float_time = @as(f64, @floatFromInt(sec)) + @as(f64, @floatFromInt(usec)) / 1000000.0;
        return Value.initFloat(float_time);
    } else {
        // 返回字符串格式 "0.microseconds seconds"
        const formatted = try std.fmt.allocPrint(allocator, "0.{d:0>6} {d}", .{ usec, sec });
        defer allocator.free(formatted);
        const result = try PHPString.init(allocator, formatted);
        return Value.initString(result);
    }
}

fn isLeapYearTop(year: i64) bool {
    return (@rem(year, 4) == 0 and @rem(year, 100) != 0) or (@rem(year, 400) == 0);
}

fn formatPhpDateValue(timestamp: i64, format_str: []const u8, allocator: Allocator) !Value {
    const epoch_seconds: u64 = @intCast(@max(@as(i64, 0), timestamp));
    const epoch = std.time.epoch.EpochSeconds{ .secs = epoch_seconds };
    const day_seconds = epoch.getDaySeconds();
    const epoch_day = epoch.getEpochDay();
    const year_day = epoch_day.calculateYearDay();
    const month_day = year_day.calculateMonthDay();
    const days_since_epoch: i64 = @intCast(epoch_day.day);
    const wday: usize = @intCast(@mod(days_since_epoch + 4, 7)); // 0=Sun
    const year: i64 = @intCast(@as(i32, year_day.year));
    const month: usize = @intCast(month_day.month.numeric());
    const day: usize = @intCast(month_day.day_index + 1);
    const hour: usize = @intCast(day_seconds.getHoursIntoDay());
    const minute: usize = @intCast(day_seconds.getMinutesIntoHour());
    const second: usize = @intCast(day_seconds.getSecondsIntoMinute());

    const weekday_full = [_][]const u8{ "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" };
    const weekday_short = [_][]const u8{ "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
    const month_full = [_][]const u8{ "", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" };
    const month_short = [_][]const u8{ "", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };

    var aw2 = std.Io.Writer.Allocating.initCapacity(allocator, format_str.len * 2) catch return Value.initNull();
    defer aw2.deinit();

    var i: usize = 0;
    while (i < format_str.len) : (i += 1) {
        const c = format_str[i];
        switch (c) {
            // Year
            'Y' => try aw2.writer.print("{d:0>4}", .{@as(u32, @intCast(year))}),
            'y' => try aw2.writer.print("{d:0>2}", .{@as(u32, @intCast(@mod(year, 100)))}),
            // Month
            'm' => try aw2.writer.print("{d:0>2}", .{month}),
            'n' => try aw2.writer.print("{d}", .{month}),
            'F' => try aw2.writer.writeAll(month_full[month]),
            'M' => try aw2.writer.writeAll(month_short[month]),
            // Day
            'd' => try aw2.writer.print("{d:0>2}", .{day}),
            'j' => try aw2.writer.print("{d}", .{day}),
            // Weekday
            'l' => try aw2.writer.writeAll(weekday_full[wday]),
            'D' => try aw2.writer.writeAll(weekday_short[wday]),
            'w' => try aw2.writer.print("{d}", .{wday}),
            'N' => try aw2.writer.print("{d}", .{if (wday == 0) @as(usize, 7) else wday}), // ISO: Mon=1..Sun=7
            // ISO week number
            'W' => {
                const doy: i64 = @as(i64, @intCast(year_day.day)) + 1;
                const iso_wday: i64 = if (wday == 0) 7 else @as(i64, @intCast(wday));
                var week: i64 = @divFloor(doy - iso_wday + 10, 7);
                if (week < 1) {
                    week = if (isLeapYearTop(year - 1)) 53 else 52;
                } else if (week > 52) {
                    const days_in_year: i64 = if (isLeapYearTop(year)) 366 else 365;
                    if (doy - iso_wday > days_in_year - 1) week = 1;
                }
                try aw2.writer.print("{d:0>2}", .{@as(u32, @intCast(week))});
            },
            // Hour
            'H' => try aw2.writer.print("{d:0>2}", .{hour}),
            'G' => try aw2.writer.print("{d}", .{hour}),
            'h' => try aw2.writer.print("{d:0>2}", .{if (@mod(hour, 12) == 0) @as(usize, 12) else @mod(hour, 12)}),
            'g' => try aw2.writer.print("{d}", .{if (@mod(hour, 12) == 0) @as(usize, 12) else @mod(hour, 12)}),
            'A' => try aw2.writer.writeAll(if (hour < 12) "AM" else "PM"),
            'a' => try aw2.writer.writeAll(if (hour < 12) "am" else "pm"),
            // Minute / second
            'i' => try aw2.writer.print("{d:0>2}", .{minute}),
            's' => try aw2.writer.print("{d:0>2}", .{second}),
            // Timestamp
            'U' => try aw2.writer.print("{d}", .{timestamp}),
            // Day of year (0-based in PHP)
            'z' => try aw2.writer.print("{d}", .{year_day.day}),
            // ISO 8601 date: 2024-01-15T12:30:45+00:00
            'c' => {
                try aw2.writer.print("{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}+00:00", .{
                    @as(u32, @intCast(year)), month, day, hour, minute, second,
                });
            },
            // RFC 2822 date: Mon, 15 Jan 2024 12:30:45 +0000
            'r' => {
                try aw2.writer.print("{s}, {d:0>2} {s} {d:0>4} {d:0>2}:{d:0>2}:{d:0>2} +0000", .{
                    weekday_short[wday], day, month_short[month], @as(u32, @intCast(year)), hour, minute, second,
                });
            },
            // Timezone offset with colon: +00:00
            'P' => try aw2.writer.writeAll("+00:00"),
            // Timezone offset without colon: +0000
            'O' => try aw2.writer.writeAll("+0000"),
            // Timezone abbreviation
            'T' => try aw2.writer.writeAll("UTC"),
            // Timezone offset in seconds
            'Z' => try aw2.writer.writeAll("0"),
            // English ordinal suffix for day
            'S' => {
                const suffix: []const u8 = switch (day) {
                    1, 21, 31 => "st",
                    2, 22 => "nd",
                    3, 23 => "rd",
                    else => "th",
                };
                try aw2.writer.writeAll(suffix);
            },
            // Number of days in the month
            't' => {
                const days_in_month: usize = switch (month) {
                    1, 3, 5, 7, 8, 10, 12 => 31,
                    4, 6, 9, 11 => 30,
                    2 => if (isLeapYearTop(year)) 29 else 28,
                    else => 30,
                };
                try aw2.writer.print("{d}", .{days_in_month});
            },
            // Leap year (1/0)
            'L' => try aw2.writer.print("{d}", .{@as(usize, if (isLeapYearTop(year)) 1 else 0)}),
            // ISO year (simplified: same as Y for UTC)
            'o' => try aw2.writer.print("{d:0>4}", .{@as(u32, @intCast(year))}),
            // Escape
            '\\' => {
                i += 1;
                if (i < format_str.len) try aw2.writer.writeAll(format_str[i .. i + 1]);
            },
            else => try aw2.writer.writeAll(&[_]u8{c}),
        }
    }

    return Value.initString(try PHPString.init(allocator, aw2.written()));
}

/// date - 格式化日期时间
///
/// 注意：这是一个简化实现，仅支持基本格式
/// 完整的PHP date()函数支持更多格式选项
///
/// @param format 格式字符串
/// @param timestamp 时间戳（可选，默认当前时间）
/// @param allocator 内存分配器
/// @return 格式化后的日期字符串
pub fn php_date(format: Value, timestamp: Value, allocator: Allocator) !Value {
    if (!format.isString()) {
        return Value.initString(try PHPString.init(allocator, ""));
    }

    // 获取时间戳
    const ts = if (timestamp.isNull())
        unixTimestamp()
    else if (timestamp.isInt())
        timestamp.asInt()
    else if (timestamp.isFloat())
        @as(i64, @intFromFloat(timestamp.asFloat()))
    else
        unixTimestamp();

    return formatPhpDateValue(ts, format.asString().data, allocator);
}

// ============================================================================
// 随机数函数（MT19937实现，PHP兼容）
// ============================================================================

/// MT19937状态
const MT19937 = struct {
    state: [624]u32 = undefined,
    index: usize = 624,

    fn init(seed: u32) MT19937 {
        var mt = MT19937{};
        mt.state[0] = seed;
        var i: usize = 1;
        while (i < 624) : (i += 1) {
            mt.state[i] = 1812433253 *% (mt.state[i - 1] ^ (mt.state[i - 1] >> 30)) +% @as(u32, @intCast(i));
        }
        mt.index = 624;
        return mt;
    }

    fn generate(self: *MT19937) u32 {
        if (self.index >= 624) {
            self.twist();
        }
        var y = self.state[self.index];
        self.index += 1;

        y ^= (y >> 11);
        y ^= (y << 7) & 0x9D2C5680;
        y ^= (y << 15) & 0xEFC60000;
        y ^= (y >> 18);

        return y;
    }

    fn twist(self: *MT19937) void {
        var i: usize = 0;
        while (i < 624) : (i += 1) {
            const x = (self.state[i] & 0x80000000) + (self.state[(i + 1) % 624] & 0x7FFFFFFF);
            var xA = x >> 1;
            if ((x & 1) != 0) {
                xA ^= 0x9908B0DF;
            }
            self.state[i] = self.state[(i + 397) % 624] ^ xA;
        }
        self.index = 0;
    }
};

threadlocal var mt_state: ?MT19937 = null;

fn nextRandom() u64 {
    if (mt_state == null) {
        mt_state = MT19937.init(@intCast(@as(u64, @intCast(unixTimestamp())) & 0xFFFFFFFF));
    }
    return @as(u64, mt_state.?.generate());
}

/// rand - 生成随机整数
///
/// @param min 最小值（可选）
/// @param max 最大值（可选）
/// @return 随机整数
pub fn php_rand(min: Value, max: Value) !Value {
    if (min.isNull() and max.isNull()) {
        // 无参数：返回 0 到 RAND_MAX (PHP uses generate() >> 1)
        const random = nextRandom();
        return Value.initInt(@as(i64, @intCast(random >> 1)));
    }

    // ★F-62f 接线（门 BLT 段 H b173/b174）：实测 `rand(): Argument #N ($min|$max) must be of type int, Foo given`。
    //   ★用 requireOptionalNumParam 而非 requireNumParam：两枚形参在 PHP 都带默认值，
    //   而省略的形参在本调用约定里同样是 null ⇒ 若走必填支路，`rand(10)` 会替没写的 `$max` 多印一句 Passing-null Deprecated。
    //   代价与 b72 同档（显式 `rand(1,null)` 的 Deprecated 不发），已登记在 helper 注释。
    const min_ok = requireOptionalNumParam("rand", 1, "min", .int_param, min) orelse return Value.initNull();
    const max_ok = requireOptionalNumParam("rand", 2, "max", .int_param, max) orelse return Value.initNull();

    const min_val = min_ok.toInt();
    const max_val = max_ok.toInt();

    if (min_val > max_val) {
        return Value.initInt(min_val);
    }

    const range = @as(u64, @intCast(max_val - min_val + 1));
    const random = nextRandom() % range;

    return Value.initInt(min_val + @as(i64, @intCast(random)));
}

/// mt_rand - 生成随机整数（Mersenne Twister）
///
/// 注意：这是简化实现，使用与rand()相同的生成器
/// 完整实现应该使用真正的MT19937算法
///
/// @param min 最小值（可选）
/// @param max 最大值（可选）
/// @return 随机整数
pub fn php_mt_rand(min: Value, max: Value) !Value {
    // 确保mt_state已初始化
    if (mt_state == null) {
        mt_state = MT19937.init(@intCast(@as(u64, @intCast(unixTimestamp())) & 0xFFFFFFFF));
    }

    // mt_rand() - 无参数，返回0到MT_RAND_MAX
    // mt_rand(min, max) - 返回min到max之间的随机数
    if (min.isNull() and max.isNull()) {
        // 无参数：返回0到2147483647 (PHP uses generate() >> 1)
        return Value.initInt(@intCast(mt_state.?.generate() >> 1));
    }
    return php_rand(min, max);
}

/// srand - 设置随机数种子
///
/// @param seed 种子值（可选）
fn applySrandArgs(fn_name: []const u8, seed: Value, mode: Value) void {
    // ★F-62f 余量（R-232）：#1 ?int seed／#2 int mode；Foo ⇒ TypeError。
    //   ★mode 仅做类型/接受性校验：MT_RAND_PHP(1) 的序列未实现（F-145），当前一律 MT19937。
    const seed_ok = requireOptionalNumParam(fn_name, 1, "seed", .nullable_int_param, seed) orelse return;
    const mode_ok = requireOptionalNumParam(fn_name, 2, "mode", .int_param, mode) orelse return;
    // ★F-145：PHP 8.5 对 MT_RAND_PHP(1) 每次调用发一条 Deprecated（双流）；序列差异另见 F-145-b。
    const mode_val: i64 = if (mode_ok.isNull()) 0 else mode_ok.toInt();
    if (mode_val == 1) {
        emitDeprecated("The MT_RAND_PHP variant of Mt19937 is deprecated");
    }
    if (seed_ok.isNull()) {
        mt_state = MT19937.init(@intCast(@as(u64, @intCast(unixTimestamp())) & 0xFFFFFFFF));
    } else {
        mt_state = MT19937.init(@intCast(@as(u64, @intCast(@abs(seed_ok.toInt()))) & 0xFFFFFFFF));
    }
}

pub fn php_srand(seed: Value, mode: Value) !Value {
    applySrandArgs("srand", seed, mode);
    return Value.initNull();
}

/// mt_srand - 设置MT随机数种子
///
/// @param seed 种子值（可选）
pub fn php_mt_srand(seed: Value, mode: Value) !Value {
    applySrandArgs("mt_srand", seed, mode);
    return Value.initNull();
}

/// mt_getrandmax - 返回 mt_rand() 的最大值
pub fn php_mt_getrandmax() !Value {
    return Value.initInt(2147483647);
}

/// random_int - 生成密码学安全的随机整数
///
/// @param min 最小值
/// @param max 最大值
/// @return 随机整数
pub fn php_random_int(min: Value, max: Value) !Value {
    // ★F-62f 接线（门 BLT 段 H b175）：实测 `random_int(): Argument #1 ($min) must be of type int, Foo given`。
    //   与 rand 相反，这两枚在 PHP **无默认值** ⇒ 走必填支路（requireNumParam）。
    //   ★下面 `min_val > max_val ⇒ error.InvalidRange` 是另一枚面：实测 PHP 给
    //   `ValueError: random_int(): Argument #1 ($min) must be less than or equal to argument #2 ($max)`，本批不动（工单 §104.3）。
    const min_ok = requireNumParam("random_int", 1, "min", .int_param, min) orelse return Value.initNull();
    const max_ok = requireNumParam("random_int", 2, "max", .int_param, max) orelse return Value.initNull();
    const min_val = min_ok.toInt();
    const max_val = max_ok.toInt();

    // ★F-126（R-229）：PHP 8 对 min>max 抛可捕获 ValueError（原先 Zig error.InvalidRange 外逸）
    if (min_val > max_val) {
        return throwThrowable("ValueError", "random_int(): Argument #1 ($min) must be less than or equal to argument #2 ($max)", runtime_allocator);
    }

    // 使用密码学安全的随机数生成器
    const random_val = getRandomIntRange(i64, min_val, max_val);
    return Value.initInt(random_val);
}

/// random_bytes - 生成密码学安全的随机字节
///
/// @param length 字节数
/// @param allocator 内存分配器
/// @return 随机字节字符串
pub fn php_random_bytes(length: Value, allocator: Allocator) !Value {
    // ★F-62f 第三批：Foo ⇒ TypeError；≤0 ⇒ 可捕获 ValueError（原 error.InvalidLength 外逸）
    const len_ok = requireNumParam("random_bytes", 1, "length", .int_param, length) orelse return Value.initNull();
    const len = len_ok.toInt();

    if (len <= 0) {
        return throwThrowable("ValueError", "random_bytes(): Argument #1 ($length) must be greater than 0", runtime_allocator);
    }

    const byte_len = @as(usize, @intCast(len));
    const buffer = try allocator.alloc(u8, byte_len);
    errdefer allocator.free(buffer);

    // 填充密码学安全的随机字节
    getRandomBytes(buffer);

    const result = try PHPString.init(allocator, buffer);
    allocator.free(buffer);
    return Value.initString(result);
}

// ============================================================================
// 扩展数组函数
// ============================================================================

/// array_shift - 移除并返回数组的第一个元素
pub fn php_array_shift(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initNull();

    const php_arr = arr.asArray();
    const v = array_ops_shared.shift(ArrayKey, Value, @TypeOf(php_arr.elements), allocator, &php_arr.elements, &php_arr.next_index) orelse return Value.initNull();
    return v;
}

/// array_shift 的引用版本：接收 *Value，内部做 COW 分离并回写
/// 用于 byref 场景：array_shift($stack) 中 $stack 可能是 Ref
pub fn php_array_shift_ref(arr_ptr: *Value, allocator: Allocator) !Value {
    const target = val_deref(arr_ptr);
    if (!target.*.isArray()) return Value.initNull();
    php_ensure_array_separated(target);
    const php_arr = target.*.asArray();
    const v = array_ops_shared.shift(ArrayKey, Value, @TypeOf(php_arr.elements), allocator, &php_arr.elements, &php_arr.next_index) orelse return Value.initNull();
    return v;
}

/// array_unshift - 在数组开头添加元素
pub fn php_array_unshift(arr: Value, values: []const Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initInt(0);

    const php_arr = arr.asArray();
    try array_ops_shared.unshift(ArrayKey, Value, @TypeOf(php_arr.elements), allocator, &php_arr.elements, &php_arr.next_index, values);
    return Value.initInt(@intCast(php_arr.count()));
}

/// array_search - 在数组中搜索值并返回键
pub fn php_array_search(needle: Value, haystack: Value, strict: Value) !Value {
    if (!haystack.isArray()) return Value.initBool(false);

    // ★F-149（R-238）：#3 bool $strict
    const strict_ok = requireBoolParam("array_search", 3, "strict", strict) orelse return Value.initBool(false);

    const arr = haystack.asArray();
    var it = arr.elements.iterator();
    const is_strict = strict_ok.toBool();

    while (it.next()) |entry| {
        const val = entry.value_ptr.*;
        const found = if (is_strict) (try php_identical(needle, val)).asBool() else (try php_eq(needle, val)).asBool();
        if (found) {
            // 返回键
            return switch (entry.key_ptr.*) {
                .integer => |k| Value.initInt(k),
                .string => |k| blk: {
                    k.retain();
                    break :blk Value.initString(k);
                },
            };
        }
    }

    return Value.initBool(false);
}

/// array_sum - 计算数组元素的总和（packed int 快速路径 + SIMD 向量化）
pub fn php_array_sum(arr: Value) !Value {
    // ★F-62（R-172 c 段）：实参非数组 ⇒ 参数类型校验（实测 `array_sum(5)` ⇒
    //   `array_sum(): Argument #1 ($array) must be of type array, int given`、`array_sum($o)` ⇒ 同句式 `Foo given`），
    //   旧写法静默返回 0。
    _ = requireArrayParam("array_sum", 1, "array", arr) orelse return Value.initNull();

    const php_arr = arr.asArray();

    if (php_arr.elements.mixed == null) {
        const items = php_arr.elements.packed_values.items;
        if (items.len == 0) return Value.initInt(0);

        var all_int = true;
        for (items) |v| {
            if (!v.isInt()) {
                all_int = false;
                break;
            }
        }

        if (all_int) {
            return Value.initInt(fastPackedIntSum(items));
        }
    }

    var sum_int: i64 = 0;
    var sum_float: f64 = 0;
    var has_float = false;

    var it = php_arr.elements.iterator();
    while (it.next()) |entry| {
        // ★元素级口径（`classifyArrayNumElem`）：array／object ⇒ Warning 后**整枚跳过**；
        //   非数值串 ⇒ Warning 后**计入 0**；前导数值串 ⇒ `A non-numeric value encountered` 后计入前缀；
        //   bool／null ⇒ 静默计入 1／0；数值串 ⇒ 按 int／float 语法计入（实测 `array_sum(["1e3"])`＝double 1000.0，
        //   旧写法用 `toInt()` 把它落成 int 1000 ⇒ 结果类型错）。
        const classified = classifyArrayNumElem("array_sum", "Addition", entry.value_ptr.*);
        switch (classified) {
            .skip => {},
            .use => |v| {
                if (v.isFloat()) {
                    has_float = true;
                    sum_float += v.asFloat();
                } else {
                    sum_int += v.asInt();
                }
            },
        }
    }

    if (has_float) {
        return Value.initFloat(sum_float + @as(f64, @floatFromInt(sum_int)));
    }
    return Value.initInt(sum_int);
}

/// packed int 数组快速求和：comptime @Vector SIMD 优化
fn fastPackedIntSum(items: []const Value) i64 {
    // comptime 自动选择最优向量宽度
    const vec_len = comptime std.simd.suggestVectorLength(i64) orelse 4;
    const V = @Vector(vec_len, i64);

    var accum: V = @splat(0);
    var i: usize = 0;
    const len = items.len;

    // 主循环：向量化累加
    const aligned = len & ~@as(usize, vec_len - 1);
    while (i < aligned) : (i += vec_len) {
        var batch: V = undefined;
        inline for (0..vec_len) |j| {
            batch[j] = items[i + j].toInt();
        }
        accum +%= batch;
    }

    // 水平归约
    var sum: i64 = @reduce(.Add, accum);

    // 处理剩余元素
    while (i < len) : (i += 1) {
        sum +%= items[i].toInt();
    }

    return sum;
}

/// array_product - 计算数组元素的乘积
pub fn php_array_product(arr: Value) !Value {
    // ★F-62（R-172 c 段）：同 `array_sum`，非数组实参 ⇒ 参数类型校验（实测 `array_product(5)` ⇒ `int given`）。
    _ = requireArrayParam("array_product", 1, "array", arr) orelse return Value.initNull();

    const php_arr = arr.asArray();
    if (php_arr.count() == 0) return Value.initInt(1);

    var product: f64 = 1;
    var it = php_arr.elements.iterator();

    while (it.next()) |entry| {
        // ★元素级口径与 `array_sum` 同一 helper（措辞换成 `Multiplication`）：
        //   实测 `array_product([2, [1]])`＝2（array **跳过**）、`array_product([2, "abc"])`＝0（非数值串**计入 0**）、
        //   `array_product([2, "5a"])`＝10（前导数值串：Warning 后计入 5）。
        const classified = classifyArrayNumElem("array_product", "Multiplication", entry.value_ptr.*);
        switch (classified) {
            .skip => {},
            .use => |v| {
                product *= v.toFloat();
            },
        }
    }

    // 如果结果是整数，返回整数
    if (@floor(product) == product and product >= @as(f64, @floatFromInt(std.math.minInt(i64))) and product <= @as(f64, @floatFromInt(std.math.maxInt(i64)))) {
        return Value.initInt(@intFromFloat(product));
    }
    return Value.initFloat(product);
}

/// array_reverse - 反转数组
pub fn php_array_reverse(arr: Value, preserve_keys_val: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initArray(try PHPArray.init(allocator));

    // ★F-149（R-238）：#2 bool $preserve_keys
    const pk_ok = requireBoolParam("array_reverse", 2, "preserve_keys", preserve_keys_val) orelse return Value.initNull();

    const php_arr = arr.asArray();
    const result = try PHPArray.init(allocator);
    const preserve_keys = pk_ok.toBool();

    if (preserve_keys) {
        // 保留原始键名
        var entries = std.ArrayListUnmanaged(struct { key: ArrayKey, val: Value }){ .items = &.{}, .capacity = 0 };
        defer entries.deinit(allocator);
        var it = php_arr.elements.iterator();
        while (it.next()) |entry| {
            try entries.append(allocator, .{ .key = entry.key_ptr.*, .val = entry.value_ptr.* });
        }
        var i: usize = entries.items.len;
        while (i > 0) {
            i -= 1;
            try result.set(allocator, entries.items[i].key, entries.items[i].val);
        }
    } else {
        // 默认行为：数字键重新索引，字符串键保留
        var entries = std.ArrayListUnmanaged(struct { key: ArrayKey, val: Value }){ .items = &.{}, .capacity = 0 };
        defer entries.deinit(allocator);
        var it = php_arr.elements.iterator();
        while (it.next()) |entry| {
            try entries.append(allocator, .{ .key = entry.key_ptr.*, .val = entry.value_ptr.* });
        }
        var i: usize = entries.items.len;
        while (i > 0) {
            i -= 1;
            const k = entries.items[i].key;
            switch (k) {
                .integer => try result.push(allocator, entries.items[i].val),
                else => try result.set(allocator, k, entries.items[i].val),
            }
        }
    }

    return Value.initArray(result);
}

/// array_unique - 移除数组中的重复值
pub fn php_array_unique(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initArray(try PHPArray.init(allocator));

    const php_arr = arr.asArray();
    const result = try PHPArray.init(allocator);

    var it = php_arr.elements.iterator();
    while (it.next()) |entry| {
        const val = entry.value_ptr.*;

        // 检查是否已存在
        var exists = false;
        var result_it = result.elements.iterator();
        while (result_it.next()) |existing| {
            const eq_result = try php_eq(val, existing.value_ptr.*);
            if (eq_result.asBool()) {
                exists = true;
                break;
            }
        }

        if (!exists) {
            try result.set(allocator, entry.key_ptr.*, val);
        }
    }

    return Value.initArray(result);
}

/// array_flip - 交换数组的键和值
pub fn php_array_flip(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initArray(try PHPArray.init(allocator));

    const php_arr = arr.asArray();
    const result = try PHPArray.init(allocator);

    var it = php_arr.elements.iterator();
    while (it.next()) |entry| {
        const val = entry.value_ptr.*;
        const key = entry.key_ptr.*;

        // 值变成键，键变成值
        // PHP 语义：数字字符串键需规范化为整数键（与数组赋值/查找一致）
        if (val.isInt()) {
            try result.set(allocator, .{ .integer = val.asInt() }, switch (key) {
                .integer => |k| Value.initInt(k),
                .string => |k| Value.initString(k),
            });
        } else if (val.isString()) {
            const new_key = normalizeArrayKeyFromValue(val);
            try result.set(allocator, new_key, switch (key) {
                .integer => |k| Value.initInt(k),
                .string => |k| Value.initString(k),
            });
        }
    }

    return Value.initArray(result);
}

/// array_key_exists - 检查数组中是否存在指定的键
pub fn php_array_key_exists(key: Value, arr: Value) !Value {
    if (!arr.isArray()) return Value.initBool(false);
    if (key.isNull()) {
        emitDeprecated("Using null as the key parameter for array_key_exists() is deprecated, use an empty string instead");
    }

    const php_arr = arr.asArray();
    return Value.initBool(php_arr.get(normalizeArrayKeyFromValue(key)) != null);
}

/// array_key_first - 获取数组的第一个键
pub fn php_array_key_first(arr: Value) !Value {
    if (!arr.isArray()) return Value.initNull();

    const php_arr = arr.asArray();
    var it = php_arr.elements.iterator();

    if (it.next()) |entry| {
        return switch (entry.key_ptr.*) {
            .integer => |k| Value.initInt(k),
            .string => |k| blk: {
                k.retain();
                break :blk Value.initString(k);
            },
        };
    }

    return Value.initNull();
}

/// array_key_last - 获取数组的最后一个键
pub fn php_array_key_last(arr: Value) !Value {
    if (!arr.isArray()) return Value.initNull();

    const php_arr = arr.asArray();
    var last_key: ?ArrayKey = null;

    var it = php_arr.elements.iterator();
    while (it.next()) |entry| {
        last_key = entry.key_ptr.*;
    }

    if (last_key) |key| {
        return switch (key) {
            .integer => |k| Value.initInt(k),
            .string => |k| blk: {
                k.retain();
                break :blk Value.initString(k);
            },
        };
    }

    return Value.initNull();
}

/// array_fill - 用指定值填充数组
pub fn php_array_fill(start_index: Value, num: Value, value: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b163/b164）：两枚都是必填 int，实测措辞分别用**形参名** `$start_index`(#1)／`$count`(#2)。
    //   ★只接类型拒，符号语义不动：b176（`array_fill(-2, 3, "z")`）是**反向守卫**，负 start_index 合法；
    //   而负 count 在 PHP 是 `ValueError: array_fill(): Argument #2 ($count) must be greater than or equal to 0`，
    //   现有 `@max(0, …)` 静默夹取属另一枚面（工单 §104.3），本批不随之改。
    const start_ok = requireNumParam("array_fill", 1, "start_index", .int_param, start_index) orelse return Value.initNull();
    const num_ok = requireNumParam("array_fill", 2, "count", .int_param, num) orelse return Value.initNull();

    const result = try PHPArray.init(allocator);

    const start = start_ok.toInt();
    // ★F-126（R-229）：负 count 是 ValueError（原先 @max(0,…) 静默夹取）
    const count = num_ok.toInt();
    if (count < 0) {
        return throwThrowable("ValueError", "array_fill(): Argument #2 ($count) must be greater than or equal to 0", runtime_allocator);
    }

    var i: i64 = 0;
    while (i < count) : (i += 1) {
        // PHP 值语义：array_fill 对数组类型应深拷贝每个元素
        if (value.isArray() and !value.isRef()) {
            const cloned = try value.asArray().cloneDeep(allocator);
            try result.set(allocator, .{ .integer = start + i }, Value.initArray(cloned));
        } else {
            try result.set(allocator, .{ .integer = start + i }, value);
        }
    }

    return Value.initArray(result);
}

/// ★F-164（R-257）：range 数值字符串边界的分类（仅整串为数值串时成立）。
const RangeBoundKind = enum { int_string, float_string, not_numeric };

fn rangeStringBoundKind(data: []const u8) RangeBoundKind {
    if (!isNumericString(data)) return .not_numeric;
    const v = numericPrefixValue(data) orelse return .not_numeric;
    return if (v.isInt()) .int_string else .float_string;
}

/// range - 创建包含指定范围元素的数组
pub fn php_range(start: Value, end: Value, step_val: Value, allocator: Allocator) !Value {
    // ★F-62f（R-255）：#1/#2 `string|int|float`、#3 `int|float`；null 走原口径（F-62f-opt 未发 Deprecated）。
    const start_ok = requireRangeBoundParam("range", 1, "start", start) orelse return Value.initNull();
    const end_ok = requireRangeBoundParam("range", 2, "end", end) orelse return Value.initNull();
    const step_ok = requireOptionalNumParam("range", 3, "step", .num_param, step_val) orelse return Value.initNull();
    const result = try PHPArray.init(allocator);
    const step_is_null = step_ok.isNull();
    const step_f: f64 = if (step_is_null) 1.0 else step_ok.toFloat();
    const step_integral = step_f == @trunc(step_f);

    // 字符串范围：单个字符（双数值串 + 非整值步长除外：PHP 走数值浮点路径）
    if (start_ok.isString() and end_ok.isString()) {
        const ss = start_ok.asString().data;
        const es = end_ok.asString().data;
        if (ss.len == 1 and es.len == 1 and !(isNumericString(ss) and isNumericString(es) and !step_integral)) {
            const step: i64 = if (step_ok.isInt()) blk: {
                const s = step_ok.toInt();
                break :blk if (s > 0) s else 1;
            } else 1;
            const sc = ss[0];
            const ec = es[0];
            if (sc <= ec) {
                var c = sc;
                while (c <= ec) : (c += @intCast(step)) {
                    try result.push(allocator, Value.initString(try PHPString.init(allocator, &[_]u8{c})));
                }
            } else {
                var c = sc;
                while (c >= ec) : (c -= @intCast(step)) {
                    try result.push(allocator, Value.initString(try PHPString.init(allocator, &[_]u8{c})));
                }
            }
            return Value.initArray(result);
        }
    }

    // ★F-163（R-256）：浮点步长按 PHP 语义取值；整值步长 + 整型边界仍走整数路径。
    if (!step_is_null and step_f == 0.0) {
        throwThrowableDiscardCatch("ValueError", "range(): Argument #3 ($step) cannot be 0", runtime_allocator);
        return Value.initNull();
    }
    const start_f = start_ok.toFloat();
    const end_f = end_ok.toFloat();
    const increasing = start_f <= end_f;
    const span = @abs(end_f - start_f);
    if (span > 0.0) {
        if (increasing and step_f < 0.0) {
            throwThrowableDiscardCatch("ValueError", "range(): Argument #3 ($step) must be greater than 0 for increasing ranges", runtime_allocator);
            return Value.initNull();
        }
        if (@abs(step_f) > span) {
            throwThrowableDiscardCatch("ValueError", "range(): Argument #3 ($step) must be less than the range spanned by argument #1 ($start) and argument #2 ($end)", runtime_allocator);
            return Value.initNull();
        }
    }
    const step_abs = @abs(step_f);
    const step_int_ok = step_abs == @trunc(step_abs) and
        step_abs <= @as(f64, @floatFromInt(std.math.maxInt(i64)));
    // ★F-164（R-257）：数值字符串边界的输出类型——浮点串/浮点边界/非整值步长 ⇒ 浮点元素；
    //   其余（整型、整数字符串、混合）⇒ 整数元素（PHP 实测 "01".."03" 也是 int）。
    const start_kind: RangeBoundKind = if (start_ok.isString()) rangeStringBoundKind(start_ok.asString().data) else .not_numeric;
    const end_kind: RangeBoundKind = if (end_ok.isString()) rangeStringBoundKind(end_ok.asString().data) else .not_numeric;
    const force_float = start_ok.isFloat() or end_ok.isFloat() or
        start_kind == .float_string or end_kind == .float_string;

    if (!force_float and step_int_ok) {
        const start_val = start_ok.toInt();
        const end_val = end_ok.toInt();
        const step: i64 = if (step_abs == 0.0) 1 else @intFromFloat(step_abs);
        if (start_val <= end_val) {
            var i = start_val;
            while (i <= end_val) : (i += step) {
                try result.push(allocator, Value.initInt(i));
            }
        } else {
            var i = start_val;
            while (i >= end_val) : (i -= step) {
                try result.push(allocator, Value.initInt(i));
            }
        }
    } else {
        // PHP 用 start + i*step 的乘法式取值（非逐次累加）：实测 range(1,0,0.3) 末元素 0.10000000000000009。
        const signed_step: f64 = if (increasing) step_abs else -step_abs;
        var idx: u64 = 0;
        while (true) : (idx += 1) {
            const cur = start_f + @as(f64, @floatFromInt(idx)) * signed_step;
            if (increasing) {
                if (!(cur <= end_f)) break;
            } else {
                if (!(cur >= end_f)) break;
            }
            try result.push(allocator, Value.initFloat(cur));
        }
    }

    return Value.initArray(result);
}

fn arrayGetByString(arr: *PHPArray, key_bytes: []const u8) ?Value {
    var it = arr.elements.iterator();
    while (it.next()) |entry| {
        if (entry.key_ptr.* == .string) {
            const s = entry.key_ptr.*.string;
            if (std.mem.eql(u8, s.data, key_bytes)) return entry.value_ptr.*;
        }
    }
    return null;
}

fn arraySetByString(arr: *PHPArray, allocator: Allocator, key_bytes: []const u8, value: Value) !void {
    const s = try PHPString.init(allocator, key_bytes);
    defer s.release(allocator);
    try arr.set(allocator, .{ .string = s }, value);
}

fn valueCompare(a: Value, b: Value, allocator: Allocator) !i64 {
    if ((a.isInt() or a.isFloat() or a.isBool() or a.isNull()) and (b.isInt() or b.isFloat() or b.isBool() or b.isNull())) {
        const af = a.toFloat();
        const bf = b.toFloat();
        if (af < bf) return -1;
        if (af > bf) return 1;
        return 0;
    }

    const as = try a.toString(allocator);
    defer as.release(allocator);
    const bs = try b.toString(allocator);
    defer bs.release(allocator);

    return switch (std.mem.order(u8, as.data, bs.data)) {
        .lt => -1,
        .eq => 0,
        .gt => 1,
    };
}

fn keyCompare(a: ArrayKey, b: ArrayKey) i64 {
    return switch (a) {
        .integer => |ai| switch (b) {
            .integer => |bi| if (ai < bi) -1 else if (ai > bi) 1 else 0,
            .string => -1,
        },
        .string => |as| switch (b) {
            .integer => 1,
            .string => |bs| switch (std.mem.order(u8, as.data, bs.data)) {
                .lt => -1,
                .eq => 0,
                .gt => 1,
            },
        },
    };
}

fn quickSortValues(values: []Value, allocator: Allocator, descending: bool) !void {
    if (values.len < 2) return;

    const pivot = values[values.len / 2];
    var i: usize = 0;
    var j: usize = values.len - 1;

    while (i <= j) {
        while (true) {
            const cmp = try valueCompare(values[i], pivot, allocator);
            if ((!descending and cmp < 0) or (descending and cmp > 0)) {
                i += 1;
                if (i >= values.len) break;
                continue;
            }
            break;
        }
        while (true) {
            const cmp = try valueCompare(values[j], pivot, allocator);
            if ((!descending and cmp > 0) or (descending and cmp < 0)) {
                if (j == 0) break;
                j -= 1;
                continue;
            }
            break;
        }

        if (i <= j) {
            const tmp = values[i];
            values[i] = values[j];
            values[j] = tmp;
            i += 1;
            if (j == 0) break;
            j -= 1;
        }
    }

    if (j > 0) try quickSortValues(values[0 .. j + 1], allocator, descending);
    if (i < values.len) try quickSortValues(values[i..], allocator, descending);
}

const KV = struct { key: ArrayKey, value: Value, orig_idx: usize = 0 };

fn collectEntries(arr: *PHPArray, allocator: Allocator) ![]KV {
    const n = arr.count();
    const items = try allocator.alloc(KV, n);
    var it = arr.elements.iterator();
    var idx: usize = 0;
    while (it.next()) |entry| : (idx += 1) {
        items[idx] = .{ .key = entry.key_ptr.*, .value = entry.value_ptr.*, .orig_idx = idx };
    }
    return items;
}

fn quickSortEntriesByValue(items: []KV, allocator: Allocator, descending: bool) !void {
    if (items.len < 2) return;

    const pivot = items[items.len / 2].value;
    const pivot_idx = items[items.len / 2].orig_idx;
    var i: usize = 0;
    var j: usize = items.len - 1;

    while (i <= j) {
        while (true) {
            const cmp = try valueCompare(items[i].value, pivot, allocator);
            // 稳定排序：值相等时用 orig_idx 做 tiebreaker（低索引在前）
            const effective_cmp = if (cmp == 0)
                (@as(i32, @intCast(items[i].orig_idx)) - @as(i32, @intCast(pivot_idx)))
            else if (descending) -cmp else cmp;
            if (effective_cmp < 0) {
                i += 1;
                if (i >= items.len) break;
                continue;
            }
            break;
        }
        while (true) {
            const cmp = try valueCompare(items[j].value, pivot, allocator);
            const effective_cmp = if (cmp == 0)
                (@as(i32, @intCast(items[j].orig_idx)) - @as(i32, @intCast(pivot_idx)))
            else if (descending) -cmp else cmp;
            if (effective_cmp > 0) {
                if (j == 0) break;
                j -= 1;
                continue;
            }
            break;
        }

        if (i <= j) {
            const tmp = items[i];
            items[i] = items[j];
            items[j] = tmp;
            i += 1;
            if (j == 0) break;
            j -= 1;
        }
    }

    if (j > 0) try quickSortEntriesByValue(items[0 .. j + 1], allocator, descending);
    if (i < items.len) try quickSortEntriesByValue(items[i..], allocator, descending);
}

fn quickSortEntriesByKey(items: []KV, descending: bool) void {
    if (items.len < 2) return;

    const pivot = items[items.len / 2].key;
    var i: usize = 0;
    var j: usize = items.len - 1;

    while (i <= j) {
        while (true) {
            const cmp = keyCompare(items[i].key, pivot);
            if ((!descending and cmp < 0) or (descending and cmp > 0)) {
                i += 1;
                if (i >= items.len) break;
                continue;
            }
            break;
        }
        while (true) {
            const cmp = keyCompare(items[j].key, pivot);
            if ((!descending and cmp > 0) or (descending and cmp < 0)) {
                if (j == 0) break;
                j -= 1;
                continue;
            }
            break;
        }

        if (i <= j) {
            const tmp = items[i];
            items[i] = items[j];
            items[j] = tmp;
            i += 1;
            if (j == 0) break;
            j -= 1;
        }
    }

    if (j > 0) quickSortEntriesByKey(items[0 .. j + 1], descending);
    if (i < items.len) quickSortEntriesByKey(items[i..], descending);
}

pub fn php_sizeof(val: Value) !Value {
    return php_count(val, Value.initInt(0));
}

pub fn php_array_combine(keys: Value, values: Value, allocator: Allocator) !Value {
    if (!keys.isArray() or !values.isArray()) return Value.initBool(false);
    const keys_arr = keys.asArray();
    const values_arr = values.asArray();
    if (keys_arr.count() != values_arr.count()) return Value.initBool(false);

    const result = try PHPArray.init(allocator);
    errdefer result.release(allocator);

    var key_it = keys_arr.elements.iterator();
    var val_it = values_arr.elements.iterator();
    while (key_it.next()) |k_entry| {
        const v_entry = val_it.next().?;
        const k = k_entry.value_ptr.*;
        const v = v_entry.value_ptr.*;
        if (k.isInt()) {
            try result.set(allocator, .{ .integer = k.asInt() }, v);
        } else if (k.isString()) {
            try result.set(allocator, .{ .string = k.asString() }, v);
        } else {
            const ks = try k.toString(allocator);
            defer ks.release(allocator);
            try result.set(allocator, .{ .string = ks }, v);
        }
    }

    return Value.initArray(result);
}

pub fn php_array_pad(arr: Value, pad_size: Value, pad_value: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b162）：形参名实测 **`$length`**，`array_pad(): Argument #2 ($length) must be of type int, Foo given`。
    //   b177（`array_pad([1], -3, 0)`）是**反向守卫**：负 length 在 PHP 是合法前填 ⇒ 只接类型拒，符号语义一律不动。
    const pad_size_ok = requireNumParam("array_pad", 2, "length", .int_param, pad_size) orelse return Value.initNull();
    if (!arr.isArray()) return Value.initNull();
    const php_arr = arr.asArray();
    const n = php_arr.count();
    const target_i = pad_size_ok.toInt();
    const target: usize = @intCast(@abs(target_i));

    const result = try PHPArray.init(allocator);
    errdefer result.release(allocator);

    if (target > n and target_i < 0) {
        var i: usize = 0;
        while (i < target - n) : (i += 1) {
            try result.push(allocator, pad_value);
        }
    }

    var it = php_arr.elements.iterator();
    while (it.next()) |entry| {
        try result.push(allocator, entry.value_ptr.*);
    }

    if (target > n and target_i > 0) {
        var i: usize = 0;
        while (i < target - n) : (i += 1) {
            try result.push(allocator, pad_value);
        }
    }

    return Value.initArray(result);
}

pub fn php_array_intersect(arrays: []const Value, allocator: Allocator) !Value {
    if (arrays.len == 0 or !arrays[0].isArray()) return Value.initArray(try PHPArray.init(allocator));

    const first = arrays[0].asArray();
    const result = try PHPArray.init(allocator);
    errdefer result.release(allocator);

    var it = first.elements.iterator();
    while (it.next()) |entry| {
        const v = entry.value_ptr.*;
        var keep = true;
        for (arrays[1..]) |other_val| {
            if (!other_val.isArray()) {
                keep = false;
                break;
            }
            var found = false;
            var oit = other_val.asArray().elements.iterator();
            while (oit.next()) |oentry| {
                const eq = try php_eq(v, oentry.value_ptr.*);
                if (eq.asBool()) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                keep = false;
                break;
            }
        }
        if (keep) {
            try result.set(allocator, entry.key_ptr.*, v);
        }
    }

    return Value.initArray(result);
}

pub fn php_array_diff(arrays: []const Value, allocator: Allocator) !Value {
    if (arrays.len == 0 or !arrays[0].isArray()) return Value.initArray(try PHPArray.init(allocator));

    const first = arrays[0].asArray();
    const result = try PHPArray.init(allocator);
    errdefer result.release(allocator);

    var it = first.elements.iterator();
    while (it.next()) |entry| {
        const v = entry.value_ptr.*;
        var keep = true;
        for (arrays[1..]) |other_val| {
            if (!other_val.isArray()) continue;
            var oit = other_val.asArray().elements.iterator();
            while (oit.next()) |oentry| {
                const eq = try php_eq(v, oentry.value_ptr.*);
                if (eq.asBool()) {
                    keep = false;
                    break;
                }
            }
            if (!keep) break;
        }
        if (keep) {
            try result.set(allocator, entry.key_ptr.*, v);
        }
    }

    return Value.initArray(result);
}

pub fn php_array_diff_key(arrays: []const Value, allocator: Allocator) !Value {
    if (arrays.len == 0 or !arrays[0].isArray()) return Value.initArray(try PHPArray.init(allocator));

    const first = arrays[0].asArray();
    const result = try PHPArray.init(allocator);
    errdefer result.release(allocator);

    // 遍历第一个数组的所有键值对
    var it = first.elements.iterator();
    while (it.next()) |entry| {
        const key = entry.key_ptr.*;
        const v = entry.value_ptr.*;
        var keep = true;

        // 检查这个键是否在其他数组中存在
        for (arrays[1..]) |other_val| {
            if (!other_val.isArray()) continue;
            const other_arr = other_val.asArray();

            // 如果其他数组中存在相同的键，则不保留
            if (other_arr.elements.get(key)) |_| {
                keep = false;
                break;
            }
        }

        if (keep) {
            try result.set(allocator, key, v);
        }
    }

    return Value.initArray(result);
}

pub fn php_array_intersect_key(arrays: []const Value, allocator: Allocator) !Value {
    if (arrays.len == 0 or !arrays[0].isArray()) return Value.initArray(try PHPArray.init(allocator));

    const first = arrays[0].asArray();
    const result = try PHPArray.init(allocator);
    errdefer result.release(allocator);

    var it = first.elements.iterator();
    while (it.next()) |entry| {
        const key = entry.key_ptr.*;
        const v = entry.value_ptr.*;
        var keep = true;
        for (arrays[1..]) |other_val| {
            if (!other_val.isArray()) {
                keep = false;
                break;
            }
            if (other_val.asArray().elements.get(key) == null) {
                keep = false;
                break;
            }
        }
        if (keep) {
            try result.set(allocator, key, v);
        }
    }

    return Value.initArray(result);
}

pub fn php_array_splice(arr: Value, offset: Value, length: Value, replacement: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b160）：`$offset` 必填 int，实测 `array_splice(): Argument #2 ($offset) must be of type int, Foo given`。
    //   同样置于 by-ref 解引用与 `!isArray()` 早退之前（PHP 先做参数类型检查）。
    const offset_ok = requireNumParam("array_splice", 2, "offset", .int_param, offset) orelse return Value.initNull();
    // 解引用 Ref：by-ref 参数通过 make_ref 传递，arr 可能是 Ref(cell)
    const derefed = if (arr.isRef()) blk: {
        const cell = arr.asRef();
        break :blk cell.*;
    } else arr;
    if (!derefed.isArray()) return Value.initNull();
    const php_arr = derefed.asArray();
    const n = php_arr.count();

    const off_i = offset_ok.toInt();
    const start_idx: usize = blk: {
        if (off_i < 0) {
            const abs_off = @as(usize, @intCast(@abs(off_i)));
            break :blk if (abs_off > n) 0 else n - abs_off;
        }
        break :blk @intCast(@min(off_i, @as(i64, @intCast(n))));
    };

    const delete_count: usize = blk: {
        if (length.isNull()) break :blk n - start_idx;
        const len_i = length.toInt();
        if (len_i >= 0) break :blk @min(@as(usize, @intCast(len_i)), n - start_idx);
        const abs_len = @as(usize, @intCast(@abs(len_i)));
        if (abs_len >= n - start_idx) break :blk 0;
        break :blk (n - start_idx) - abs_len;
    };

    const removed = try PHPArray.init(allocator);
    errdefer removed.release(allocator);

    const items = try collectEntries(php_arr, allocator);
    defer allocator.free(items);

    var rep_values: ?[]Value = null;
    if (!replacement.isNull()) {
        if (replacement.isArray()) {
            const rep_arr = replacement.asArray();
            const rep_n = rep_arr.count();
            const vals = try allocator.alloc(Value, rep_n);
            var rep_it = rep_arr.elements.iterator();
            var ridx: usize = 0;
            while (rep_it.next()) |e| : (ridx += 1) vals[ridx] = e.value_ptr.*;
            rep_values = vals;
        } else {
            const vals = try allocator.alloc(Value, 1);
            vals[0] = replacement;
            rep_values = vals;
        }
    }
    defer if (rep_values) |vals| allocator.free(vals);

    var new_elements = std.ArrayHashMapUnmanaged(ArrayKey, Value, PHPArray.ArrayContext, true){};
    var next_int_key: i64 = 0;

    var idx: usize = 0;
    while (idx < items.len) : (idx += 1) {
        if (idx == start_idx) {
            var r: usize = 0;
            while (r < delete_count) : (r += 1) {
                try removed.push(allocator, items[idx + r].value);
                items[idx + r].value.release(allocator);
                if (items[idx + r].key == .string) {
                    items[idx + r].key.string.release(allocator);
                }
            }

            if (rep_values) |vals| {
                for (vals) |v| {
                    _ = v.retain();
                    try new_elements.put(allocator, .{ .integer = next_int_key }, v);
                    next_int_key += 1;
                }
            }

            idx += delete_count;
            if (idx >= items.len) break;
        }

        const kv = items[idx];
        switch (kv.key) {
            .string => {
                try new_elements.put(allocator, kv.key, kv.value);
            },
            .integer => {
                try new_elements.put(allocator, .{ .integer = next_int_key }, kv.value);
                next_int_key += 1;
            },
        }
    }

    // AOT-SPLICE-001 修复：当 start_idx >= items.len（offset 等于或超过数组长度）时，
    // 主循环中 idx == start_idx 永远不会命中，replacement 值未被插入。
    // 此处补充尾部追加逻辑。
    if (start_idx >= items.len) {
        if (rep_values) |vals| {
            for (vals) |v| {
                _ = v.retain();
                try new_elements.put(allocator, .{ .integer = next_int_key }, v);
                next_int_key += 1;
            }
        }
    }

    php_arr.elements.deinit();
    php_arr.elements = PHPArray.Elements.initMixed(allocator, new_elements);
    php_arr.next_index = next_int_key;

    return Value.initArray(removed);
}

pub fn php_sort(arr: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) {
        const got = valueTypeName(arr);
        emitTypeFatalError("sort", 1, "array", got);
    }
    const php_arr = arr.asArray();

    // 原地排序：直接修改 PHPArray，所有引用均可见排序结果
    const sort_arr = php_arr;

    const n = sort_arr.count();
    var values = try allocator.alloc(Value, n);
    defer allocator.free(values);

    var it = sort_arr.elements.iterator();
    var idx: usize = 0;
    while (it.next()) |entry| : (idx += 1) values[idx] = entry.value_ptr.*;
    try quickSortValues(values, allocator, false);

    var new_elements = std.ArrayHashMapUnmanaged(ArrayKey, Value, PHPArray.ArrayContext, true){};
    var i: usize = 0;
    while (i < values.len) : (i += 1) {
        try new_elements.put(allocator, .{ .integer = @intCast(i) }, values[i]);
    }

    sort_arr.elements.deinit();
    sort_arr.elements = PHPArray.Elements.initMixed(allocator, new_elements);
    sort_arr.next_index = @intCast(values.len);
    return Value.initArray(sort_arr);
}

