// libc 外部声明
extern "c" fn fork() std.posix.pid_t;
extern "c" fn waitpid(
    pid: std.posix.pid_t,
    status: *c_int,
    options: c_int,
) std.posix.pid_t;
extern "c" fn kill(
    pid: std.posix.pid_t,
    sig: c_int,
) c_int;
extern "c" fn alarm(seconds: c_uint) c_uint;
extern "c" fn getpid() std.posix.pid_t;
extern "c" fn signal(
    sig: c_int,
    handler: ?*const fn (c_int) callconv(.c) void,
) ?*const fn (c_int) callconv(.c) void;
extern "c" fn mkfifo(
    path: [*:0]const u8,
    mode: std.posix.mode_t,
) c_int;
extern "c" fn socketpair(
    domain: c_int,
    sock_type: c_int,
    protocol: c_int,
    sv: *[2]c_int,
) c_int;
extern "c" fn close(fd: c_int) c_int;

// System V IPC 外部声明
extern "c" fn msgget(key: c_int, msgflg: c_int) c_int;
extern "c" fn msgctl(
    msqid: c_int,
    cmd: c_int,
    buf: ?*anyopaque,
) c_int;
extern "c" fn semget(
    key: c_int,
    nsems: c_int,
    semflg: c_int,
) c_int;
extern "c" fn semctl(
    semid: c_int,
    semnum: c_int,
    cmd: c_int,
) c_int;
extern "c" fn shmget(
    key: c_int,
    size: usize,
    shmflg: c_int,
) c_int;
extern "c" fn shmctl(
    shmid: c_int,
    cmd: c_int,
    buf: ?*anyopaque,
) c_int;

const IPC_CREAT = 0o1000;
const IPC_RMID = 0;
const MAX_SIGNALS = 32;

var signal_handlers: [MAX_SIGNALS]Value = blk: {
    var arr: [MAX_SIGNALS]Value = undefined;
    for (0..MAX_SIGNALS) |i| arr[i] = Value.initNull();
    break :blk arr;
};
var pending_signals: [MAX_SIGNALS]bool = blk: {
    var arr: [MAX_SIGNALS]bool = undefined;
    for (0..MAX_SIGNALS) |i| arr[i] = false;
    break :blk arr;
};
var last_wait_status: c_int = 0;

/// C 信号处理函数（仅设置标志位）
fn pcntl_c_signal_handler(sig: c_int) callconv(.c) void {
    const s: usize = @intCast(@max(0, sig));
    if (s < MAX_SIGNALS) {
        pending_signals[s] = true;
    }
}

/// pcntl_fork - 创建子进程
pub fn php_pcntl_fork() !Value {
    const pid = fork();
    return Value.initInt(@intCast(pid));
}

/// pcntl_waitpid - 等待指定子进程
pub fn php_pcntl_waitpid(
    pid_val: Value,
    _: Value,
    _: Allocator,
) !Value {
    const pid: std.posix.pid_t = @intCast(pid_val.toInt());
    var status: c_int = 0;
    const result = waitpid(pid, &status, 0);
    last_wait_status = status;
    return Value.initInt(@intCast(result));
}

/// pcntl_wait - 等待任意子进程
pub fn php_pcntl_wait(_: Value, _: Allocator) !Value {
    var status: c_int = 0;
    const result = waitpid(-1, &status, 0);
    last_wait_status = status;
    return Value.initInt(@intCast(result));
}

/// pcntl_wexitstatus - 提取子进程退出码
pub fn php_pcntl_wexitstatus(_: Value) !Value {
    const exit_code = (last_wait_status >> 8) & 0xFF;
    return Value.initInt(@intCast(exit_code));
}

/// pcntl_signal - 注册信号处理器
pub fn php_pcntl_signal(
    signo_val: Value,
    handler_val: Value,
    _: Allocator,
) !Value {
    const signo: usize = @intCast(
        @max(0, signo_val.toInt()),
    );
    if (signo >= MAX_SIGNALS) return Value.initBool(false);
    _ = handler_val.retain();
    signal_handlers[signo].release(runtime_allocator);
    signal_handlers[signo] = handler_val;
    _ = signal(
        @intCast(signo),
        pcntl_c_signal_handler,
    );
    return Value.initBool(true);
}

/// pcntl_signal_dispatch - 分派待处理信号
pub fn php_pcntl_signal_dispatch(_: Allocator) !Value {
    for (0..MAX_SIGNALS) |i| {
        if (pending_signals[i]) {
            pending_signals[i] = false;
            const handler = signal_handlers[i];
            if (!handler.isNull() and handler.isFunction()) {
                const closure = handler.asFunction();
                _ = closure.func(
                    handler,
                    &[_]Value{Value.initInt(@intCast(i))},
                    runtime_allocator,
                ) catch {};
            }
        }
    }
    return Value.initBool(true);
}

/// pcntl_alarm - 设置闹钟信号
pub fn php_pcntl_alarm(seconds_val: Value) !Value {
    const secs: c_uint = @intCast(
        @max(0, seconds_val.toInt()),
    );
    const prev = alarm(secs);
    return Value.initInt(@intCast(prev));
}

/// pcntl_sigprocmask - 设置信号屏蔽字
pub fn php_pcntl_sigprocmask(
    _: Value,
    _: Value,
    _: Allocator,
) !Value {
    return Value.initBool(true);
}

/// posix_getpid - 获取当前进程 ID
pub fn php_posix_getpid() !Value {
    return Value.initInt(@intCast(getpid()));
}

/// posix_kill - 向进程发送信号
pub fn php_posix_kill(
    pid_val: Value,
    sig_val: Value,
) !Value {
    const pid: std.posix.pid_t = @intCast(
        pid_val.toInt(),
    );
    const sig: c_int = @intCast(sig_val.toInt());
    const ret = kill(pid, sig);
    return Value.initBool(ret == 0);
}

/// posix_mkfifo - 创建 FIFO 特殊文件
pub fn php_posix_mkfifo(
    path_val: Value,
    mode_val: Value,
    allocator: Allocator,
) !Value {
    const path_str = try path_val.toString(allocator);
    defer path_str.release(allocator);
    const mode: std.posix.mode_t = @intCast(
        @max(0, mode_val.toInt()),
    );
    const path_z = try allocator.dupeSentinel(u8, path_str.data, 0);
    defer allocator.free(path_z);
    const ret = mkfifo(path_z, mode);
    return Value.initBool(ret == 0);
}

/// ftok - 生成 System V IPC 键值
pub fn php_ftok(
    path_val: Value,
    proj_val: Value,
    allocator: Allocator,
) !Value {
    const path_str = try path_val.toString(allocator);
    defer path_str.release(allocator);
    const proj_str = try proj_val.toString(allocator);
    defer proj_str.release(allocator);
    const proj_id: i64 = if (proj_str.data.len > 0)
        @intCast(proj_str.data[0])
    else
        0;
    // 简化 ftok: 使用路径哈希 + proj_id
    var hash: u32 = 0;
    for (path_str.data) |c| {
        hash = hash *% 31 +% @as(u32, c);
    }
    const key = (@as(i64, proj_id) << 24) |
        @as(i64, hash & 0xFFFFFF);
    return Value.initInt(key);
}

/// msg_get_queue - 获取消息队列
pub fn php_msg_get_queue(
    key_val: Value,
    allocator: Allocator,
) !Value {
    const key: c_int = @intCast(key_val.toInt());
    const id = msgget(key, IPC_CREAT | 0o666);
    if (id < 0) return Value.initBool(false);
    _ = allocator;
    return Value.initInt(@intCast(id));
}

/// msg_remove_queue - 删除消息队列
pub fn php_msg_remove_queue(queue_val: Value) !Value {
    const id: c_int = @intCast(queue_val.toInt());
    const ret = msgctl(id, IPC_RMID, null);
    return Value.initBool(ret == 0);
}

/// sem_get - 获取信号量
pub fn php_sem_get(
    key_val: Value,
    max_val: Value,
    allocator: Allocator,
) !Value {
    _ = allocator;
    const key: c_int = @intCast(key_val.toInt());
    const nsems: c_int = @intCast(
        @max(1, max_val.toInt()),
    );
    const id = semget(key, nsems, IPC_CREAT | 0o666);
    if (id < 0) return Value.initBool(false);
    return Value.initInt(@intCast(id));
}

/// sem_remove - 删除信号量
pub fn php_sem_remove(sem_val: Value) !Value {
    const id: c_int = @intCast(sem_val.toInt());
    const ret = semctl(id, 0, IPC_RMID);
    return Value.initBool(ret == 0);
}

/// shmop_open - 打开共享内存段
pub fn php_shmop_open(
    key_val: Value,
    flags_val: Value,
    mode_val: Value,
    size_val: Value,
    allocator: Allocator,
) !Value {
    _ = allocator;
    _ = flags_val;
    const key: c_int = @intCast(key_val.toInt());
    const mode: c_int = @intCast(
        @max(0, mode_val.toInt()),
    );
    const size: usize = @intCast(
        @max(1, size_val.toInt()),
    );
    const id = shmget(key, size, IPC_CREAT | mode);
    if (id < 0) return Value.initBool(false);
    return Value.initInt(@intCast(id));
}

/// shmop_close - 关闭共享内存段
pub fn php_shmop_close(_: Value) !Value {
    return Value.initBool(true);
}

/// socket_create_pair - 创建套接字对
pub fn php_socket_create_pair(
    domain_val: Value,
    type_val: Value,
    protocol_val: Value,
    _: Value,
    allocator: Allocator,
) !Value {
    const domain: c_int = @intCast(domain_val.toInt());
    const sock_type: c_int = @intCast(
        type_val.toInt(),
    );
    const protocol: c_int = @intCast(
        protocol_val.toInt(),
    );
    var sv: [2]c_int = .{ -1, -1 };
    const ret = socketpair(
        domain,
        sock_type,
        protocol,
        &sv,
    );
    if (ret != 0) return Value.initBool(false);
    const arr = try PHPArray.init(allocator);
    try arr.push(allocator, Value.initInt(sv[0]));
    try arr.push(allocator, Value.initInt(sv[1]));
    return Value.initArray(arr);
}

/// socket_close - 关闭套接字
pub fn php_socket_close(fd_val: Value) !Value {
    const fd: c_int = @intCast(fd_val.toInt());
    _ = close(fd);
    return Value.initBool(true);
}

// ============================================================================
// 高阶数组函数
// ============================================================================

/// array_map - 对一个或多个数组的每个元素应用回调函数
pub fn php_array_map(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return error.InvalidArgumentCount;

    const callback = args[0];
    const arrays = args[1..];
    for (arrays) |arr| {
        if (!arr.isArray()) return error.InvalidArgument;
    }

    const result_arr = try PHPArray.init(allocator);

    if (callback.isNull()) {
        if (arrays.len == 1) {
            const src = arrays[0].asArray();
            var src_iter = src.elements.iterator();
            while (src_iter.next()) |entry| {
                try result_arr.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
            }
            return Value.initArray(result_arr);
        }

        var max_count: i64 = 0;
        for (arrays) |arr| {
            const cur = arr.asArray();
            if (cur.next_index > max_count) max_count = cur.next_index;
        }

        var idx: i64 = 0;
        while (idx < max_count) : (idx += 1) {
            const tuple_arr = try PHPArray.init(allocator);
            const key = ArrayKey{ .integer = idx };

            for (arrays) |arr| {
                const cur = arr.asArray();
                const val = cur.get(key) orelse Value.initNull();
                try tuple_arr.push(allocator, val);
            }

            try result_arr.push(allocator, Value.initArray(tuple_arr));
        }

        return Value.initArray(result_arr);
    }

    const primary = arrays[0].asArray();

    // 预提取所有数组的值列表（按位置索引）
    // PHP array_map 多数组语义：按位置而非键匹配
    const all_values = try allocator.alloc([]Value, arrays.len);
    defer {
        for (all_values) |vals| allocator.free(vals);
        allocator.free(all_values);
    }
    for (arrays, 0..) |arr, ai| {
        const cur = arr.asArray();
        const vals = try allocator.alloc(Value, cur.count());
        var ci: usize = 0;
        var it = cur.elements.iterator();
        while (it.next()) |e| : (ci += 1) {
            vals[ci] = e.value_ptr.*;
        }
        all_values[ai] = vals;
    }

    var iter = primary.elements.iterator();
    var pos: usize = 0;
    while (iter.next()) |entry| {
        var callback_args = try allocator.alloc(Value, arrays.len);
        defer allocator.free(callback_args);

        for (arrays, 0..) |_, ai| {
            if (ai < all_values.len and pos < all_values[ai].len) {
                callback_args[ai] = all_values[ai][pos];
            } else {
                callback_args[ai] = Value.initNull();
            }
        }

        const result_value = try php_invoke_callable(callback, callback_args, allocator);
        try result_arr.set(allocator, entry.key_ptr.*, result_value);
        result_value.release(allocator);
        pos += 1;
    }

    return Value.initArray(result_arr);
}

/// array_filter - 过滤数组元素
/// mode: 0 = 只传值, 1 = 传值和键 (ARRAY_FILTER_USE_BOTH), 2 = 传键 (ARRAY_FILTER_USE_KEY)
pub fn php_array_filter(arr: Value, callback: Value, mode: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();
    const result_arr = try PHPArray.init(allocator);
    const mode_int: u32 = if (mode.isInt()) @intCast(@max(mode.asInt(), 0)) else 0;

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const should_keep = if (callback.isNull()) blk: {
            // 无回调时，检查值是否为真
            break :blk entry.value_ptr.*.toBool();
        } else blk: {
            // 根据mode决定传参方式
            const result = switch (mode_int) {
                0 => blk2: {
                    // ARRAY_FILTER_USE_VALUE (默认) - 只传值
                    const args = [_]Value{entry.value_ptr.*};
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
                1 => blk2: {
                    // ARRAY_FILTER_USE_BOTH - 传值和键
                    const key_val = switch (entry.key_ptr.*) {
                        .integer => |k| Value.initInt(k),
                        .string => |s| blk_s: {
                            s.retain(); // 增加引用计数
                            break :blk_s Value.initString(s);
                        },
                    };
                    const args = [_]Value{ entry.value_ptr.*, key_val };
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
                2 => blk2: {
                    // ARRAY_FILTER_USE_KEY - 只传键
                    const key_val = switch (entry.key_ptr.*) {
                        .integer => |k| Value.initInt(k),
                        .string => |s| blk_s: {
                            s.retain(); // 增加引用计数
                            break :blk_s Value.initString(s);
                        },
                    };
                    const args = [_]Value{key_val};
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
                else => blk2: {
                    // 默认行为：只传值
                    const args = [_]Value{entry.value_ptr.*};
                    break :blk2 try php_invoke_callable(callback, &args, allocator);
                },
            };
            defer result.release(allocator);
            break :blk result.toBool();
        };

        if (should_keep) {
            try result_arr.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
        }
    }

    return Value.initArray(result_arr);
}

/// array_reduce - 使用回调函数迭代地将数组简化为单一值
pub fn php_array_reduce(arr: Value, callback: Value, initial: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();
    var carry = initial.retain();

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const args = [_]Value{ carry, entry.value_ptr.* };
        const new_carry = try php_invoke_callable(callback, &args, allocator);
        carry.release(allocator);
        carry = new_carry;
    }

    return carry;
}

/// array_find - 查找数组中第一个满足回调条件的元素 (PHP 8.4+)
pub fn php_array_find(arr: Value, callback: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initNull();

    const php_arr = arr.asArray();
    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const args = [_]Value{entry.value_ptr.*};
        const result = try php_invoke_callable(callback, &args, allocator);
        defer result.release(allocator);
        if (result.toBool()) {
            return entry.value_ptr.*.retain();
        }
    }
    return Value.initNull();
}

/// array_find_key - PHP 8.4: 返回第一个满足回调的元素的键
pub fn php_array_find_key(arr: Value, callback: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return Value.initNull();
    const php_arr = arr.asArray();
    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const args = [_]Value{entry.value_ptr.*};
        const result = try php_invoke_callable(callback, &args, allocator);
        defer result.release(allocator);
        if (result.toBool()) {
            return switch (entry.key_ptr.*) {
                .int => |k| Value.initInt(k),
                .string => |s| Value.initString(try PHPString.init(allocator, s)),
            };
        }
    }
    return Value.initNull();
}

/// array_chunk - 将数组分割成指定大小的块
/// array_chunk - 将数组分割成指定大小的块
pub fn php_array_chunk(arr: Value, size: Value, preserve_keys: Value, allocator: Allocator) !Value {
    // ★F-62f 接线（门 BLT 段 H b161）：形参名实测是 **`$length`**（不是模板变量名 `size`）——
    //   `array_chunk(): Argument #2 ($length) must be of type int, Foo given`。
    //   ★本臂是 R-194 修前**唯一 `zig_escape=1`** 的来源：修前对象先被 `size.toInt()` 折成 0，
    //   再撞上下面 `chunk_size < 1` 的 `return error.InvalidArgument` ⇒ Zig 错误外逸成 PHP 不可见的失败。
    //   接线的正确位置在早退**之前**，于是 b161 与 escape 同时消失；而 `<1` 那条分支自身是另一枚面（ValueError，工单 §104.3），本批不动。
    const size_ok = requireNumParam("array_chunk", 2, "length", .int_param, size) orelse return Value.initNull();
    if (!arr.isArray()) return error.InvalidArgument;

    const chunk_size = size_ok.toInt();
    // ★F-126（R-229）：length<1 是 ValueError（原先 error.InvalidArgument 外逸）
    if (chunk_size < 1) {
        return throwThrowable("ValueError", "array_chunk(): Argument #2 ($length) must be greater than 0", runtime_allocator);
    }

    const preserve = preserve_keys.toBool();
    const php_arr = arr.asArray();
    const result_arr = try PHPArray.init(allocator);

    var current_chunk = try PHPArray.init(allocator);
    var count: i64 = 0;
    var new_index: i64 = 0;

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        if (preserve) {
            try current_chunk.set(allocator, entry.key_ptr.*, entry.value_ptr.*);
        } else {
            try current_chunk.push(allocator, entry.value_ptr.*);
        }
        count += 1;

        if (count >= chunk_size) {
            try result_arr.set(allocator, .{ .integer = new_index }, Value.initArray(current_chunk));
            new_index += 1;
            current_chunk = try PHPArray.init(allocator);
            count = 0;
        }
    }

    if (count > 0) {
        try result_arr.set(allocator, .{ .integer = new_index }, Value.initArray(current_chunk));
    } else {
        current_chunk.release(allocator);
    }

    return Value.initArray(result_arr);
}

/// array_column - 返回数组中指定列的值
pub fn php_array_column(arr: Value, column_key: Value, index_key: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();
    const result_arr = try PHPArray.init(allocator);

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        const row = entry.value_ptr.*;
        if (!row.isArray()) continue;

        const row_arr = row.asArray();

        // 获取列值
        const col_value = if (column_key.isInt()) blk: {
            break :blk row_arr.get(.{ .integer = column_key.asInt() });
        } else if (column_key.isString()) blk: {
            break :blk arrayGetByString(row_arr, column_key.asString().data);
        } else blk: {
            break :blk null;
        };

        if (col_value) |val| {
            // 确定索引
            if (index_key.isNull()) {
                try result_arr.push(allocator, val);
            } else {
                const idx_value = if (index_key.isInt()) blk: {
                    break :blk row_arr.get(.{ .integer = index_key.asInt() });
                } else if (index_key.isString()) blk: {
                    break :blk arrayGetByString(row_arr, index_key.asString().data);
                } else blk: {
                    break :blk null;
                };

                if (idx_value) |idx| {
                    if (idx.isInt()) {
                        try result_arr.set(allocator, .{ .integer = idx.asInt() }, val);
                    } else if (idx.isString()) {
                        try arraySetByString(result_arr, allocator, idx.asString().data, val);
                    } else {
                        try result_arr.push(allocator, val);
                    }
                } else {
                    try result_arr.push(allocator, val);
                }
            }
        }
    }

    return Value.initArray(result_arr);
}

/// array_walk - 对数组中的每个元素应用用户自定义函数
/// @enhancement AOT超越PHP: 首参数允许数组字面量(PHP解释器报Fatal Error: could not be passed by reference)
pub fn php_array_walk(arr: Value, callback: Value, userdata: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;

    const php_arr = arr.asArray();

    var iter = php_arr.elements.iterator();
    while (iter.next()) |entry| {
        // 构建回调参数：value(by-ref), key, userdata
        const key_val = switch (entry.key_ptr.*) {
            .integer => |k| Value.initInt(k),
            .string => |k| Value.initString(k),
        };

        // array_walk 的回调第一个参数按引用传递（PHP 规范）
        // 直接用 entry.value_ptr 构造 Ref，使回调内对 $value 的赋值写回数组槽位
        // iterator 返回 *const Value，此处需要可写指针以实现引用语义
        var args_buf: [3]Value = undefined;
        // AOT-REF-002 R-1b：引用装槽（make_ref）而非直接锚住迭代期容器槽地址——
        // 回调内扩容会搬迁桶数组，槽地址随之悬垂；装槽后容器槽自身存 Ref，
        // 单元地址恒不变，回调写回经该单元落到容器。
        args_buf[0] = try make_ref(@constCast(entry.value_ptr), allocator);
        args_buf[1] = key_val;
        const arg_count: usize = if (userdata.isNull()) 2 else blk: {
            args_buf[2] = userdata;
            break :blk 3;
        };

        const result = try php_invoke_callable(callback, args_buf[0..arg_count], allocator);
        result.release(allocator);
    }

    return Value.initBool(true);
}

fn php_array_walk_recursive_inner(arr: *PHPArray, callback: Value, userdata: Value, allocator: Allocator) !void {
    var iter = arr.elements.iterator();
    while (iter.next()) |entry| {
        const value = entry.value_ptr.*;
        if (value.isArray()) {
            try php_array_walk_recursive_inner(value.asArray(), callback, userdata, allocator);
            continue;
        }

        const key_val = switch (entry.key_ptr.*) {
            .integer => |k| Value.initInt(k),
            .string => |k| Value.initString(k),
        };

        var args_buf: [3]Value = undefined;
        args_buf[0] = value;
        args_buf[1] = key_val;
        const arg_count: usize = if (userdata.isNull()) 2 else blk: {
            args_buf[2] = userdata;
            break :blk 3;
        };

        const result = try php_invoke_callable(callback, args_buf[0..arg_count], allocator);
        result.release(allocator);
    }
}

/// @enhancement AOT超越PHP: 首参数允许数组字面量(PHP解释器报Fatal Error: could not be passed by reference)
pub fn php_array_walk_recursive(arr: Value, callback: Value, userdata: Value, allocator: Allocator) !Value {
    if (!arr.isArray()) return error.InvalidArgument;
    try php_array_walk_recursive_inner(arr.asArray(), callback, userdata, allocator);
    return Value.initBool(true);
}

// ============================================================================
// 字符串高级函数
// ============================================================================

/// 格式化浮点数到指定精度（用于 sprintf %f）
/// 使用 C 的 snprintf 以匹配 PHP 的浮点舍入行为
extern fn snprintf(buf: [*]u8, size: usize, fmt: [*:0]const u8, ...) c_int;
fn formatFloatPrecision(buf: []u8, val: f64, precision: usize) []const u8 {
    var fmt_buf: [16]u8 = undefined;
    const fmt_str = std.fmt.bufPrintSentinel(&fmt_buf, "%.{d}f", .{precision}, 0) catch "%.6f";
    const len = snprintf(buf.ptr, buf.len, fmt_str.ptr, val);
    if (len > 0 and @as(usize, @intCast(len)) < buf.len) {
        return buf[0..@intCast(len)];
    }
    return std.fmt.bufPrint(buf, "{d:.6}", .{val}) catch "0";
}

/// sprintf - 格式化字符串
pub fn php_sprintf(format: Value, args: []const Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;

    const fmt = format.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    var arg_idx: usize = 0;
    var i: usize = 0;

    while (i < fmt.len) {
        if (fmt[i] == '%' and i + 1 < fmt.len) {
            i += 1;
            if (fmt[i] == '%') {
                try result.append(allocator, '%');
                i += 1;
                continue;
            }

            // 解析位置参数 (n$)
            var explicit_arg_idx: ?usize = null;
            if (i < fmt.len and fmt[i] >= '1' and fmt[i] <= '9') {
                var pos: usize = 0;
                const num_start = i;
                while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                    pos = pos * 10 + (fmt[i] - '0');
                    i += 1;
                }
                if (i < fmt.len and fmt[i] == '$') {
                    explicit_arg_idx = pos - 1; // 转为 0-based
                    i += 1;
                } else {
                    // 不是位置参数，回退
                    i = num_start;
                }
            }

            // 解析标志
            var flag_minus = false;
            var flag_plus = false;
            var flag_space = false;
            var flag_zero = false;
            var pad_char: u8 = ' ';
            while (i < fmt.len) {
                switch (fmt[i]) {
                    '-' => flag_minus = true,
                    '+' => flag_plus = true,
                    ' ' => flag_space = true,
                    '0' => flag_zero = true,
                    '#' => return throwThrowable("ValueError", "Unknown format specifier \"#\"", allocator),
                    '\'' => {
                        // PHP custom pad char: %'x10s
                        i += 1;
                        if (i < fmt.len) {
                            pad_char = fmt[i];
                        }
                    },
                    else => break,
                }
                i += 1;
            }
            if (flag_zero and !flag_minus) pad_char = '0';

            // 解析宽度
            var width: usize = 0;
            while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                width = width * 10 + (fmt[i] - '0');
                i += 1;
            }

            // 解析精度
            var precision: ?usize = null;
            if (i < fmt.len and fmt[i] == '.') {
                i += 1;
                var prec_val: usize = 0;
                while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                    prec_val = prec_val * 10 + (fmt[i] - '0');
                    i += 1;
                }
                precision = prec_val;
            }

            if (i >= fmt.len) break;

            const specifier = fmt[i];
            i += 1;

            // 使用位置参数或顺序参数
            const use_idx = explicit_arg_idx orelse arg_idx;
            if (explicit_arg_idx == null) arg_idx += 1;
            if (use_idx >= args.len) continue;
            const arg = args[use_idx];

            // Format the value into a temporary buffer, then apply width/padding
            var tmp_buf = try std.ArrayList(u8).initCapacity(allocator, 0);
            defer tmp_buf.deinit(allocator);

            switch (specifier) {
                's' => {
                    if (arg.isString()) {
                        const sdata = arg.asString().data;
                        if (precision) |prec| {
                            const len = @min(prec, sdata.len);
                            try tmp_buf.appendSlice(allocator, sdata[0..len]);
                        } else {
                            try tmp_buf.appendSlice(allocator, sdata);
                        }
                    } else {
                        const str = try arg.toString(allocator);
                        defer str.release(allocator);
                        if (precision) |prec| {
                            const len = @min(prec, str.data.len);
                            try tmp_buf.appendSlice(allocator, str.data[0..len]);
                        } else {
                            try tmp_buf.appendSlice(allocator, str.data);
                        }
                    }
                },
                'd', 'i' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    if (flag_plus and val >= 0) try tmp_buf.append(allocator, '+') else if (flag_space and val >= 0) try tmp_buf.append(allocator, ' ');
                    const str = try std.fmt.allocPrint(allocator, "{d}", .{val});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'f' => {
                    const val = arg.toFloat();
                    if (flag_plus and val >= 0) try tmp_buf.append(allocator, '+') else if (flag_space and val >= 0) try tmp_buf.append(allocator, ' ');
                    const prec = precision orelse 6;
                    var fbuf: [128]u8 = undefined;
                    const fstr = formatFloatPrecision(&fbuf, val, prec);
                    try tmp_buf.appendSlice(allocator, fstr);
                },
                'x' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{x}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'X' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{X}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'c' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    // ★F-81（工单 §64.2，根因已由"吞 NUL"改写为此条）：PHP 的 `%c` **恒发 1 字节＝低 8 位**，
                    //   与符号/范围无关（9 枚实测：`0→00`、`65→41`、`255→ff`、`256→00`、`321→41`、`-1→ff`、
                    //   `-255→01`、`-8446744073709551616→00`、`9223372036854775807→ff`）。
                    //   旧守卫 `val >= 0 and val <= 255` 的问题是对范围外**整字节丢弃**；NUL 本身 PHPString 保得住
                    //   （`:1483` 按 `str.len` 全量 memcpy）。★此处一处修四入口：printf/vprintf/vsprintf 都委托 php_sprintf。
                    try tmp_buf.append(allocator, @truncate(@as(u64, @bitCast(val))));
                },
                'u' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const uval: u64 = @bitCast(val);
                    const str = try std.fmt.allocPrint(allocator, "{d}", .{uval});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'o' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{o}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'b' => {
                    const val = castIntArgWithWarn(arg); // ★F-69：sprintf／printf 的 int 族站点（实测 %d %u %x %X %o %b %c 各转换一次 ⇒ 各发一条 Warn）
                    const str = try std.fmt.allocPrint(allocator, "{b}", .{@as(u64, @bitCast(val))});
                    defer allocator.free(str);
                    try tmp_buf.appendSlice(allocator, str);
                },
                'e', 'E' => {
                    const val = arg.toFloat();
                    const prec = precision orelse 6;
                    // PHP %e 格式：[-]d.dddddde[+-]dd
                    var ebuf: [128]u8 = undefined;
                    const abs_val = if (val < 0) -val else val;
                    var exp: i32 = 0;
                    var mantissa = abs_val;
                    if (abs_val >= 1.0) {
                        while (mantissa >= 10.0) : (mantissa /= 10.0) exp += 1;
                    } else if (abs_val > 0.0) {
                        while (mantissa < 1.0) : (mantissa *= 10.0) exp -= 1;
                    }
                    // 格式化尾数
                    var fbuf: [64]u8 = undefined;
                    const fstr = formatFloatPrecision(&fbuf, mantissa, prec);
                    const sign_str = if (val < 0) "-" else if (flag_plus) "+" else if (flag_space) " " else "";
                    const exp_sign = if (exp >= 0) "+" else "-";
                    const exp_abs: u32 = @intCast(if (exp >= 0) exp else -exp);
                    const e_char: u8 = if (specifier == 'E') 'E' else 'e';
                    const formatted = std.fmt.bufPrint(&ebuf, "{s}{s}{c}{s}{d}", .{ sign_str, fstr, e_char, exp_sign, exp_abs }) catch "0";
                    try tmp_buf.appendSlice(allocator, formatted);
                },
                else => {
                    try result.append(allocator, '%');
                    try result.append(allocator, specifier);
                    continue;
                },
            }

            // Apply width padding
            const content = tmp_buf.items;
            if (width > 0 and content.len < width) {
                const padding = width - content.len;
                if (flag_minus) {
                    // Left-align: content first, then padding
                    try result.appendSlice(allocator, content);
                    for (0..padding) |_| try result.append(allocator, pad_char);
                } else {
                    // Right-align: padding first, then content
                    // For zero-padding with sign, put sign before zeros
                    if (pad_char == '0' and content.len > 0 and (content[0] == '-' or content[0] == '+' or content[0] == ' ')) {
                        try result.append(allocator, content[0]);
                        for (0..padding) |_| try result.append(allocator, '0');
                        try result.appendSlice(allocator, content[1..]);
                    } else {
                        for (0..padding) |_| try result.append(allocator, pad_char);
                        try result.appendSlice(allocator, content);
                    }
                }
            } else {
                try result.appendSlice(allocator, content);
            }
        } else {
            try result.append(allocator, fmt[i]);
            i += 1;
        }
    }

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

/// vsprintf - 格式化字符串（参数为数组）
pub fn php_vsprintf(format: Value, args_arr: Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;
    // 将数组参数展开为切片
    if (args_arr.isArray()) {
        const arr = args_arr.asArray();
        const count = arr.count();
        const args = try allocator.alloc(Value, count);
        defer allocator.free(args);
        var iter = arr.elements.iterator();
        var i: usize = 0;
        while (iter.next()) |entry| {
            if (i < count) {
                args[i] = entry.value_ptr.*;
                i += 1;
            }
        }
        return php_sprintf(format, args[0..i], allocator);
    }
    return php_sprintf(format, &[_]Value{}, allocator);
}

pub fn php_sscanf(str: Value, format: Value, allocator: Allocator) !Value {
    if (!str.isString() or !format.isString()) return Value.initBool(false);

    const input = str.asString().data;
    const fmt = format.asString().data;

    var arr = try PHPArray.init(allocator);
    var input_pos: usize = 0;
    var fmt_pos: usize = 0;

    while (fmt_pos < fmt.len and input_pos < input.len) {
        if (fmt[fmt_pos] == '%' and fmt_pos + 1 < fmt.len) {
            fmt_pos += 1;
            const spec = fmt[fmt_pos];
            fmt_pos += 1;

            // 跳过空白
            while (input_pos < input.len and input[input_pos] == ' ') input_pos += 1;

            if (spec == 'd') {
                // 解析整数
                var num: i64 = 0;
                var neg = false;
                if (input_pos < input.len and input[input_pos] == '-') {
                    neg = true;
                    input_pos += 1;
                }
                while (input_pos < input.len and input[input_pos] >= '0' and input[input_pos] <= '9') {
                    num = num * 10 + (input[input_pos] - '0');
                    input_pos += 1;
                }
                if (neg) num = -num;
                try arr.push(allocator, Value.initInt(num));
            } else if (spec == 's') {
                // 解析字符串（到空白）
                const start = input_pos;
                while (input_pos < input.len and input[input_pos] != ' ') input_pos += 1;
                const s = try allocator.dupe(u8, input[start..input_pos]);
                const php_str = try PHPString.init(allocator, s);
                try arr.push(allocator, Value.initString(php_str));
            }
        } else {
            // 匹配字面字符
            if (input_pos < input.len and input[input_pos] == fmt[fmt_pos]) {
                input_pos += 1;
            }
            fmt_pos += 1;
        }
    }

    return Value.initArray(arr);
}

/// preg_match / preg_match_all 的 offset 形参折算（PHP 8.5.8 实测）：
///   null 或 <=0 视为 0；超出 subject 长度时调用返回 false 且 matches 置空数组。
fn pcreSearchOffset(offset: Value, subject_len: usize) struct { start: usize, out_of_range: bool } {
    if (offset.isNull()) return .{ .start = 0, .out_of_range = false };
    const raw = offset.toInt();
    if (raw <= 0) return .{ .start = 0, .out_of_range = false };
    const as_len: usize = @intCast(raw);
    if (as_len > subject_len) return .{ .start = as_len, .out_of_range = true };
    return .{ .start = as_len, .out_of_range = false };
}

pub fn php_preg_match(pattern: Value, subject: Value, matches: *Value, flags: Value, offset: Value, allocator: Allocator) !Value {
    // ★F-62f 余量（R-232）：#4 flags／#5 offset 必为 int（Foo ⇒ TypeError，先于 PREG_* 域检查）
    const flags_ok = requireOptionalNumParam("preg_match", 4, "flags", .int_param, flags) orelse return Value.initBool(false);
    const offset_ok = requireOptionalNumParam("preg_match", 5, "offset", .int_param, offset) orelse return Value.initBool(false);
    const flags_val: i64 = if (flags_ok.isNull()) 0 else flags_ok.toInt();
    if (pregMatchFlagsInvalid(flags_val)) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        throwThrowableDiscardCatch("ValueError", "preg_match(): Argument #4 ($flags) must be a PREG_* constant", allocator);
        return Value.initBool(false);
    }
    const offset_capture = (flags_val & PREG_OFFSET_CAPTURE_BIT) != 0;
    const unmatched_as_null = (flags_val & PREG_UNMATCHED_AS_NULL_BIT) != 0;

    if (!pattern.isString() or !subject.isString()) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initInt(0);
    }

    const pattern_str = pattern.asString();
    const subject_str = subject.asString();
    const parsed = parsePHPRegexPattern(pattern_str.data);
    // ★F-50（R-163）：非法分隔符/修饰符 ⇒ 按 PHP 口径发 Warning 后返回 false，不进 PCRE。
    //   出参槽按本文件既有早退支装成空数组；★实测 PHP 在告警路径上**保留调用者预置值**，本仓因按引用实参未初始化而做不到 ⇒ 另立 F-53。
    if (parsed.issue != .none) {
        emitRegexPatternWarning("preg_match", parsed);
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initBool(false);
    }

    // 使用缓存获取编译后的正则
    // ★F-79d：本文件内另有 `preg_match` 的孪生实现（builtin_map 重复键，工单 §66.2-2/§70.2）⇒
    //   **两侧必须同语义**，否则"哪一行活着"会决定这里是否报警。
    const re = compileRegexOrWarn("preg_match", parsed, allocator) orelse {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initBool(false);
    };

    const off = pcreSearchOffset(offset_ok, subject_str.length);
    if (off.out_of_range) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initBool(false);
    }

    const match_data = pcre2_match_data_create_from_pattern_8(re, null) orelse {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initInt(0);
    };
    defer pcre2_match_data_free_8(match_data);

    const rc = pcre2_match_8(
        re,
        subject_str.data.ptr,
        subject_str.length,
        @intCast(off.start),
        0,
        match_data,
        null,
    );
    recordPcreMatchResult(rc);

    if (rc == PCRE2_ERROR_NOMATCH) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initInt(0);
    }
    // ★F-90（R-184）：孪生支同语义 ⇒ 真错误 false，出参槽装空数组。
    if (rc < 0) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initBool(false);
    }

    // 填充matches数组
    const matches_arr = try PHPArray.init(allocator);
    const ovec = pcre2_get_ovector_pointer_8(match_data);

    // PHP 口径：默认只到「最高已捕获组」（PCRE2 的 rc 即此值），其间未匹配的组补 ""/null；
    // 带 PREG_UNMATCHED_AS_NULL 时一路补到模式的全部组（实测尾部未匹配组给 null 而非省略）。
    const used_groups: usize = @intCast(rc);
    const group_span = if (unmatched_as_null) pcreGroupSpan(re, used_groups) else used_groups;

    var i: usize = 0;
    while (i < group_span) : (i += 1) {
        const start = ovec[i * 2];
        const end = ovec[i * 2 + 1];
        const unset = start > subject_str.length or end > subject_str.length or start > end;

        // 命名组键在 PHP 里紧随「上一数字键」之后、本组数字键之前（实测序：0, name1, 1, name2, 2）
        if (i > 0) {
            if (pcreGroupNameForGroup(re, i)) |gname| {
                const name_str = try PHPString.init(allocator, gname);
                const named_entry = try pcreCaptureEntry(allocator, subject_str.data, start, end, unset, offset_capture, unmatched_as_null);
                try matches_arr.set(allocator, .{ .string = name_str }, named_entry);
            }
        }
        const entry = try pcreCaptureEntry(allocator, subject_str.data, start, end, unset, offset_capture, unmatched_as_null);
        try matches_arr.push(allocator, entry);
    }

    matches.* = Value.initArray(matches_arr);
    return Value.initInt(1);
}

/// 单次匹配里一个捕获组的原始跨度：先只留偏移，渲染阶段统一走 pcreCaptureEntry，
/// 避免 preg_match 与 preg_match_all 各存一份「未匹配怎么表示」的真相。
const PcreCaptureSpan = struct {
    start: usize,
    end: usize,
    unset: bool,
};

/// preg_split 的一片入表：no_empty 只过滤空文本片；offset_capture 时包成 [文本, 起始下标]。
/// 返回是否真的入表 —— limit 计数沿用既有口径（只计实际产出的片）。
/// `arr` 取 PHPArray.init 的返回值本身（该构造函数返回 `*PHPArray`，故此处形参即指针）。
fn pregSplitPushPiece(
    arr: *PHPArray,
    allocator: Allocator,
    text: []const u8,
    at: usize,
    no_empty: bool,
    offset_capture: bool,
) !bool {
    if (no_empty and text.len == 0) return false;
    if (offset_capture) {
        const pair = try PHPArray.init(allocator);
        try pair.push(allocator, Value.initString(try PHPString.init(allocator, text)));
        try pair.push(allocator, Value.initInt(@intCast(at)));
        try arr.push(allocator, Value.initArray(pair));
    } else {
        try arr.push(allocator, Value.initString(try PHPString.init(allocator, text)));
    }
    return true;
}

/// PREG_PATTERN_ORDER 下某一组的全匹配列（命名键与数字键在 PHP 里是两份独立副本，故各建一次）
fn pcreGroupColumn(
    allocator: Allocator,
    subject: []const u8,
    all_matches: []const std.ArrayListUnmanaged(PcreCaptureSpan),
    group: usize,
    offset_capture: bool,
    unmatched_as_null: bool,
) !*PHPArray {
    const group_arr = try PHPArray.init(allocator);
    for (all_matches) |spans| {
        const span: PcreCaptureSpan = if (group < spans.items.len)
            spans.items[group]
        else
            .{ .start = 0, .end = 0, .unset = true };
        try group_arr.push(allocator, try pcreCaptureEntry(allocator, subject, span.start, span.end, span.unset, offset_capture, unmatched_as_null));
    }
    return group_arr;
}

pub fn php_preg_match_all(pattern: Value, subject: Value, matches: *Value, flags: Value, offset: Value, allocator: Allocator) !Value {
    // ★F-62f 余量（R-232）：#4 flags／#5 offset 必为 int（Foo ⇒ TypeError，先于 PREG_* 域检查）
    const flags_ok = requireOptionalNumParam("preg_match_all", 4, "flags", .int_param, flags) orelse return Value.initBool(false);
    const offset_ok = requireOptionalNumParam("preg_match_all", 5, "offset", .int_param, offset) orelse return Value.initBool(false);
    const flags_val: i64 = if (flags_ok.isNull()) 0 else flags_ok.toInt();
    if (pregMatchAllFlagsInvalid(flags_val)) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        throwThrowableDiscardCatch("ValueError", "preg_match_all(): Argument #4 ($flags) must be a PREG_* constant", allocator);
        return Value.initBool(false);
    }
    const offset_capture = (flags_val & PREG_OFFSET_CAPTURE_BIT) != 0;
    const unmatched_as_null = (flags_val & PREG_UNMATCHED_AS_NULL_BIT) != 0;
    const is_set_order = (flags_val & PREG_SET_ORDER_BIT) != 0;

    if (!pattern.isString() or !subject.isString()) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initInt(0);
    }

    const pattern_str = pattern.asString();
    const subject_str = subject.asString();
    const parsed = parsePHPRegexPattern(pattern_str.data);
    // ★F-50（R-163）：非法分隔符/修饰符 ⇒ 按 PHP 口径发 Warning 后返回 false，不进 PCRE。
    //   出参槽按本文件既有早退支装成空数组；★实测 PHP 在告警路径上**保留调用者预置值**，本仓因按引用实参未初始化而做不到 ⇒ 另立 F-53。
    if (parsed.issue != .none) {
        emitRegexPatternWarning("preg_match_all", parsed);
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initBool(false);
    }

    // 使用缓存获取编译后的正则
    // ★F-79d：同 `preg_match` 孪生支 ⇒ 两侧同语义（§66.2-2 的重复键未决项不因本批改变）
    const re = compileRegexOrWarn("preg_match_all", parsed, allocator) orelse {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initBool(false);
    };

    const off = pcreSearchOffset(offset_ok, subject_str.length);
    if (off.out_of_range) {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initBool(false);
    }

    const match_data = pcre2_match_data_create_from_pattern_8(re, null) orelse {
        matches.* = Value.initArray(try PHPArray.init(allocator));
        return Value.initInt(0);
    };
    defer pcre2_match_data_free_8(match_data);

    // 存储所有匹配（临时）
    var all_matches = std.ArrayListUnmanaged(std.ArrayListUnmanaged(PcreCaptureSpan)){ .items = &.{}, .capacity = 0 };
    defer {
        for (all_matches.items) |*spans| {
            spans.deinit(allocator);
        }
        all_matches.deinit(allocator);
    }

    var match_offset: usize = off.start;
    var match_count: i64 = 0;

    // 循环匹配所有
    while (match_offset <= subject_str.length) {
        const rc = pcre2_match_8(
            re,
            subject_str.data.ptr,
            subject_str.length,
            @intCast(match_offset),
            0,
            match_data,
            null,
        );
        recordPcreMatchResult(rc);

        if (rc == PCRE2_ERROR_NOMATCH) break;
        // ★F-90（R-184）：孪生支同语义（§66.2-2 口径）——真错误 ⇒ 整调用 false。
        //   ★早退安全：`match_data`/`all_matches` 均挂 `defer`。
        if (rc < 0) return Value.initBool(false);

        match_count += 1;
        const ovec = pcre2_get_ovector_pointer_8(match_data);

        // 保存当前匹配的所有组偏移
        var spans = std.ArrayListUnmanaged(PcreCaptureSpan){ .items = &.{}, .capacity = 0 };
        var i: usize = 0;
        while (i < @as(usize, @intCast(rc))) : (i += 1) {
            const start = ovec[i * 2];
            const end = ovec[i * 2 + 1];
            try spans.append(allocator, .{
                .start = start,
                .end = end,
                .unset = start > subject_str.length or end > subject_str.length or start > end,
            });
        }
        try all_matches.append(allocator, spans);

        // 移动到下一个位置
        const match_end = ovec[1];
        if (match_end == match_offset) {
            match_offset += 1; // 避免空匹配无限循环
        } else {
            match_offset = match_end;
        }
    }

    // PREG_SET_ORDER=2: matches[i] = [full_match, group1, group2, ...]
    // PREG_PATTERN_ORDER=1 (默认): matches[0] = [all full matches], matches[1] = [all group1], ...
    const group_span = pcreGroupSpan(re, 1);

    const matches_arr = try PHPArray.init(allocator);

    if (is_set_order) {
        // PREG_SET_ORDER: 每个元素是一个匹配的所有组。
        // 实测：默认按本次匹配实际用到的组数截断（尾部未匹配组省略）；
        //       带 PREG_UNMATCHED_AS_NULL 时补到模式全组数并给 null。
        for (all_matches.items) |spans| {
            const set_arr = try PHPArray.init(allocator);
            const set_span: usize = if (unmatched_as_null) group_span else spans.items.len;
            var g: usize = 0;
            while (g < set_span) : (g += 1) {
                const span: PcreCaptureSpan = if (g < spans.items.len)
                    spans.items[g]
                else
                    .{ .start = 0, .end = 0, .unset = true };
                const entry = try pcreCaptureEntry(allocator, subject_str.data, span.start, span.end, span.unset, offset_capture, unmatched_as_null);
                if (g > 0) {
                    if (pcreGroupNameForGroup(re, g)) |gname| {
                        const name_str = try PHPString.init(allocator, gname);
                        const named_copy = try pcreCaptureEntry(allocator, subject_str.data, span.start, span.end, span.unset, offset_capture, unmatched_as_null);
                        try set_arr.set(allocator, .{ .string = name_str }, named_copy);
                    }
                }
                try set_arr.push(allocator, entry);
            }
            try matches_arr.push(allocator, Value.initArray(set_arr));
        }
    } else {
        // PREG_PATTERN_ORDER：恒按「模式全组数」出行，零匹配也给出 [[], [], ...]（实测）
        var g: usize = 0;
        while (g < group_span) : (g += 1) {
            if (g > 0) {
                if (pcreGroupNameForGroup(re, g)) |gname| {
                    const name_str = try PHPString.init(allocator, gname);
                    const named_column = try pcreGroupColumn(allocator, subject_str.data, all_matches.items, g, offset_capture, unmatched_as_null);
                    try matches_arr.set(allocator, .{ .string = name_str }, Value.initArray(named_column));
                }
            }
            const numeric_column = try pcreGroupColumn(allocator, subject_str.data, all_matches.items, g, offset_capture, unmatched_as_null);
            try matches_arr.push(allocator, Value.initArray(numeric_column));
        }
    }

    matches.* = Value.initArray(matches_arr);
    return Value.initInt(match_count);
}

pub fn php_preg_replace(pattern: Value, replacement: Value, subject: Value, allocator: Allocator) !Value {
    if (!pattern.isString() or !replacement.isString() or !subject.isString())
        return Value.initBool(false);

    const pat = pattern.asString().data;
    const repl = replacement.asString().data;
    const subj = subject.asString().data;

    if (pat.len < 3) return Value.initString(try PHPString.init(allocator, try allocator.dupe(u8, subj)));
    const actual_pat = pat[1 .. pat.len - 1];

    // 简单替换
    var result = try std.ArrayList(u8).initCapacity(allocator, subj.len);
    defer result.deinit(allocator);

    var pos: usize = 0;
    while (pos < subj.len) {
        if (std.mem.indexOf(u8, subj[pos..], actual_pat)) |idx| {
            try result.appendSlice(allocator, subj[pos .. pos + idx]);
            try result.appendSlice(allocator, repl);
            pos += idx + actual_pat.len;
        } else {
            try result.appendSlice(allocator, subj[pos..]);
            break;
        }
    }

    const output = try PHPString.init(allocator, try result.toOwnedSlice(allocator));
    return Value.initString(output);
}

pub fn php_preg_replace_callback(pattern: Value, callback: Value, subject: Value, allocator: Allocator) !Value {
    if (!pattern.isString() or !subject.isString())
        return Value.initBool(false);

    const pattern_str = pattern.asString().data;
    const subject_str = subject.asString().data;

    // 解析 PHP 正则模式
    const parsed = parsePHPRegexPattern(pattern_str);
    // ★F-50（R-163）：非法分隔符/修饰符 ⇒ 按 PHP 口径发 Warning 后返回 null（实测），不进 PCRE
    if (parsed.issue != .none) {
        emitRegexPatternWarning("preg_replace_callback", parsed);
        return Value.initNull();
    }

    // 编译正则表达式
    // ★F-79d：实测 PHP `preg_replace_callback` 编译失败 ⇒ `null` ＋ Warning（旧返回未替换的 subject）
    const re = compileRegexOrWarn("preg_replace_callback", parsed, allocator) orelse return Value.initNull();

    // 创建匹配数据
    const match_data = pcre2_match_data_create_from_pattern_8(re, null) orelse {
        return Value.initString(try PHPString.init(allocator, try allocator.dupe(u8, subject_str)));
    };
    defer pcre2_match_data_free_8(match_data);

    // 准备输出缓冲区
    var result = try std.ArrayList(u8).initCapacity(allocator, subject_str.len * 2);
    defer result.deinit(allocator);

    var subject_offset: usize = 0;
    var replace_count: usize = 0;
    const limit: usize = std.math.maxInt(usize);

    while (subject_offset < subject_str.len and replace_count < limit) {
        const rc = pcre2_match_8(
            re,
            subject_str.ptr,
            subject_str.len,
            @as(c_int, @intCast(subject_offset)),
            0,
            match_data,
            null,
        );
        recordPcreMatchResult(rc);

        if (rc == PCRE2_ERROR_NOMATCH) break;
        // ★F-90（R-184）：真错误 ⇒ 整调用 **null**（`preg_replace_callback` 实测契约）。
        //   ★早退安全：`result` 挂 `defer result.deinit(allocator)`，循环内 `matches_arr` 自挂 defer。
        if (rc < 0) return Value.initNull();

        const ovec = pcre2_get_ovector_pointer_8(match_data);
        const match_start = ovec[0];
        const match_end = ovec[1];

        // 添加匹配前的内容
        if (match_start > subject_offset) {
            try result.appendSlice(allocator, subject_str[subject_offset..match_start]);
        }

        // 构建匹配数组
        const matches_arr = try PHPArray.init(allocator);
        defer matches_arr.release(allocator);

        // 添加所有捕获组
        var i: usize = 0;
        while (i < @as(usize, @intCast(rc))) : (i += 1) {
            const start = ovec[i * 2];
            const end = ovec[i * 2 + 1];
            const match_str = subject_str[start..end];
            const php_str = try PHPString.init(allocator, try allocator.dupe(u8, match_str));
            try matches_arr.push(allocator, Value.initString(php_str));
        }

        // 调用回调函数
        const callback_result = try php_invoke_callable(callback, &[_]Value{Value.initArray(matches_arr)}, allocator);
        defer callback_result.release(allocator);

        // 将回调结果添加到输出
        if (callback_result.isString()) {
            try result.appendSlice(allocator, callback_result.asString().data);
        } else if (callback_result.isInt()) {
            // 处理整数返回值
            const int_val = callback_result.asInt();
            var buf: [32]u8 = undefined;
            const int_str = try std.fmt.bufPrint(&buf, "{d}", .{int_val});
            try result.appendSlice(allocator, int_str);
        } else {
            const str_result = try callback_result.toString(allocator);
            defer str_result.release(allocator);
            try result.appendSlice(allocator, str_result.data);
        }

        subject_offset = match_end;
        replace_count += 1;
    }

    // 添加剩余内容
    if (subject_offset < subject_str.len) {
        try result.appendSlice(allocator, subject_str[subject_offset..]);
    }

    const output = try PHPString.init(allocator, try result.toOwnedSlice(allocator));
    return Value.initString(output);
}

pub fn php_preg_split(pattern: Value, subject: Value, limit_val: Value, flags_val: Value, allocator: Allocator) !Value {
    // 转发到 PCRE2 实现
    return preg_split(pattern, subject, limit_val, flags_val, allocator);
}

/// filter_var - 使用特定的过滤器过滤一个变量
pub fn php_filter_var(value: Value, filter: Value, options: Value, allocator: Allocator) !Value {
    if (!filter.isInt()) return Value.initBool(false);

    const filter_type = filter.asInt();

    // FILTER_VALIDATE_EMAIL = 274
    if (filter_type == 274) {
        if (!value.isString()) return Value.initBool(false);

        const email = value.asString().data;

        // 简单的邮箱验证：必须包含 @ 和 .，且格式合理
        if (email.len < 3) return Value.initBool(false);

        // 查找 @
        const at_pos = std.mem.indexOf(u8, email, "@") orelse return Value.initBool(false);
        if (at_pos == 0 or at_pos == email.len - 1) return Value.initBool(false);

        // @ 后面必须有 .
        const domain = email[at_pos + 1 ..];
        const dot_pos = std.mem.indexOf(u8, domain, ".") orelse return Value.initBool(false);
        if (dot_pos == 0 or dot_pos == domain.len - 1) return Value.initBool(false);

        // 检查是否有多个 @
        if (std.mem.indexOf(u8, email[at_pos + 1 ..], "@") != null) return Value.initBool(false);

        // 验证通过，返回原值
        return value;
    }

    // FILTER_VALIDATE_URL = 273
    if (filter_type == 273) {
        if (!value.isString()) return Value.initBool(false);
        const url = value.asString().data;
        if (url.len < 8) return Value.initBool(false);
        // 必须以 http:// 或 https:// 或 ftp:// 开头
        if (std.mem.startsWith(u8, url, "http://") or std.mem.startsWith(u8, url, "https://") or std.mem.startsWith(u8, url, "ftp://")) {
            // 协议后必须有至少一个字符（域名）
            const scheme_end = std.mem.indexOf(u8, url, "://").? + 3;
            if (scheme_end >= url.len) return Value.initBool(false);
            // 域名部分不能包含空格
            if (std.mem.indexOf(u8, url[scheme_end..], " ") != null) return Value.initBool(false);
            return value;
        }
        return Value.initBool(false);
    }

    // FILTER_VALIDATE_IP = 275
    if (filter_type == 275) {
        if (!value.isString()) return Value.initBool(false);
        const ip = value.asString().data;
        // IPv4 验证：4 段数字，每段 0-255
        var parts = std.mem.splitScalar(u8, ip, '.');
        var count: usize = 0;
        while (parts.next()) |part| {
            count += 1;
            if (count > 4) return Value.initBool(false);
            if (part.len == 0 or part.len > 3) return Value.initBool(false);
            const num = std.fmt.parseInt(u16, part, 10) catch return Value.initBool(false);
            if (num > 255) return Value.initBool(false);
        }
        if (count != 4) return Value.initBool(false);
        return value;
    }

    // FILTER_VALIDATE_INT = 257
    if (filter_type == 257) {
        if (!value.isString() and !value.isInt()) return Value.initBool(false);
        if (value.isInt()) return value;
        const s = value.asString().data;
        _ = std.fmt.parseInt(i64, s, 10) catch return Value.initBool(false);
        return value;
    }

    // FILTER_VALIDATE_FLOAT = 259
    if (filter_type == 259) {
        if (!value.isString() and !value.isFloat() and !value.isInt()) return Value.initBool(false);
        if (value.isFloat() or value.isInt()) return value;
        const s = value.asString().data;
        _ = std.fmt.parseFloat(f64, s) catch return Value.initBool(false);
        return value;
    }

    // FILTER_VALIDATE_BOOLEAN = 258
    if (filter_type == 258) {
        if (value.isBool()) return value;
        if (value.isInt()) return Value.initBool(value.asInt() != 0);
        if (!value.isString()) return Value.initBool(false);
        const s = value.asString().data;
        if (std.ascii.eqlIgnoreCase(s, "true") or std.ascii.eqlIgnoreCase(s, "yes") or std.mem.eql(u8, s, "1") or std.ascii.eqlIgnoreCase(s, "on")) {
            return Value.initBool(true);
        }
        if (std.ascii.eqlIgnoreCase(s, "false") or std.ascii.eqlIgnoreCase(s, "no") or std.mem.eql(u8, s, "0") or std.ascii.eqlIgnoreCase(s, "off") or std.mem.eql(u8, s, "")) {
            return Value.initBool(false);
        }
        return Value.initNull();
    }

    // FILTER_VALIDATE_REGEXP = 272
    if (filter_type == 272) {
        if (!value.isString()) return Value.initBool(false);
        // 从 options 中提取 regexp
        if (options.isNull() or !options.isArray()) return Value.initBool(false);
        const opts_arr = options.asArray();
        const opts_entry = opts_arr.getByValue(Value.initString(PHPString.initStatic("options"))) orelse return Value.initBool(false);
        defer opts_entry.release(runtime_allocator);
        if (!opts_entry.isArray()) return Value.initBool(false);
        const inner_arr = opts_entry.asArray();
        const regexp_entry = inner_arr.getByValue(Value.initString(PHPString.initStatic("regexp"))) orelse return Value.initBool(false);
        defer regexp_entry.release(runtime_allocator);
        if (!regexp_entry.isString()) return Value.initBool(false);
        // 使用 preg_match 进行匹配
        var dummy_matches: Value = Value.initNull();
        const match_result = try preg_match(regexp_entry, value, &dummy_matches, Value.initNull(), Value.initInt(0), allocator);
        if (match_result.isInt() and match_result.asInt() > 0) return value;
        return Value.initBool(false);
    }

    // 其他过滤器类型暂不支持
    return Value.initBool(false);
}

/// htmlspecialchars - 将特殊字符转换为HTML实体
pub fn php_htmlspecialchars(str: Value, flags: Value, encoding: Value, double_encode: Value, allocator: Allocator) !Value {
    _ = flags;
    _ = encoding;
    _ = double_encode;
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    for (input) |c| {
        switch (c) {
            '&' => try result.appendSlice(allocator, "&amp;"),
            '"' => try result.appendSlice(allocator, "&quot;"),
            '\'' => try result.appendSlice(allocator, "&#039;"),
            '<' => try result.appendSlice(allocator, "&lt;"),
            '>' => try result.appendSlice(allocator, "&gt;"),
            else => try result.append(allocator, c),
        }
    }

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

/// htmlentities - 将所有适用的字符转换为HTML实体
pub fn php_htmlentities(str: Value, flags: Value, encoding: Value, double_encode: Value, allocator: Allocator) !Value {
    return php_htmlspecialchars(str, flags, encoding, double_encode, allocator);
}

/// htmlspecialchars_decode - 将HTML实体转换回字符
pub fn php_htmlspecialchars_decode(str: Value, flags: Value, allocator: Allocator) !Value {
    _ = flags;
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    var i: usize = 0;
    while (i < input.len) {
        if (input[i] == '&') {
            if (i + 4 <= input.len and std.mem.eql(u8, input[i .. i + 4], "&lt;")) {
                try result.append(allocator, '<');
                i += 4;
            } else if (i + 4 <= input.len and std.mem.eql(u8, input[i .. i + 4], "&gt;")) {
                try result.append(allocator, '>');
                i += 4;
            } else if (i + 5 <= input.len and std.mem.eql(u8, input[i .. i + 5], "&amp;")) {
                try result.append(allocator, '&');
                i += 5;
            } else if (i + 6 <= input.len and std.mem.eql(u8, input[i .. i + 6], "&quot;")) {
                try result.append(allocator, '"');
                i += 6;
            } else if (i + 6 <= input.len and std.mem.eql(u8, input[i .. i + 6], "&#039;")) {
                try result.append(allocator, '\'');
                i += 6;
            } else {
                try result.append(allocator, input[i]);
                i += 1;
            }
        } else {
            try result.append(allocator, input[i]);
            i += 1;
        }
    }

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

fn wordwrapNextWordLen(input: []const u8, from: usize) usize {
    var i = from;
    while (i < input.len and input[i] == ' ') : (i += 1) {}
    var n: usize = 0;
    while (i < input.len and input[i] != ' ' and input[i] != '\n') : (i += 1) n += 1;
    return n;
}

/// ★F-150：按 PHP 口径硬切超宽段；inclusive 区分“空格/换行处”（切满也发 break）
/// 与“串尾”（恰好宽度不发 break）。返回是否发生过切分。
fn wordwrapCutFlush(
    result: *std.ArrayList(u8),
    allocator: Allocator,
    input: []const u8,
    line_start: *usize,
    end: usize,
    width: usize,
    break_chars: []const u8,
    enabled: bool,
    inclusive: bool,
) !bool {
    if (!enabled) return false;
    var moved = false;
    while (true) {
        const seg = end - line_start.*;
        const hit = if (inclusive) seg >= width else seg > width;
        if (!hit) break;
        try result.appendSlice(allocator, input[line_start.* .. line_start.* + width]);
        try result.appendSlice(allocator, break_chars);
        line_start.* += width;
        moved = true;
    }
    return moved;
}

/// wordwrap - 将字符串按指定长度换行
/// ★F-150（R-239）：按 PHP 8.5.8 实测重写——保留原有空格/空行/换行，cut 时按宽度硬切。
pub fn php_wordwrap(str: Value, width: Value, break_str: Value, cut: Value, allocator: Allocator) !Value {
    // ★F-62f 接线：`$width`（可选 int，PHP 侧默认 75）⇒ 对象/array/坏串必须 TypeError（实测 `Argument #2 ($width) must be of type int`）
    const width_ok = requireOptionalNumParam("wordwrap", 2, "width", .int_param, width) orelse return Value.initNull();
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    const wrap_width: usize = @intCast(@max(1, width_ok.toInt()));
    const break_chars = if (break_str.isString()) break_str.asString().data else "\n";
    // ★F-149（R-238）：#4 bool $cut_long_words（注意 PHP 形参名不是 $cut）
    const cut_ok = requireBoolParam("wordwrap", 4, "cut_long_words", cut) orelse return Value.initNull();
    const force_cut = cut_ok.toBool();

    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);

    var line_start: usize = 0;
    var i: usize = 0;
    while (i < input.len) : (i += 1) {
        if (input[i] == '\n') {
            _ = try wordwrapCutFlush(&result, allocator, input, &line_start, i, wrap_width, break_chars, force_cut, true);
            try result.appendSlice(allocator, input[line_start..i]);
            // 已有换行原样保留（不受 $break 影响；实测 PHP 如此）
            try result.append(allocator, '\n');
            line_start = i + 1;
        } else if (input[i] == ' ') {
            const moved = try wordwrapCutFlush(&result, allocator, input, &line_start, i, wrap_width, break_chars, force_cut, true);
            if (moved and line_start == i) {
                // 恰好切满：该空格被丢弃
                line_start = i + 1;
            } else if (i + 1 >= input.len or input[i + 1] != ' ') {
                const seg = i - line_start;
                const next_len = wordwrapNextWordLen(input, i + 1);
                if (seg > 0 and seg + 1 + next_len > wrap_width) {
                    try result.appendSlice(allocator, input[line_start..i]);
                    try result.appendSlice(allocator, break_chars);
                    line_start = i + 1;
                }
            }
        }
    }

    _ = try wordwrapCutFlush(&result, allocator, input, &line_start, input.len, wrap_width, break_chars, force_cut, false);
    try result.appendSlice(allocator, input[line_start..]);

    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

pub fn php_printf(format: Value, args: []const Value, allocator: Allocator) !Value {
    const out = try php_sprintf(format, args, allocator);
    defer out.release(allocator);
    try php_echo(out);
    if (out.isString()) return Value.initInt(@intCast(out.asString().length));
    return Value.initInt(0);
}

pub fn php_bin2hex(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;
    const input = str.asString().data;
    const hex_len = input.len * 2;
    const hex_str = try allocator.alloc(u8, hex_len);
    defer allocator.free(hex_str);

    const hex_chars = "0123456789abcdef";
    for (input, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, hex_str);
    return Value.initString(php_str);
}

/// 解析十进制字符串为 (负数标记, 整数值, 小数位数)
/// value * 10^(-scale) 即为原始数值
fn parseBcNumber(s: []const u8) struct { neg: bool, value: i128, scale: u32 } {
    var i: usize = 0;
    var neg = false;
    if (i < s.len and (s[i] == '+' or s[i] == '-')) {
        neg = s[i] == '-';
        i += 1;
    }
    var int_part: i128 = 0;
    while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
        int_part = int_part * 10 + @as(i128, s[i] - '0');
    }
    var scale: u32 = 0;
    var frac_value: i128 = 0;
    if (i < s.len and s[i] == '.') {
        i += 1;
        while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {
            frac_value = frac_value * 10 + @as(i128, s[i] - '0');
            scale += 1;
        }
    }
    // 合并整数和小数部分
    var total = int_part;
    var j: u32 = 0;
    while (j < scale) : (j += 1) {
        total = total * 10;
    }
    total += frac_value;
    if (neg) total = -total;
    return .{ .neg = neg, .value = total, .scale = scale };
}

/// 将 bc 数值格式化为字符串，截断到指定小数位
fn formatBcNumber(value: i128, orig_scale: u32, target_scale: u32, allocator: Allocator) !Value {
    // 调整精度：如果 target_scale < orig_scale，需要截断
    var v = value;
    var cur_scale = orig_scale;
    if (target_scale < cur_scale) {
        const diff = cur_scale - target_scale;
        var divisor: i128 = 1;
        var k: u32 = 0;
        while (k < diff) : (k += 1) divisor *= 10;
        v = @divTrunc(v, divisor);
        cur_scale = target_scale;
    } else if (target_scale > cur_scale) {
        const diff = target_scale - cur_scale;
        var multiplier: i128 = 1;
        var k: u32 = 0;
        while (k < diff) : (k += 1) multiplier *= 10;
        v = v * multiplier;
        cur_scale = target_scale;
    }

    var neg = false;
    if (v < 0) {
        neg = true;
        v = -v;
    }

    // 将整数转为字符串
    var buf: [64]u8 = undefined;
    const written = std.fmt.bufPrint(&buf, "{d}", .{v}) catch return Value.initNull();
    const digits = written;

    // 分割整数和小数部分
    var int_str: []const u8 = digits;
    var frac_str: []const u8 = "";
    var frac_buf: [64]u8 = undefined;
    if (cur_scale > 0) {
        if (digits.len > cur_scale) {
            int_str = digits[0 .. digits.len - cur_scale];
            frac_str = digits[digits.len - cur_scale ..];
        } else {
            int_str = "0";
            const leading_zeros = cur_scale - digits.len;
            var pos: usize = 0;
            var z: u32 = 0;
            while (z < leading_zeros) : (z += 1) {
                frac_buf[pos] = '0';
                pos += 1;
            }
            @memcpy(frac_buf[pos .. pos + digits.len], digits);
            pos += digits.len;
            frac_str = frac_buf[0..pos];
        }
    }

    // 组装最终字符串
    var result_buf: [80]u8 = undefined;
    var pos: usize = 0;
    if (neg and v != 0) {
        result_buf[pos] = '-';
        pos += 1;
    }
    @memcpy(result_buf[pos .. pos + int_str.len], int_str);
    pos += int_str.len;
    if (cur_scale > 0) {
        result_buf[pos] = '.';
        pos += 1;
        @memcpy(result_buf[pos .. pos + frac_str.len], frac_str);
        pos += frac_str.len;
    }

    return Value.initString(try PHPString.init(allocator, result_buf[0..pos]));
}

pub fn php_bcadd(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const max_scale = @max(a.scale, b.scale);
    const av = scaleBcValue(a.value, a.scale, max_scale);
    const bv = scaleBcValue(b.value, b.scale, max_scale);
    const result = av + bv;
    return formatBcNumber(result, max_scale, s, allocator);
}

pub fn php_bcsub(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const max_scale = @max(a.scale, b.scale);
    const av = scaleBcValue(a.value, a.scale, max_scale);
    const bv = scaleBcValue(b.value, b.scale, max_scale);
    const result = av - bv;
    return formatBcNumber(result, max_scale, s, allocator);
}

pub fn php_bcmul(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const result = a.value * b.value;
    const result_scale = a.scale + b.scale;
    return formatBcNumber(result, result_scale, s, allocator);
}

pub fn php_bcdiv(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    if (b.value == 0) return Value.initNull();
    // (a.value / 10^a.scale) / (b.value / 10^b.scale) = (a.value * 10^b.scale) / (b.value * 10^a.scale)
    // 要得到 s 位小数: result = (a.value * 10^(s + b.scale)) / (b.value * 10^a.scale)
    const scale_diff: i32 = @as(i32, @intCast(s)) + @as(i32, @intCast(b.scale)) - @as(i32, @intCast(a.scale));
    var av = a.value;
    var bv = b.value;
    if (scale_diff >= 0) {
        var multiplier: i128 = 1;
        var k: i32 = 0;
        while (k < scale_diff) : (k += 1) multiplier *= 10;
        av = av * multiplier;
    } else {
        var divisor: i128 = 1;
        var k: i32 = 0;
        while (k < -scale_diff) : (k += 1) divisor *= 10;
        bv = bv * divisor;
    }
    const result = @divTrunc(av, bv);
    return formatBcNumber(result, s, s, allocator);
}

pub fn php_bcmod(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const av = @divTrunc(a.value, bcPow10(a.scale));
    const bv = @divTrunc(b.value, bcPow10(b.scale));
    if (bv == 0) return Value.initNull();
    const result = @rem(av, bv);
    var buf: [64]u8 = undefined;
    const written = std.fmt.bufPrint(&buf, "{d}", .{result}) catch return Value.initNull();
    return Value.initString(try PHPString.init(allocator, written));
}

pub fn php_bcpow(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const e = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const exp_int = @divTrunc(e.value, bcPow10(e.scale));
    if (exp_int < 0) return Value.initNull();
    var result: i128 = 1;
    var i: i128 = 0;
    while (i < exp_int) : (i += 1) {
        result = result * a.value;
    }
    const result_scale = a.scale * @as(u32, @intCast(exp_int));
    return formatBcNumber(result, result_scale, s, allocator);
}

pub fn php_bcsqrt(args: []const Value, allocator: Allocator) !Value {
    if (args.len < 1) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const s: u32 = if (args.len >= 2 and args[1].isInt()) @intCast(@max(0, args[1].asInt())) else 0;
    if (a.value < 0) return Value.initNull();
    const scaled = scaleBcValue(a.value, a.scale, s * 2);
    if (scaled == 0) return formatBcNumber(0, 0, s, allocator);
    var x: i128 = scaled;
    var prev: i128 = 0;
    var iter: u32 = 0;
    while (iter < 100) : (iter += 1) {
        prev = x;
        x = @divTrunc(x + @divTrunc(scaled, x), 2);
        if (x == prev) break;
    }
    return formatBcNumber(x, s, s, allocator);
}

pub fn php_bccomp(args: []const Value, _: Allocator) !Value {
    if (args.len < 2) return Value.initNull();
    const a = parseBcNumber(args[0].asString().data);
    const b = parseBcNumber(args[1].asString().data);
    const s: u32 = if (args.len >= 3 and args[2].isInt()) @intCast(@max(0, args[2].asInt())) else 0;
    const max_scale = @max(@max(a.scale, b.scale), s);
    const av = scaleBcValue(a.value, a.scale, max_scale);
    const bv = scaleBcValue(b.value, b.scale, max_scale);
    if (av < bv) return Value.initInt(-1);
    if (av > bv) return Value.initInt(1);
    return Value.initInt(0);
}

fn bcPow10(n: u32) i128 {
    var result: i128 = 1;
    var i: u32 = 0;
    while (i < n) : (i += 1) result *= 10;
    return result;
}

fn scaleBcValue(value: i128, from_scale: u32, to_scale: u32) i128 {
    if (to_scale <= from_scale) {
        const diff = from_scale - to_scale;
        return @divTrunc(value, bcPow10(diff));
    }
    const diff = to_scale - from_scale;
    return value * bcPow10(diff);
}

/// pack - 将数据打包为二进制字符串
pub fn php_pack(format: Value, args: []const Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;
    const fmt = format.asString().data;
    var result = try std.ArrayList(u8).initCapacity(allocator, 0);
    defer result.deinit(allocator);
    var arg_idx: usize = 0;
    var i: usize = 0;
    while (i < fmt.len) {
        const code = fmt[i];
        i += 1;
        // 解析重复次数
        var repeat: ?usize = null;
        if (i < fmt.len and fmt[i] == '*') {
            repeat = null; // 使用所有剩余参数
            i += 1;
        } else if (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
            var n: usize = 0;
            while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                n = n * 10 + (fmt[i] - '0');
                i += 1;
            }
            repeat = n;
        }
        switch (code) {
            'a' => {
                // NUL 填充字符串
                const n = repeat orelse 0;
                if (arg_idx < args.len) {
                    const str = try args[arg_idx].toString(allocator);
                    defer str.release(allocator);
                    const data = str.data;
                    const write_len = if (n > 0) @min(data.len, n) else data.len;
                    try result.appendSlice(allocator, data[0..write_len]);
                    if (n > write_len) {
                        try result.appendNTimes(allocator, 0, n - write_len);
                    }
                    arg_idx += 1;
                } else if (n > 0) {
                    try result.appendNTimes(allocator, 0, n);
                }
            },
            'A' => {
                // 空格填充字符串
                const n = repeat orelse 0;
                if (arg_idx < args.len) {
                    const str = try args[arg_idx].toString(allocator);
                    defer str.release(allocator);
                    const data = str.data;
                    const write_len = if (n > 0) @min(data.len, n) else data.len;
                    try result.appendSlice(allocator, data[0..write_len]);
                    if (n > write_len) {
                        try result.appendNTimes(allocator, ' ', n - write_len);
                    }
                    arg_idx += 1;
                } else if (n > 0) {
                    try result.appendNTimes(allocator, ' ', n);
                }
            },
            'C', 'c' => {
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u8 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFF);
                    try result.append(allocator, val);
                    arg_idx += 1;
                }
            },
            'n' => {
                // 16-bit big-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u16 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFF);
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    try result.append(allocator, @intCast(val & 0xFF));
                    arg_idx += 1;
                }
            },
            'v' => {
                // 16-bit little-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u16 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFF);
                    try result.append(allocator, @intCast(val & 0xFF));
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    arg_idx += 1;
                }
            },
            'N' => {
                // 32-bit big-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u32 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFFFFFF);
                    try result.append(allocator, @intCast((val >> 24) & 0xFF));
                    try result.append(allocator, @intCast((val >> 16) & 0xFF));
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    try result.append(allocator, @intCast(val & 0xFF));
                    arg_idx += 1;
                }
            },
            'V' => {
                // 32-bit little-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u32 = @intCast(@as(i64, @truncate(args[arg_idx].toInt())) & 0xFFFFFFFF);
                    try result.append(allocator, @intCast(val & 0xFF));
                    try result.append(allocator, @intCast((val >> 8) & 0xFF));
                    try result.append(allocator, @intCast((val >> 16) & 0xFF));
                    try result.append(allocator, @intCast((val >> 24) & 0xFF));
                    arg_idx += 1;
                }
            },
            'J' => {
                // 64-bit big-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u64 = @bitCast(args[arg_idx].toInt());
                    var b: i32 = 56;
                    while (b >= 0) : (b -= 8) {
                        try result.append(allocator, @intCast((val >> @intCast(b)) & 0xFF));
                    }
                    arg_idx += 1;
                }
            },
            'P' => {
                // 64-bit little-endian unsigned
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: u64 = @bitCast(args[arg_idx].toInt());
                    var b: i32 = 0;
                    while (b < 64) : (b += 8) {
                        try result.append(allocator, @intCast((val >> @intCast(b)) & 0xFF));
                    }
                    arg_idx += 1;
                }
            },
            'f' => {
                // 32-bit float (平台字节序)
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: f32 = @floatCast(args[arg_idx].toFloat());
                    const bytes: [4]u8 = @bitCast(val);
                    try result.appendSlice(allocator, &bytes);
                    arg_idx += 1;
                }
            },
            'd' => {
                // 64-bit double (平台字节序)
                const count = repeat orelse 1;
                for (0..count) |_| {
                    if (arg_idx >= args.len) break;
                    const val: f64 = args[arg_idx].toFloat();
                    const bytes: [8]u8 = @bitCast(val);
                    try result.appendSlice(allocator, &bytes);
                    arg_idx += 1;
                }
            },
            'x' => {
                // NUL 字节
                const count = repeat orelse 1;
                try result.appendNTimes(allocator, 0, count);
            },
            else => {},
        }
    }
    const php_str = try PHPString.init(allocator, result.items);
    return Value.initString(php_str);
}

/// unpack - 从二进制字符串解包数据
pub fn php_unpack(format: Value, data: Value, allocator: Allocator) !Value {
    if (!format.isString()) return error.InvalidArgument;
    if (!data.isString()) return error.InvalidArgument;
    const fmt = format.asString().data;
    const input = data.asString().data;
    const result = try PHPArray.init(allocator);
    var offset: usize = 0;
    var out_idx: usize = 1;
    var i: usize = 0;
    while (i < fmt.len) {
        const code = fmt[i];
        i += 1;
        var repeat: ?usize = null;
        if (i < fmt.len and fmt[i] == '*') {
            repeat = null;
            i += 1;
        } else if (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
            var n: usize = 0;
            while (i < fmt.len and fmt[i] >= '0' and fmt[i] <= '9') {
                n = n * 10 + (fmt[i] - '0');
                i += 1;
            }
            repeat = n;
        }
        switch (code) {
            'A' => {
                const n = repeat orelse (input.len - offset);
                if (offset + n <= input.len) {
                    var slice = input[offset .. offset + n];
                    // 去除尾部空格/NUL
                    while (slice.len > 0 and (slice[slice.len - 1] == 0 or slice[slice.len - 1] == ' ')) {
                        slice = slice[0 .. slice.len - 1];
                    }
                    const php_str = try PHPString.init(allocator, slice);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initString(php_str));
                    out_idx += 1;
                    offset += n;
                }
            },
            'a' => {
                const n = repeat orelse (input.len - offset);
                if (offset + n <= input.len) {
                    var slice = input[offset .. offset + n];
                    while (slice.len > 0 and slice[slice.len - 1] == 0) {
                        slice = slice[0 .. slice.len - 1];
                    }
                    const php_str = try PHPString.init(allocator, slice);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initString(php_str));
                    out_idx += 1;
                    offset += n;
                }
            },
            'C', 'c' => {
                const count = repeat orelse (input.len - offset);
                for (0..count) |_| {
                    if (offset >= input.len) break;
                    const b = input[offset];
                    const val: i64 = if (code == 'c') (if (b & 0x80 != 0) @as(i64, b) - 256 else b) else b;
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(val));
                    out_idx += 1;
                    offset += 1;
                }
            },
            'n' => {
                const count = repeat orelse ((input.len - offset) / 2);
                for (0..count) |_| {
                    if (offset + 2 > input.len) break;
                    const val: u16 = (@as(u16, input[offset]) << 8) | input[offset + 1];
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(val));
                    out_idx += 1;
                    offset += 2;
                }
            },
            'v' => {
                const count = repeat orelse ((input.len - offset) / 2);
                for (0..count) |_| {
                    if (offset + 2 > input.len) break;
                    const val: u16 = input[offset] | (@as(u16, input[offset + 1]) << 8);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(val));
                    out_idx += 1;
                    offset += 2;
                }
            },
            'N' => {
                const count = repeat orelse ((input.len - offset) / 4);
                for (0..count) |_| {
                    if (offset + 4 > input.len) break;
                    const val: u32 = (@as(u32, input[offset]) << 24) | (@as(u32, input[offset + 1]) << 16) | (@as(u32, input[offset + 2]) << 8) | input[offset + 3];
                    // PHP 的 N 格式返回有符号 int（如果最高位为 1 则为负数）
                    const sval: i64 = @intCast(val);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(sval));
                    out_idx += 1;
                    offset += 4;
                }
            },
            'V' => {
                const count = repeat orelse ((input.len - offset) / 4);
                for (0..count) |_| {
                    if (offset + 4 > input.len) break;
                    const val: u32 = input[offset] | (@as(u32, input[offset + 1]) << 8) | (@as(u32, input[offset + 2]) << 16) | (@as(u32, input[offset + 3]) << 24);
                    const sval: i64 = @intCast(val);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(sval));
                    out_idx += 1;
                    offset += 4;
                }
            },
            'J' => {
                const count = repeat orelse ((input.len - offset) / 8);
                for (0..count) |_| {
                    if (offset + 8 > input.len) break;
                    var val: u64 = 0;
                    var b: i32 = 56;
                    while (b >= 0) : (b -= 8) {
                        val = (val << 8) | input[offset + @as(usize, @intCast(@divTrunc(56 - b, 8)))];
                    }
                    offset += 8;
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(@bitCast(val)));
                    out_idx += 1;
                }
            },
            'P' => {
                const count = repeat orelse ((input.len - offset) / 8);
                for (0..count) |_| {
                    if (offset + 8 > input.len) break;
                    var val: u64 = 0;
                    var b: i32 = 0;
                    while (b < 64) : (b += 8) {
                        val |= @as(u64, input[offset + @as(usize, @intCast(@divTrunc(b, 8)))]) << @intCast(b);
                    }
                    offset += 8;
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initInt(@bitCast(val)));
                    out_idx += 1;
                }
            },
            'f' => {
                if (offset + 4 <= input.len) {
                    const bytes: [4]u8 = input[offset .. offset + 4][0..4].*;
                    const val: f32 = @bitCast(bytes);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initFloat(val));
                    out_idx += 1;
                    offset += 4;
                }
            },
            'd' => {
                if (offset + 8 <= input.len) {
                    const bytes: [8]u8 = input[offset .. offset + 8][0..8].*;
                    const val: f64 = @bitCast(bytes);
                    try result.elements.put(.{ .integer = @intCast(out_idx) }, Value.initFloat(val));
                    out_idx += 1;
                    offset += 8;
                }
            },
            else => {},
        }
    }
    return Value.initArray(result);
}

/// decbin - 十进制转二进制
pub fn php_decbin(num: Value, allocator: Allocator) !Value {
    const n = if (num.isInt()) num.asInt() else @as(i64, @intFromFloat(num.asFloat()));
    if (n == 0) {
        const php_str = try PHPString.init(allocator, "0");
        return Value.initString(php_str);
    }

    var abs_n: u64 = if (n < 0) @intCast(-n) else @intCast(n);
    var buf: [64]u8 = undefined;
    var len: usize = 0;

    while (abs_n > 0) : (abs_n >>= 1) {
        buf[63 - len] = if (abs_n & 1 == 1) '1' else '0';
        len += 1;
    }

    const result = buf[64 - len ..];
    const php_str = try PHPString.init(allocator, result);
    return Value.initString(php_str);
}

fn hexCharToInt(c: u8) ?u8 {
    if (c >= '0' and c <= '9') return c - '0';
    if (c >= 'a' and c <= 'f') return c - 'a' + 10;
    if (c >= 'A' and c <= 'F') return c - 'A' + 10;
    return null;
}

pub fn php_hex2bin(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;
    const input = str.asString().data;
    if (input.len % 2 != 0) return Value.initBool(false);

    const bin_len = input.len / 2;
    const bin_str = try allocator.alloc(u8, bin_len);
    defer allocator.free(bin_str);

    for (0..bin_len) |i| {
        const high = hexCharToInt(input[i * 2]) orelse return Value.initBool(false);
        const low = hexCharToInt(input[i * 2 + 1]) orelse return Value.initBool(false);
        bin_str[i] = (high << 4) | low;
    }

    const php_str = try PHPString.init(allocator, bin_str);
    return Value.initString(php_str);
}

// ============================================================================
// 哈希函数
// ============================================================================

/// md5 - 计算字符串的MD5哈希值
pub fn php_md5(str: Value, raw_output: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var hash: [16]u8 = undefined;
    std.crypto.hash.Md5.hash(input, &hash, .{});

    if (raw_output.toBool()) {
        const php_str = try PHPString.init(allocator, &hash);
        return Value.initString(php_str);
    }

    // 转换为十六进制字符串
    var hex_str: [32]u8 = undefined;
    const hex_chars = "0123456789abcdef";
    for (hash, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, &hex_str);
    return Value.initString(php_str);
}

/// sha1 - 计算字符串的SHA1哈希值
pub fn php_sha1(str: Value, raw_output: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var hash: [20]u8 = undefined;
    std.crypto.hash.Sha1.hash(input, &hash, .{});

    if (raw_output.toBool()) {
        const php_str = try PHPString.init(allocator, &hash);
        return Value.initString(php_str);
    }

    // 转换为十六进制字符串
    var hex_str: [40]u8 = undefined;
    const hex_chars = "0123456789abcdef";
    for (hash, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, &hex_str);
    return Value.initString(php_str);
}

/// password_hash - 创建密码哈希
/// 签名: password_hash(password, algo, options = []) — bcrypt（`options['cost']` 生效）
pub fn php_password_hash(password: Value, algo: Value, options_val: Value, allocator: Allocator) !Value {
    const pass_ok = requireStringParamWeak("password_hash", 1, "password", password) orelse return Value.initNull();
    const algo_ok = requireStringOrIntOrNullParam("password_hash", 2, "algo", algo) orelse return Value.initNull();
    const options_ok = requireArrayParam("password_hash", 3, "options", options_val) orelse return Value.initNull();

    // ★F-62f（R-261）／F-168（R-263）：合法算法 = 2y / argon2i / argon2id；bcrypt 与 argon 双实现
    const kind = passwordAlgoKind(algo_ok);
    if (kind == .invalid) {
        return throwThrowable("ValueError", "password_hash(): Argument #2 ($algo) must be a valid password hashing algorithm", runtime_allocator);
    }
    if (kind != .bcrypt) {
        const ap = passwordArgon2Params(options_ok);
        // ★PHP 实测文案与边界：memory ≥8 且 ≥8*p；time ≥1；threads 1..0xFFFFFF
        if (ap.m < 8 or ap.m > 0xFFFFFFFF or ap.m < 8 * ap.p) {
            return throwThrowable("ValueError", "Memory cost is outside of allowed memory range", runtime_allocator);
        }
        if (ap.t < 1 or ap.t > 0xFFFFFFFF) {
            return throwThrowable("ValueError", "Time cost is outside of allowed time range", runtime_allocator);
        }
        if (ap.p < 1 or ap.p > 0xFFFFFF) {
            return throwThrowable("ValueError", "Invalid number of threads", runtime_allocator);
        }

        const pwd_php_argon = try pass_ok.toString(allocator);
        defer pwd_php_argon.release(allocator);
        const mode: std.crypto.pwhash.argon2.Mode = if (kind == .argon2i) .argon2i else .argon2id;
        var argon_buf: [512]u8 = undefined;
        const argon_hash = std.crypto.pwhash.argon2.strHash(pwd_php_argon.data, .{
            .allocator = allocator,
            .params = .{ .t = @intCast(ap.t), .m = @intCast(ap.m), .p = @intCast(ap.p) },
            .mode = mode,
            .encoding = .phc,
        }, &argon_buf, getIo()) catch
            return throwThrowable("ValueError", "password_hash(): Failed to hash password", runtime_allocator);
        return Value.initString(try PHPString.init(allocator, argon_hash));
    }

    // ★PHP 实测：4..31 之外 ⇒ `Invalid bcrypt cost parameter specified: N`（非数值 ⇒ 0）；缺省 12
    const cost_raw = passwordBcryptCost(options_ok);
    if (cost_raw < 4 or cost_raw > 31) {
        var msg_buf: [96]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "Invalid bcrypt cost parameter specified: {d}", .{cost_raw}) catch
            return throwThrowable("ValueError", "Invalid bcrypt cost parameter specified", runtime_allocator);
        return throwThrowable("ValueError", msg, runtime_allocator);
    }
    const cost: u6 = @intCast(cost_raw);

    const pwd_php = try pass_ok.toString(allocator);
    defer pwd_php.release(allocator);
    const pwd = pwd_php.data;

    var hash_buf: [128]u8 = undefined;
    const hash_result = try std.crypto.pwhash.bcrypt.strHash(pwd, .{
        .allocator = allocator,
        .params = .{ .rounds_log = cost, .silently_truncate_password = true },
        .encoding = .crypt,
    }, &hash_buf, getIo());

    // Zig生成$2b$前缀，PHP使用$2y$前缀，替换以保持兼容
    var result_buf: [128]u8 = undefined;
    const result_str = blk: {
        if (hash_result.len >= 4 and hash_result[0] == '$' and hash_result[1] == '2' and hash_result[2] == 'b' and hash_result[3] == '$') {
            result_buf[0] = '$';
            result_buf[1] = '2';
            result_buf[2] = 'y';
            @memcpy(result_buf[3..hash_result.len], hash_result[3..]);
            break :blk result_buf[0..hash_result.len];
        }
        break :blk hash_result;
    };

    const php_str = try PHPString.init(allocator, result_str);
    return Value.initString(php_str);
}

/// password_verify - 验证密码是否匹配哈希
pub fn php_password_verify(password: Value, hash: Value, allocator: Allocator) !Value {
    if (!password.isString() or !hash.isString()) {
        return Value.initBool(false);
    }

    const pwd = password.asString().data;
    const hash_str = hash.asString().data;

    // ★F-168（R-263）：argon2i/id（PHC 编码）走 std 校验
    if (std.mem.startsWith(u8, hash_str, "$argon2i$") or std.mem.startsWith(u8, hash_str, "$argon2id$")) {
        std.crypto.pwhash.argon2.strVerify(hash_str, pwd, .{ .allocator = allocator }, getIo()) catch
            return Value.initBool(false);
        return Value.initBool(true);
    }

    // PHP使用$2y$前缀，Zig期望$2b$前缀，需要转换
    var converted_buf: [128]u8 = undefined;
    const verify_str = blk: {
        if (hash_str.len >= 4 and hash_str[0] == '$' and hash_str[1] == '2' and hash_str[2] == 'y' and hash_str[3] == '$') {
            converted_buf[0] = '$';
            converted_buf[1] = '2';
            converted_buf[2] = 'b';
            if (hash_str.len <= converted_buf.len) {
                @memcpy(converted_buf[3..hash_str.len], hash_str[3..]);
                break :blk converted_buf[0..hash_str.len];
            }
        }
        break :blk hash_str;
    };

    // 使用bcrypt验证
    std.crypto.pwhash.bcrypt.strVerify(verify_str, pwd, .{
        .silently_truncate_password = true,
    }) catch {
        return Value.initBool(false);
    };

    return Value.initBool(true);
}

/// password_get_info - 返回密码哈希的相关信息
pub fn php_password_get_info(hash_val: Value, allocator: Allocator) !Value {
    if (!hash_val.isString()) {
        // 返回未知算法的空info
        const arr = try PHPArray.init(allocator);
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algo")), Value.initNull());
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algoName")), Value.initString(try PHPString.init(allocator, "unknown")));
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "options")), Value.initArray(try PHPArray.init(allocator)));
        return Value.initArray(arr);
    }

    const hash_str = hash_val.asString().data;

    // 检测bcrypt格式: $2y$XX$ 或 $2b$XX$ 或 $2a$XX$
    if (hash_str.len >= 7 and hash_str[0] == '$' and hash_str[1] == '2' and
        (hash_str[2] == 'y' or hash_str[2] == 'b' or hash_str[2] == 'a') and hash_str[3] == '$')
    {
        // 提取cost值: $2y$XX$...
        const cost_str = hash_str[4..6];
        var cost: i64 = 0;
        for (cost_str) |c| {
            if (c >= '0' and c <= '9') {
                cost = cost * 10 + @as(i64, c - '0');
            }
        }

        const options_arr = try PHPArray.init(allocator);
        try options_arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "cost")), Value.initInt(cost));

        const arr = try PHPArray.init(allocator);
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algo")), Value.initString(try PHPString.init(allocator, "2y")));
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algoName")), Value.initString(try PHPString.init(allocator, "bcrypt")));
        try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "options")), Value.initArray(options_arr));
        return Value.initArray(arr);
    }

    // 未知算法
    const arr = try PHPArray.init(allocator);
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algo")), Value.initNull());
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "algoName")), Value.initString(try PHPString.init(allocator, "unknown")));
    try arr.setByValue(allocator, Value.initString(try PHPString.init(allocator, "options")), Value.initArray(try PHPArray.init(allocator)));
    return Value.initArray(arr);
}

/// password_needs_rehash - 检查哈希是否需要重新生成
/// password_needs_rehash(hash, algo, options=[])
pub fn php_password_needs_rehash(hash_val: Value, algo: Value, options_val: Value, allocator: Allocator) !Value {
    const hash_ok = requireStringParamWeak("password_needs_rehash", 1, "hash", hash_val) orelse return Value.initNull();
    const algo_ok = requireStringOrIntOrNullParam("password_needs_rehash", 2, "algo", algo) orelse return Value.initNull();
    const options_ok = requireArrayParam("password_needs_rehash", 3, "options", options_val) orelse return Value.initNull();

    const hash_php = try hash_ok.toString(allocator);
    defer hash_php.release(allocator);
    const hash_str = hash_php.data;

    // ★F-62f（R-261）PHP 实测：无效算法 ⇒ false；F-168（R-263）：argon 比较模式与参数
    const kind = passwordAlgoKind(algo_ok);
    if (kind == .invalid) return Value.initBool(false);
    if (kind != .bcrypt) {
        if (kind == .argon2i) {
            if (!std.mem.startsWith(u8, hash_str, "$argon2i$")) return Value.initBool(true);
        } else {
            if (!std.mem.startsWith(u8, hash_str, "$argon2id$")) return Value.initBool(true);
        }
        const stored = passwordArgon2StoredParams(hash_str) orelse return Value.initBool(true);
        const want = passwordArgon2Params(options_ok);
        return Value.initBool(stored.m != want.m or stored.t != want.t or stored.p != want.p);
    }

    // needs_rehash 的 cost **不校验值域**（PHP 实测 3/100/"abc" 均只是 ⇒ true）
    const target_cost = passwordBcryptCost(options_ok);

    // 检查是否是bcrypt格式
    if (hash_str.len >= 7 and hash_str[0] == '$' and hash_str[1] == '2' and
        (hash_str[2] == 'y' or hash_str[2] == 'b' or hash_str[2] == 'a') and hash_str[3] == '$')
    {
        // 提取cost值
        var cost: i64 = 0;
        if (hash_str[4] >= '0' and hash_str[4] <= '9') cost = cost * 10 + @as(i64, hash_str[4] - '0');
        if (hash_str[5] >= '0' and hash_str[5] <= '9') cost = cost * 10 + @as(i64, hash_str[5] - '0');
        return Value.initBool(cost != target_cost);
    }
    // 不是bcrypt格式，需要rehash
    return Value.initBool(true);
}

pub fn php_uniqid(prefix: Value, more_entropy: Value, allocator: Allocator) !Value {
    const prefix_str = if (prefix.isString()) prefix.asString().data else "";
    const ent = more_entropy.toBool();

    // PHP uniqid format: prefix + 8 hex chars (seconds) + 5 hex chars (microseconds/100)
    const timestamp = nanoTimestamp();
    const now_us = @divTrunc(timestamp, 1000); // nanoseconds to microseconds
    const seconds = @as(u64, @intCast(@divTrunc(now_us, 1_000_000)));
    const microseconds = @as(u64, @intCast(@rem(now_us, 1_000_000)));
    // PHP uses microseconds/100 for the last 5 hex chars
    const usec_part = @divTrunc(microseconds, 10);

    var result_buf: [64]u8 = undefined;
    const formatted = if (ent) blk: {
        // With more_entropy: add .XXXXXXXX (8 random decimal digits)
        var rand_bytes: [4]u8 = undefined;
        getRandomBytes(&rand_bytes);
        const rand_val = @as(u32, rand_bytes[0]) * 16777216 + @as(u32, rand_bytes[1]) * 65536 + @as(u32, rand_bytes[2]) * 256 + rand_bytes[3];
        break :blk try std.fmt.bufPrint(&result_buf, "{s}{x}{x:0>5}.{d:0>8}", .{ prefix_str, seconds, usec_part, rand_val % 100000000 });
    } else try std.fmt.bufPrint(&result_buf, "{s}{x}{x:0>5}", .{ prefix_str, seconds, usec_part });

    const php_str = try PHPString.init(allocator, formatted);
    return Value.initString(php_str);
}

/// sha256 - 计算字符串的SHA256哈希值
pub fn php_sha256(str: Value, allocator: Allocator) !Value {
    if (!str.isString()) return error.InvalidArgument;

    const input = str.asString().data;
    var hash: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(input, &hash, .{});

    // 转换为十六进制字符串
    var hex_str: [64]u8 = undefined;
    const hex_chars = "0123456789abcdef";
    for (hash, 0..) |byte, i| {
        hex_str[i * 2] = hex_chars[byte >> 4];
        hex_str[i * 2 + 1] = hex_chars[byte & 0x0f];
    }

    const php_str = try PHPString.init(allocator, &hex_str);
    return Value.initString(php_str);
}

/// hash - 生成哈希值
// ============================================================================
// ★F-170（R-266）：RIPEMD-160 / RIPEMD-128（Bosselaers 规范；PHP hash/hmac/pbkdf2 同源）
// ============================================================================
const RMD_R160 = [80]u8{
